pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium dead space (10..=20) is partially unusable; moderate penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }
    // Perfect or near-perfect fills are rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (next_item_size as f64) * 0.2;
    }
    // If next item does NOT fit post-residual, penalize slightly (dead space for future).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 12.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: discourage spreading across many open bins when residuals are large.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins are crowded or item is huge.
        let crowded = (mean_residual / bin_capacity as f64) < 0.35;
        let big_item = item_size > 70;
        if crowded || big_item {
            score -= 20.0;
        } else {
            score += 30.0;
        }
    } else {
        score += (open_bins_count as f64) * 1.5;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.1;

    // Progress-based nudge: later in the stream, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial coupling to stream progress.
    // Early on, larger residuals are tolerated; late in the stream, waste is penalized harder.
    let mut score = norm_pr * (1.0 + 1.5 * progress * progress) * cap;

    // Smooth non-linear interaction: quadratic coupling of post-residual with item fill ratio.
    let fill = item_size as f64 / cap;
    score -= 2.0 * fill * (1.0 - norm_pr) * cap;

    // Penalize dead space that can't fit the lookahead item (smooth soft term).
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 8.0 * gap * gap * cap * (0.5 + progress);
    }

    // Reward using a bin when it is the last chance to fit (avoid opening new bins).
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress * cap * norm_pr;
    }

    // Mild penalty when many bins are open and this placement leaves a mid-range residual
    // (hard-to-fill later) — smooth bump around norm_pr = 0.5.
    let bump = (norm_pr - 0.5) * (norm_pr - 0.5);
    score += (open_bins_count as f64).ln().max(0.0) * 4.0 * bump * cap;

    // Deviation from mean residual: prefer bins below mean residual (tighter packing).
    score += 0.5 * (pr - mean_residual);

    // New-bin candidate: keep it neutral-to-slightly-high unless residual waste is tiny elsewhere.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.3 * progress) + 0.5 * mean_residual;
        if next_item_size > 0 {
            score -= 0.2 * next_item_size as f64 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if next item exactly fits post_residual, strongly reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // dead space relative to next item
            score += 30.0 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare against mean residual: bins with small residual (tight) preferred
    let diff = mean_residual - bin_residual as f64;
    score += 2.0 * diff;

    // Last chance bonus: if only this bin can fit the item, use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalize opening new bins late in stream when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 150.0 + 100.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer using nearly-full bins
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..~15)
    // are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 12 {
        score += (12.0 - post_residual as f64) * 25.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual < next_item_size && post_residual < 12 {
            score += 20.0; // dead space that can't hold the next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: mildly prefer already-open bins over opening new ones.
    score += open_bins_count as f64 * 0.6;

    // Prefer bins with residual below the mean (denser bins) for tight packing.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * -0.5;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any item
    // (min size 1, but small gaps < ~10 are practically unusable) are penalized hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 10.0;
    } else {
        // Reward leaving a gap that many item sizes can still use
        score -= 8.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling: dead space hurts more when the bin pool is already large
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded / mean residual is small
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64);
        score = 120.0 - pressure * 10.0;
        // If the next item could combine with current one in a fresh bin, mild bonus
        if next_item_size > 0 && next_item_size + item_size >= bin_capacity as u32 {
            score -= 15.0;
        }
    }

    // Lookahead: if the post residual exactly accommodates the next item, reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 10.0;
    }

    // Slight late-stream conservatism: prefer filling existing bins as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Perfect lookahead fit: this bin absorbs the next item exactly too.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid
    // abandoning it unless the fit is genuinely tight.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bonus = 20.0 + 25.0 * (1.0 - progress) + 0.15 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if the current fit wastes space.
        score -= new_bin_bonus;
        if post_residual as f64 > mean_residual {
            score += (post_residual as f64 - mean_residual) * 0.5;
        }
    } else {
        // Placing into an existing bin is mildly favored as stream matures.
        score -= 3.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: less leftover relative to item size is good.
    let item_f = item_size as f64;
    let post_f = post_residual as f64;
    score -= (item_f * item_f) / (post_f + 1.0) * 0.5;

    // Strict dead-space avoidance: small unusable gaps are penalized hard.
    let min_useful = 10u32.min(bin_residual); // smallest item that could ever fit
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0 + (min_useful - post_residual) as f64 * 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, encourage filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).powf(1.3) * (0.6 + 0.4 * progress) * 0.8;

    // Prefer bins with residual below mean (fill the emptiest-tightest bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item would fit in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space relative to the actual next item.
        score += (post_residual as f64).powf(1.2) * 0.5;
    }

    // New-bin candidate: make it attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by potential of a fresh bin
        // when existing residuals are small relative to the item.
        score = bin_capacity as f64 * 0.9
            - (mean_residual - item_f).max(0.0) * 2.0
            - (open_bins_count as f64) * 1.5
            - if fitting_bins_count <= 1 { 30.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), but weight by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let gap = post_residual as f64 - next_item_size as f64;
        // Perfect chain (post_residual == next_item_size) is highly desirable.
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize dead space proportional to post_residual.
        score += 0.15 * post_residual as f64;
    }

    // Relative-to-mean residual coupling: placing into a bin with residual below mean
    // consolidates space (good); above mean spreads space (bad).
    score += 0.3 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate: make it attractive only when current fit is very loose
    // (post_residual small-ish items leaving large unusable gaps) and stream is early.
    if bin_residual == bin_capacity {
        let loose = post_residual as f64; // item_size when new bin
        let tightness = 1.0 - (loose / bin_capacity as f64);
        // Penalize new bin by default; discount when item is large (tight new bin)
        // and few bins are open.
        score = 30.0 - 20.0 * tightness - 0.05 * open_bins_count as f64 - 5.0 * progress;
        // If next item is small enough to also chain into a fresh bin, soften penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 6.0;
        }
    }

    // Small penalty for opening bins when many are already open.
    score += 0.02 * open_bins_count as f64;

    score
}

