pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness: squared penalty on wasted space (dead space is quadratic bad).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Reward near-perfect fits strongly.
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead (k=2): if the next item can fit in the post-residual, this bin
    // remains useful -> reward; otherwise penalize leaving awkward leftovers.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else if next_item_size > bin_residual {
            // Next item won't fit here regardless; leftover waste matters less.
            score -= 4.0;
        } else {
            // Dead space trap: residual too small for the known next item.
            score += 15.0;
        }
    }

    // Last chance: this is the only open bin that fits the item.
    // Strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Crowding: many open bins -> encourage filling existing ones rather than
    // spawning more (encourages consolidation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + progress);

    // Relative residual vs mean: prefer bins with less residual than average
    // (use up the emptiest-but-fitting bins first, keep roomy bins flexible).
    score -= (mean_residual - bin_residual as f64) * 0.6;

    // New-bin candidate handling: an empty bin gets a baseline penalty so it is
    // only chosen when all fitting bins have poor scores (large post_residual).
    if bin_residual == bin_capacity {
        score += 55.0 + 20.0 * (1.0 - progress);
        // But if item is large relative to capacity, opening a fresh bin is
        // often fine/needed to avoid fragmenting other bins.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
        // If no open bin fits tightly, new bin is more attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Early stream: keep bins flexible (mild penalty for very tight commits early on).
    if progress < 0.2 && post_residual > 0 && post_residual < 10 {
        score += 8.0 * (1.0 - progress * 5.0);
    }

    score
}

