        score -= 6.0;
    } else {
        // penalize awkward remainders proportionally
        score += post_class as f64 * 0.4;
    }

    // Deep-dead-space penalty: leftover in (0,10) is nearly unusable for items >=10
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect fit is the ideal
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item can exactly fill the post residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item fits into post residual, mild reward scaled by tightness
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't use this leftover: penalize large stranded leftovers
        score += post_residual as f64 * 0.15;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large (harmonic class of item near capacity fractions)
    let item_quot = item_size / 10;
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score += 20.0;
        // large items (>= half capacity) justify a fresh bin more
        if item_size >= bin_capacity / 2 {
            score -= 18.0;
        }
        // if an existing bin would leave a very awkward remainder, new bin wins
        let existing_waste = (bin_residual - item_size) % 10;
        if bin_residual > item_size && existing_waste > 0 && (bin_residual - item_size) < 10 {
            score -= 14.0;
        }
    }

    // Mid-stream: tighten packing as the stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Coupling with mean residual: prefer bins tighter than the fleet average
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Integer-division threshold: bins whose quotient class of residual is low
    // (nearly full bins) get a bonus, encouraging consolidation
    score -= post_quot as f64 * 0.5;

    // Item harmonic class: small items are flexible, slight penalty for wasting
    // a large-capacity residual on a tiny item
    if item_size < 20 && post_quot >= 5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for tiny unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // Reward tight fits (waste near zero).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate: make it costly unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Allow new bin if lookahead item would pair well with the residual this item leaves.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer bins whose residual deviates favorably from the mean (larger residual = easier home).
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Lookahead coupling: if this placement leaves room for the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: reward when the NEXT item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect 2-step match: big bonus; decays with slack.
            score -= 60.0 / (1.0 + slack / 10.0);
        } else {
            // Next item won't fit here: penalize wasted potential,
            // scaled by how close the mismatch is.
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * gap / bin_capacity as f64;
        }
    }

    // Relative-to-mean coupling: bins with residual near mean are neutral;
    // favor bins tighter than mean, penalize unusually loose ones.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate: make it attractive only when the item leaves
    // a large unusable residue in existing bins.
    if bin_residual == bin_capacity {
        // Default: slightly worse than a good existing fit.
        score = (bin_capacity - item_size) as f64 * 0.9;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin also accommodates the next item
        }
        if fitting_bins_count <= 1 {
            score -= 30.0; // poor alternatives: opening a new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    let dead = (post_residual as f64) * (post_residual as f64) / cap;
    score += 1.5 * dead;

    // Lookahead: if the next item fits exactly in the post-residual, strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let gap = post_residual as f64 - nxt;
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            // Next item won't chain here: mild penalty proportional to overflow.
            score += 2.0 * ((nxt - post_residual as f64) / cap).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.05 * (open_bins_count as f64);
    }

    // New-bin candidate handling: prefer existing bins generally; open a new bin
    // only when item is large and current mean residual is small (poor global fit).
    if bin_residual == bin_capacity {
        score += 5.0;
        let pressure = item_size as f64 / mean_residual.max(1.0);
        score -= 10.0 * pressure.min(1.0);
        // Late in the stream, opening fresh bins is cheaper (less fragmentation risk).
        let t = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * t;
    }

    // Reward using bins whose residual is far below the mean (cleaning up laggards).
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= 0.8 * diff;
    }

    // Mild preference to spread load when many bins are open.
    score -= 0.02 * open_bins_count as f64 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress * (1.0 - progress) * 4.0; // peaks mid-stream, smooth
    score -= t * norm_pr * norm_pr * cap * 0.5;
    score += progress * norm_pr * norm_pr * cap * 0.6;
    // Penalize dead space scaled by stream maturity
    score += (norm_pr * norm_pr) * cap * progress * 0.4;
    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * fit_ratio * 10.0;
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // Lookahead: favor bins whose post_residual matches next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= (1.0 - gap / cap) * 8.0;
    } else if next_item_size > 0 {
        score += 6.0;
    }
    // Mild penalty relative to mean residual dispersion
    score += (mean_residual - pr).abs() * 0.05;
    // New-bin candidate handling: keep it slightly unattractive unless residuals are poor
    if bin_residual == bin_capacity {
        score += 3.0 + 20.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction buckets.
    // Buckets (fractions of C=100): (0,0], (0,10], (10,25], (25,50], (50,75], (75,100)
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class index via integer division thresholds (harmonic-style classes)
    let class: f64 = if post_residual == 0 {
        0.0 // perfect fit: strongly reward
    } else if post_residual <= 10 {
        1.0
    } else if post_residual <= 25 {
        2.0
    } else if post_residual <= 50 {
        3.0
    } else if post_residual <= 75 {
        4.0
    } else {
        5.0
    };
    score += class * (c * 0.06);

    // Perfect / near-perfect fits are the ideal outcome.
    if post_residual == 0 {
        score -= c * 1.5;
    } else if post_residual <= 10 {
        score -= c * 0.6;
    }

    // Dead-space penalty: leftover too small for typical future items
    // (items >= 1, but practically most items are sizable; penalize tiny unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += c * 0.25;
    }

    // Lookahead coupling: reward if next item fits exactly into the resulting residual.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if next_item_size == post_residual {
            score -= c * 1.2; // chain fit: excellent
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how tightly the next item nests
            score -= (c * 0.5) * (1.0 - slack / c);
        } else {
            // next item cannot fit here: residual becomes a "harmonic trap" if in a mid class
            if class >= 3.0 && class <= 4.0 {
                score += c * 0.15;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= c * 0.8;
    }

    // Prefer fuller bins relative to the fleet mean residual.
    score -= (mean_residual - pr).max(0.0) * 0.5;
    score += (pr - mean_residual).max(0.0) * 0.3;

    // Late in the stream, tighten packing: penalize leaving large residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * progress * 0.4;

    // New-bin candidate handling: only allow opening a new bin when no open bin offers
    // a good harmonic fit (post_residual in a low class) or when the fleet is crowded.
    if bin_residual == bin_capacity {
        let good_fit_exists = class <= 2.0 && fitting_bins_count > 0;
        if good_fit_exists {
            score += c * 2.0; // keep item in an existing well-fitting bin
        } else if fitting_bins_count == 0 {
            score -= c * 1.0; // must open a new bin
        } else {
            // existing bins fit but poorly; mildly discourage new bin unless fleet is bloated
            if (open_bins_count as f64) > 2.0 + progress * 4.0 {
                score += c * 0.5;
            } else {
                score += c * 0.1;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (< 10) are essentially unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Bonus if the leftover residual can still accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
    }

    // Prefer tighter bins (relative fit quality).
    score += (bin_residual as f64 - item_size as f64).recip() * 5.0;

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect 2-step packing: post_residual exactly matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0;
        } else if diff <= 5 {
            score -= 25.0;
        } else if diff <= 15 {
            score -= 10.0;
        } else {
            // Penalize leaving dead space the next item cannot use.
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }
        // Bonus if the bin can chain both current and next item with tight fit.
        if post_residual >= next_item_size {
            let chain_waste = post_residual - next_item_size;
            score -= (bin_capacity - chain_waste.min(bin_capacity)) as f64 * 0.05;
        }
    }

    // Prefer bins with residuals near the mean (balanced packing), slight pull.
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // Last-chance bonus: only one bin fits the item; avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Early stream: be slightly more aggressive in filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    // New-bin candidate: make it unattractive unless current bin would leave huge waste.
    if bin_residual == bin_capacity {
        score += 5.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer minimal post-residual (tight fit), with non-linear reward.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items (unusable gap).
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 45.0 * (10.0 - gap); // tiny slivers are wasted
        } else if gap < 25.0 {
            score += 12.0; // moderately awkward gap
        }
    }

    // Perfect fit is a jackpot.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 90.0;
        } else if post_residual >= next_item_size {
            // next item fits but leaves another gap: mild reward scaled by fit quality
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack.min(30.0);
        } else {
            // next item will NOT fit here: penalize leaving a gap the next item can't use
            score += 0.35 * ((post_residual as f64) - (next_item_size as f64)).abs();
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 70.0;
        score += 0.5 * post_residual as f64; // but prefer the tightest last-chance fit
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or existing residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // penalize new bins mildly, more when many bins are already open or stream is late
        score += 55.0 + 20.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);
        // but discount the penalty if item is big (fewer future placement options)
        score -= 0.45 * item_size as f64;
        // if existing bins are highly fragmented (mean residual low), new bin is fine
        score -= fragmentation.max(0.0).min(40.0);
    }

    // Global pressure: when many bins are open, conserve them by preferring tight fits more.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * tightness;

    // Mild time-horizon effect: early in the stream, be conservative (slight penalty
    // for filling bins); late, squeeze everything.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 2.0 * progress * progress);

    // Penalize dead space quadratically, weighted by progress
    score += 0.5 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits: subtract when post_residual is small
    score -= (1.0 - norm_pr).powi(2) * 2.0;

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 3.0;
    }

    // Lookahead: penalize if next item cannot use the post-residual
    if next_item_size > 0 {
        if (next_item_size as f64) > pr {
            score += 1.5 * (next_item_size as f64 - pr) / cap;
        } else {
            score -= 0.5 * (pr - next_item_size as f64) / cap;
        }
    }

    // New-bin candidate: prefer opening a new bin early, penalize late
    if bin_residual == bin_capacity {
        score += 1.0 - 2.0 * progress;
    }

    // Mean residual coupling: prefer bins deviating from mean toward tightness
    score += 0.3 * (norm_pr - mean_residual / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small denominations" (0..=10, i.e. near-perfect fills) are highly desirable.
    let class = post_residual / 10; // integer division bucket 0..=10
    match class {
        0 => score -= 60.0,                 // near-perfect fill, big reward
        1 => score -= 25.0,                 // small dead space
        2 => score -= 10.0,                 // moderate
        3 | 4 => score -= 3.0,              // neutral-ish
        5 | 6 => score += 8.0,              // half-empty bins: wasteful
        7 | 8 => score += 15.0,
        _ => score += 25.0,                 // nearly untouched bin
    }

    // Lookahead coupling: if next item fits exactly (or well) into post_residual,
    // reward chaining placements into this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_class = (post_residual - next_item_size) / 10;
        score -= (10 - next_class.min(10)) as f64 * 2.0;
        // exact chain: next item perfectly fills remainder
        if next_item_size == post_residual {
            score -= 40.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here anyway; penalize leaving medium dead space
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bin: only one bin can fit the item; strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    // (large post_residual means we'd barely use it).
    if bin_residual == bin_capacity {
        if post_residual > 50 {
            score += 80.0;  // opening fresh bin for a small item is wasteful
        } else {
            score += 5.0;   // acceptable when item is large
        }
        // fewer open bins relative to progress -> new bin cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (open_bins_count as f64).recip() * 20.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the current mean residual (pack dense bins first).
    score -= (mean_residual - post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: reward heavily.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Dead-space avoidance: small nonzero gaps are nearly unusable.
        let r = post_residual as f64;
        if r < 10.0 {
            score += (10.0 - r) * 30.0; // tiny gaps are worst
        } else if r < 20.0 {
            score += (20.0 - r) * 6.0;
        }
        // Reward residual that could still fit typical items.
        if r >= 50.0 {
            score -= 25.0;
        } else if r >= 30.0 {
            score -= 10.0;
        }
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + next_item_size as f64 * 0.5;
    }
    // Penalize leaving a gap just below next item size (near-miss dead space).
    if next_item_size > 0 && post_residual >= next_item_size.saturating_sub(5) && post_residual < next_item_size && next_item_size >= 10 {
        score += 35.0;
    }

    // Open-bin pressure: with many open bins, consolidate into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual < bin_capacity {
        score -= pressure * 0.5;
    } else {
        // New bin candidate: penalize opening when open bins are underfilled.
        score += pressure * 1.5 + mean_residual * 0.3;
    }

    // Prefer filling bins tighter than the mean residual.
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly matches the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            score -= 60.0; // perfect chain: next item seals this bin
        } else if post_residual >= next_item_size {
            // residual large enough for next item: mild reward scaled by tightness
            let tightness = 1.0 - (post_residual as f64 - next) / bin_capacity as f64;
            score -= 25.0 * tightness;
        } else {
            // next item cannot fit here: penalize stranded dead space, worse if tiny
            score += (next - post_residual as f64) * 0.8;
            if post_residual < 10 {
                score += 15.0; // nearly unusable sliver
            }
        }
        // second-order: if after chaining the next item the remainder is dead
        if post_residual > next_item_size && (post_residual - next_item_size) < 10 {
            score += 8.0;
        }
    }

    // Prefer tight fits generally
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 35.0;
        if item_size >= 50 {
            score += 10.0; // big items deserve fresh bins more
        }
    }

    // Context: many open bins with high mean residual -> encourage consolidation
    if open_bins_count > 2 && mean_residual > 30.0 {
        score += (mean_residual - post_residual as f64).abs() * 0.3;
    }

    // Late in stream: tighten everything, prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Penalize leaving a gap that barely fails the next item.
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            score += 0.3 * gap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item is huge
    // and no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size as f64 > 0.7 * bin_capacity as f64 && fitting_bins_count == 0 {
            score -= 30.0;
        }
        if open_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 && mean_residual > 30.0 {
        score -= 0.2 * mean_residual * (1.0 - progress);
    }

    // Slight preference for fuller bins as stream progresses.
    score -= (bin_capacity - bin_residual) as f64 * 0.1 * progress;

    // Small penalty for spreading across many bins early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    let nb = open_bins_count as f64;
    let mean_r = mean_residual / cap;
    let nxt = next_item_size as f64 / cap;

    // Base: quadratic in normalized post-residual, modulated by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress) + 40.0 * norm_pr * norm_pr;

    // Smooth interaction: small post-residuals become more valuable late in stream.
    score -= 60.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Reward tight fits more when fewer bins can fit the item (last-chance bonus, smooth).
    let scarcity = 1.0 / (1.0 + fit);
    score -= 25.0 * scarcity * (1.0 - norm_pr);

    // Penalize bins whose residual deviates from mean residual (encourage consolidation).
    let dev = (norm_pr - mean_r).abs();
    score += 30.0 * dev * dev * (0.5 + 0.5 * progress);

    // Lookahead: smooth reward if next item could fit into post-residual.
    let lookahead_fit = if nxt > 0.0 { (norm_pr / nxt).min(1.5) } else { 0.0 };
    score -= 20.0 * lookahead_fit * (1.0 - progress);

    // Mild penalty for proliferation of open bins.
    score += 2.0 * nb * (1.0 - progress);

    // New-bin candidate: penalize opening a fresh bin when other bins fit,
    // unless the item is large relative to residual (smooth escape hatch).
    let is_new_bin = (bin_residual == bin_capacity) as f64;
    let large_item = item_size as f64 / cap;
    score += is_new_bin * (30.0 + 40.0 * progress) * (1.0 - large_item * large_item);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of small denominators) are more valuable.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Class A: post_residual divisible by 10 -> perfectly reusable slots
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 12.0;
    }
    // Class B: post_residual divisible by 5 but not 10 -> half-harmonic
    else if post_residual % 5 == 0 {
        score -= 5.0;
    }
    // Class C: dead space - very small leftovers are nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 18.0 + 2.0 * (10 - post_residual) as f64;
    }

    // Integer-division threshold classes on post_residual
    let q = post_residual / 25; // quarter-capacity classes
    match q {
        0 => score += 6.0,   // tiny remnant
        1 => score -= 3.0,   // quarter slot
        2 => score -= 6.0,   // half slot (most flexible)
        3 => score -= 4.0,   // three-quarter slot
        _ => {}              // full/empty bin handled below
    }

    // Lookahead coupling: does post_residual accommodate the next item's harmonic class?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // bonus if next item also leaves a harmonic remainder
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 { score -= 6.0; }
            else if next_post % 5 == 0 { score -= 3.0; }
        } else {
            // this placement kills the bin for the next item
            score += 7.0;
            if post_residual > 0 && post_residual < 10 { score += 6.0; }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize mildly so it's chosen only when
    // open bins all offer poor fits; scale with progress and crowding.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress);
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 5.0;
        }
    }

    // Tight fit reward: exact or near-exact fills are excellent
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    score += open_bins_count as f64 * 0.15 * progress;

    // Mean residual anchoring: bins below mean residual (fuller than average) favored
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Reward tight fits strongly.
    score -= 2.0 * (item_size as f64 / bin_capacity as f64) * (bin_capacity - post_residual) as f64;

    // Open-bin pressure: penalize keeping many bins open; reward consolidation.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins whose residual deviates from mean (better packing diversity).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.3 * dev;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for wasting space.
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bin would leave a bad gap or no open bin fits well.
    if bin_residual == bin_capacity {
        // Brand-new bin: baseline cost of opening.
        score += 15.0 + 0.5 * open_bins_count as f64;
        // But if the item is large, a fresh bin is decent.
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    // Progression: later in stream, be more conservative with new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 20.0 * progress;
        } else {
            score -= 5.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: near-zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 150.0 / (1.0 + gap);
        // Exact chain fit: this bin then next item fits perfectly.
        if post_residual == next_item_size {
            score -= 300.0;
        }
        // Penalize leaving dead space the next item cannot use.
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average (fill crowded bins).
    let resid = post_residual as f64;
    score += 0.3 * (resid - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But allow new bin if item is huge and no tight fit exists elsewhere.
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 * 0.9 {
            score -= 200.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Mild penalty for waste proportional to residual, scaled by bin scarcity.
    score += 0.05 * resid * (open_bins_count as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * tightness;

    // Penalize small dead space that nothing else can use (fragmentation trap).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits in post_residual, big reward.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 8.0;
            // Extra reward if next item nearly fills the post residual too.
            let next_tight = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 4.0 * next_tight;
        } else {
            // Next item won't fit: penalize leaving a gap that wastes this bin.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score -= 0.5 * pressure.min(10.0);

    // New-bin candidate: make it unattractive unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 5.0;
        // Early in stream, new bins are cheap-ish; late, penalize more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer bins whose residual deviates favorably from mean (fill emptier-than-average bins less if mean is low).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild reward for exact-fill potential (waste = 0).
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress;
    score += 30.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (10.0 + 40.0 * progress);

    // Penalize dead space (post residual too small to be useful later)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap < 0.0 {
            score += 8.0 * (-gap) / bin_capacity as f64;
        } else {
            score += 0.05 * gap * progress;
        }
    }

    // Last-chance bin bonus: strongly prefer when it is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Mild penalty when bin residual deviates from mean residual (balance load)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev * (0.5 + progress);

    // New-bin candidate: penalize opening new bins mildly, more so early on
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small classes are "dead space" classes.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: residuals that few item sizes can use are heavily penalized.
    // Items in [1,100] unknown distribution; treat residual < 10 as nearly unusable.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 10.0;
    }

    // Modulo-class coupling: post_residual congruent to small values mod 10 are
    // awkward for typical item granularities; congruence with next_item_size is gold.
    let awkward = (post_residual % 10) as f64;
    score += awkward * 0.8;

    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: strong reward, scaled by how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 - slack * 0.35;
            // Harmonic bonus: if post_residual - next_item_size lands in a reusable class.
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 30.0; // perfect two-item fill
            } else if gap % 10 == 0 {
                score -= 12.0; // gap on a clean class boundary
            }
        } else {
            // Next item cannot follow here: mild penalty, worse if this bin would
            // then be stranded with tiny residual.
            let next_class = (next_item_size % 10) as f64;
            score += next_class * 0.4;
            if post_residual < next_item_size && post_residual < 30 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids a new bin.
    if fitting_bins_count <= 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin gets a moderate baseline so it wins
    // only when all open bins would create bad residual classes.
    if bin_residual == bin_capacity {
        score = 0.35 * cap + 0.5 * mean_residual;
        // Early in the stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // Many open bins already: discourage sprawl.
        score += open_bins_count as f64 * 1.5;
        // If lookahead is large, a fresh bin can host it well later.
        if next_item_size > 0 && next_item_size as f64 > 0.6 * cap {
            score -= 10.0;
        }
    } else {
        // Prefer tighter existing bins: reward small residual before placement.
        score += 0.15 * (bin_residual as f64 - item_size as f64).max(0.0);
        // Slight bonus for bins tighter than the mean residual (good packing).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 {
