        score += 15.0;
        // More attractive when existing residuals are large (poor fits elsewhere).
        score -= 0.25 * mean_residual;
        // Discourage new bins late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
