        // Prefer existing bins slightly over a fresh one in general.
        score -= 5.0;
        // Lookahead: if the next item would fit in the post-residual, reward this placement.
        if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
            score -= 12.0;
        } else if next_item_size > 0 && post_residual > 0 {
            // Next item won't fit in the leftover: penalize creating stranded space.
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Partial lookahead credit: next item fits into the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 / (1.0 + slack);
    }

    // Penalize small unusable dead space (waste that no item of size >= 1... keep flexible):
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Prefer bins with residual below mean (tighter bins first), leave large-residual bins flexible.
    if bin_residual as f64 > mean_residual {
        score += 25.0;
    } else {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are hopeless.
    if bin_residual == bin_capacity {
        // Opening a new bin is acceptable when few bins fit or residual space is very tight.
        let desperation = if next_item_size > 0 && post_residual >= next_item_size { 30.0 } else { 0.0 };
        score += 150.0 - desperation - (fitting_bins_count as f64) * 20.0;
    }

    // Late in stream: consolidate more aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that can't fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Last-chance bin bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: discourage opening new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 14.0;
        // But if mean residual is high (open bins are fragmented), new bin is more attractive
        score -= mean_residual * 0.08;
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins
    score -= mean_residual * 0.02;
    score += open_bins_count as f64 * 0.3;

    // Time horizon: late in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);

    // Base: prefer tight fits (small post_residual), with a non-linear
    // quadratic coupling so very small residuals are strongly favored.
    let mut score = post * (1.0 + 0.02 * (post / cap));

    // Smooth penalty for residual near the "dead zone" where few future
    // items fit: sin-shaped coupling of normalized residual.
    let r_norm = post / cap;
    score += 8.0 * r_norm * (1.0 - r_norm) * (1.0 - progress);

    // Reward bins whose leftover can still hold the lookahead item
    // (smooth, not piecewise).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 5.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // New-bin candidate handling: mildly penalize opening a new bin,
    // more so early in the stream when open bins exist.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 3.0 + 5.0 * (1.0 - progress) * openness.min(3.0);
        // But favor a fresh bin if mean residual of open bins is very tight
        // (they are nearly full anyway).
        score -= (mean_residual / cap).max(0.0) * 4.0;
    }

    // Mild preference for using bins with larger residuals relative to mean
    // (balance workload across bins smoothly).
    score -= 0.5 * ((bin_residual as f64) - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "reusable" residue classes (multiples of 10, 25, 50) are favored.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit, always excellent
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 10 == 0 {
        -5.0
    } else if pr % 5 == 0 {
        -2.0
    } else {
        3.0 // awkward leftover
    };
    score += class_bonus;

    // Dead-space penalty: leftover too small to hold even the smallest item (1..100).
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Capacity fraction coupling: prefer filling bins past harmonic thresholds.
    let fill = (bin_capacity - pr) as f64 / bin_capacity as f64;
    if fill > 0.75 { score -= 6.0; }
    else if fill > 0.5 { score -= 3.0; }
    else if fill > 0.25 { score += 1.0; }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is
    // large and current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        let item_big = item_size > bin_capacity / 2;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 - 10.0 * crowding.min(2.0) + if item_big { 5.0 } else { 0.0 } - 8.0 * progress;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
            // extra reward for exact harmonic chain: post_residual - next also class-aligned
            if (post_residual - next_item_size) % 25 == 0 {
                score -= 3.0;
            }
        } else {
            score += 2.0;
        }
    }

    // Mild exploration pressure: later in stream, tighten packing.
    score -= (step_index as f64 / (total_items.max(1) as f64)) * (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small but nonzero gaps are useless -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits generally (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 30.0 + 4.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual deviates from the mean (consolidate space).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would leave the post-residual dead, penalize slightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Late in the stream: be more conservative, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        if post_residual as i64 == next_item_size as i64 {
            score -= 30.0; // perfect two-step chain
        }
        // Penalize residuals that are small but unusable for the next item
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 12.0;
        }
    } else {
        // Last item: prefer tightest fit
        score += post_residual as f64 * 0.5;
    }

    // Reward tight fits generally
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: bins with residual below mean are "drier", prefer filling them
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current bin leaves a truly bad residual
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if next item matches a fresh bin perfectly, soften the penalty
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs() <= 2 {
            score -= 22.0;
        }
        // Early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to item size, the better.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Penalize small dead space that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 6.0;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.25 * next_item_size as f64;
        } else {
            // Penalize leaving a residual just barely too small for the next item.
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 10.0 {
                score += 0.8 * (10.0 - gap);
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual > 30.0 && open_bins_count > 2 {
        score -= 0.15 * mean_residual;
    }

    // Early in the stream, be more willing to spread out; later, consolidate tightly.
    score *= 1.0 - 0.15 * progress;

    // New-bin candidate evaluation: empty bin should only win when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened early / when few bins open.
        let mut new_bin_cost = 30.0;
        if open_bins_count < 3 {
            new_bin_cost -= 10.0;
        }
        if progress < 0.3 {
            new_bin_cost -= 8.0 * (0.3 - progress) / 0.3;
        }
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            new_bin_cost -= 6.0;
        }
        // If no open bin fits well (this is the only fitting candidate and it is empty),
        // opening is natural; otherwise keep the penalty.
        if fitting_bins_count == 0 {
            new_bin_cost -= 20.0;
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: penalize post-residual, with a non-linear (quadratic) dead-space term.
    // Small post-residuals are great; large ones waste capacity.
    let mut score = pr + 0.35 * (pr / cap) * pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in the stream, prefer bins with moderate leftover space (keep bins
    // flexible); late in the stream, chase tight fits aggressively.
    let t = progress;
    let flex = pr / cap;
    score += (0.6 * t * t - 0.3 * t) * flex * cap * 0.5;
    score -= (1.0 - t) * 0.25 * (flex * (1.0 - flex)) * cap * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // (smoothly scaled by progress).
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * t;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    // smoothly via a gaussian-like overlap kernel.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let d = pr - nxt;
        let kernel = (-(d * d) / (2.0 * 12.0 * 12.0)).exp();
        score -= 4.0 * kernel;
        // penalize post-residual just barely below next item (near-miss dead space)
        if d < 0.0 && d > -nxt {
            score += 2.0 * (-d / nxt);
        }
    }

    // Mildly discourage scattering across too many open bins relative to mean residual.
    let mean_gap = mean_residual - pr;
    score += 0.05 * mean_gap.abs();

    // New-bin candidate: make an empty bin moderately attractive only when
    // current residuals are poor fits, via smooth interaction with progress.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * t) + 0.2 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 15.0; // don't open new bin if an open bin is last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space
    // Class residuals into buckets of 10 (capacity fractions).
    let class = post_residual / 10;
    let within = (post_residual % 10) as f64;

    // Reward post_residuals that are either tiny (tight fit) or large enough
    // to plausibly host another item (>= ~20). Penalize the awkward middle.
    match class {
        0 => score -= 40.0,                    // near-perfect fit
        1 => score -= 10.0,                    // small but tight-ish
        2 | 3 => score += 15.0,                // dead zone: too small for most items
        _ => {
            // large leftover: fine, especially if next item fits
            if (next_item_size as u32) <= post_residual && next_item_size > 0 {
                score -= 25.0;
            } else if next_item_size > 0 {
                score += 10.0;
            } else {
                score -= 5.0; // last item, leftover matters less
            }
        }
    }

    // Fractional part penalty: leftover just below a class boundary is worse
    score += (10.0 - within) * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a bin unless nothing fits well
    if bin_residual == bin_capacity {
        let base = 30.0 + (post_residual as f64);
        // If no open bin fits, this is forced; soften penalty
        if fitting_bins_count == 0 {
            score = base - 100.0;
        } else {
            score = base;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.5;

    // Slight time decay: later in stream, tighter packing preferred
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (10)
    // are unusable "dead space". Penalize them quadratically.
    if post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64).powi(2);
    }

    // Penalize "awkward" gaps that cannot fit the lookahead item but are still
    // large enough to be tempting (wasted potential).
    if next_item_size > 0 && post_residual >= 10 && post_residual < next_item_size {
        score += 6.0 + 0.25 * post_residual as f64;
    }

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Reward placements that still leave room for the next item (good chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < 10 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, tolerate worse fits to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += 0.15 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: prefer bins that keep the fleet of residuals balanced.
    score += 0.2 * ((post_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when the item is huge and no open bin
    // would leave a decent gap, or late in the stream with many open bins.
    if bin_residual == bin_capacity {
        let bad_fit_elsewhere = fitting_bins_count == 0;
        let big_item = item_size as f64 > 0.7 * bin_capacity as f64;
        if bad_fit_elsewhere || (big_item && open_bins_count >= 2) {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squaring post_residual punishes wasted space super-linearly.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Exact fit is heavily favored.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: if the leftover space exactly accommodates the next item,
    // this placement sets up a perfect chain.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Good: next item still fits here; reward proportionally to how snug.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - slack * 0.5;
        } else {
            // Bad: leftover is too small for the next item -> potential dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 1.5;
        }
    }

    // Compare against mean residual: leaving more than average is wasteful,
    // leaving less than average is a good consolidation.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: strongly discourage opening a new bin unless the current
    // item fits very poorly everywhere (post_residual would be large) or bins are scarce.
    if bin_residual == bin_capacity {
        score += 250.0;
        // Late in the stream, closing out tightly packed bins is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 50.0;
        if open_bins_count == 0 {
            score -= 300.0;
        }
        // If the item is huge relative to capacity, a fresh bin is reasonable.
        if item_size * 2 >= bin_capacity {
            score -= 100.0;
        }
    }

    // Slight preference for bins that are already more filled (smaller residual).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item's likely successor sizes.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0 + 0.25 * post_residual as f64;
        }
        // Reward bins that can still host the lookahead item after this placement.
        if post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Last item: pure tightness dominates; strongly punish any waste.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing open bins,
    // but allow opening when open bins have poor (fragmented) residuals.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 40.0 + 0.3 * fragmentation;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // If many bins can fit, opening a fresh bin is usually wasteful.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidate waste).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Slight preference for bins with less residual overall as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual scaled by progress-dependent weight
    let w = 1.0 + progress * (1.0 - progress) * 4.0;
    let mut score = pr * w;

    // Smooth non-linear coupling: quadratic + cubic terms of normalized residual modulated by progress
    score += progress * 30.0 * norm_pr * norm_pr;
    score += (1.0 - progress) * 20.0 * norm_pr * norm_pr * norm_pr;

    // Tight fit reward, stronger late in the stream
    score -= (1.0 - progress) * (norm_pr * (1.0 - norm_pr) * 4.0) * 25.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // Dead-space penalty: residual too small for typical next items
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += gap * gap * 60.0;
        // Bonus if bin can still host the next item
        if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - norm_pr);
        }
    }

    // Mild preference toward consolidating many open bins
    score += (open_bins_count as f64).ln1p() * 3.0 * (1.0 - norm_pr);

    // Pull toward mean residual to avoid extreme fragmentation
    score += ((pr - mean_residual) / cap).abs() * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        return -1_000_000.0;
    }

    // Harmonic class of the post-residual: dead space that no future item
    // (sizes 1..=100) can ever fill is worthless; small residuals are fine.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Small residuals (<10) are excellent — nothing fits anyway, waste is bounded.
    if post_residual < 10 {
        score -= 500.0;
    }

    // Harmonic (modulo) classes on post_residual: residual mod 10 determines
    // how "reusable" the leftover space is for typical item granularities.
    let m10 = post_residual % 10;
    score -= match m10 {
        0 => 120.0,               // exact decade boundary: highly reusable
        1 => 60.0,                // nearly a decade
        5 => 40.0,                // half-slot
        2 | 8 => 25.0,
        3 | 7 => 10.0,
        _ => 0.0,
    };

    // Integer-division thresholds: how many "unit-10 slots" remain.
    let slots_left = post_residual / 10;
    score -= slots_left as f64 * 15.0;

    // Fraction of capacity wasted: quadratic penalty on waste fraction.
    let waste_frac = post / cap_f;
    score += 300.0 * waste_frac * waste_frac;

    // Coupling with the lookahead item: reward residuals that exactly or
    // nearly accommodate the next item (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 150.0 / (1.0 + chain_waste / 20.0);
        } else {
            // Next item cannot fit here: penalize by the overflow gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 40.0 / (1.0 + gap / 15.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: default mild penalty so we prefer reusing open bins
    // unless they are genuinely poor fits. Scale with stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 180.0 + 120.0 * progress;
        // Opening a new bin is attractive when the item is huge relative to
        // what open bins can absorb (avoid fragmenting many bins).
        if item_size >= 60 {
            score -= 90.0;
        }
    }

    // Crowding: many open bins with high mean residual → prefer consolidation.
    score += 5.0 * (open_bins_count as f64).ln().max(0.0);
    score += 0.3 * (mean_residual - post).abs();

    // Modulo-3 class of item size vs residual: encourage divisibility harmony.
    if post_residual % 3 == 0 {
        score -= 20.0;
    }
    if item_size % post_residual.max(1) == 0 {
        score -= 60.0; // residual divides item pattern: future splits align
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // even the smallest plausible item are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver -> heavy penalty
    } else if post_residual < 20 {
        score += 20.0; // barely usable gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward
    }

    // Non-linear dead-space: penalize residuals that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.25 * (next_item_size - post_residual) as f64;
    }
    // Reward bins whose post_residual can still accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // with few open bins, tolerate looser fits to create packing options.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 4.0 * progress);

    // Deviation from mean residual: prefer bins tighter than average (good fits).
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when no open bin yields a decent fit.
    if bin_residual == bin_capacity {
        let best_possible = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score = 120.0 - best_possible * 0.0
            + if post_residual < 10 { 0.0 } else { 0.0 };
        // Base cost of opening a new bin, modulated by stream progress.
        score = 100.0 + 50.0 * (1.0 - progress);
        // If this is the only fitting option, opening is acceptable.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        if progress > 0.8 && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 45.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (best-fit coupling).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Discard tiny unusable fragments.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Slight bias toward keeping few bins open early; more open bins late means consolidation matters.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive if nothing fits well.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual).
    score = post_residual as f64 * (1.0 + 0.01 * (item_size as f64 / 100.0));

    // Lookahead: reward bins whose residual can host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize residuals that are too small for the next item (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or when the stream is far along (waste is costlier late).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
        // But if many open bins have large residuals, opening fresh is less bad.
        score -= 0.15 * mean_residual;
        // If nothing else fits, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (use the fullest).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild dead-space penalty for very small unusable post_residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: tight fit is good (low score when post_residual small)
    let mut score = post;

    // Smooth polynomial coupling: penalize large residual increasingly as stream progresses
    let poly = norm_post * norm_post * (1.0 + 2.0 * progress) + norm_post * norm_post * norm_post * (1.0 + 3.0 * progress);
    score += poly * cap;

    // Reward near-perfect fits (small post_residual) with a smooth quadratic bonus
    if norm_post <= 0.2 {
        let t = norm_post / 0.2;
        score -= (1.0 - t * t) * 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * (1.0 - progress);
        // But if item perfectly fills a new bin, soften the penalty
        if post == 0.0 {
            score -= 40.0;
        }
    }

    // Lookahead: if next item could fill this bin's post residual, reward tight packing
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            score -= 5.0 * (1.0 - (post - next) / cap);
        } else {
            score += 3.0 * (next - post) / cap;
        }
    }

    // Slight preference for bins below mean residual (consolidating emptier bins)
    score -= (mean_residual - post) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward residuals that fall into "usable" size classes.
    // Class by integer division thresholds on post_residual.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit bonus (item exactly fills bin)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class reward: residuals that are multiples of common item sizes
    // (items 1..100 unknown, so use modular structure on plausible classes)
    let classes: [u32; 6] = [10, 20, 25, 50, 33, 34];
    let mut class_bonus = 0.0;
    for &cl in &classes {
        if post_residual % cl == 0 && post_residual > 0 {
            class_bonus += pr / c * 30.0;
        }
    }
    score -= class_bonus;

    // Penalize tiny dead space: post_residual in (0, 10) is nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize residuals in awkward band 11..19 (below min plausible pairing)
    if post_residual >= 11 && post_residual <= 19 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how well next item nests
            score -= 50.0 * (1.0 - slack / c);
        } else {
            // next item won't fit here; mild penalty scaled by how much overshoot
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin over opening new
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful when many bins fit;
    // penalize the empty-bin candidate unless current bin would leave bad residue.
    if bin_residual == bin_capacity {
        // empty bin baseline: neutral score plus stream-phase term
        score = c * 0.5 + (step_index as f64 / total_items.max(1) as f64) * 20.0;
        // if no open bin fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        if open_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably from mean
    let dev = pr - mean_residual;
    score += 0.15 * dev;

    // Fraction-of-capacity harmonic thresholds on bin_residual
    let bf = bin_residual as f64 / c;
    if bf > 0.75 {
        score -= 40.0; // prefer filling nearly-full bins
    } else if bf < 0.25 {
        score += 15.0; // discourage barely-touched bins
    }

    // Late-stream consolidation: as stream progresses, tighten packing
    let phase = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * phase;

    // Tie-break by item size class (mod 10)
    score -= (item_size % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it's too small to hold even the smallest plausible item.
    let dead_threshold = 12u32; // below this, gap is likely unusable
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }

    // Perfect / near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Tightness ratio: reward bins where the item fills a large fraction of residual.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: penalize opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin is only attractive if existing fits are bad (high mean residual mismatch)
        // or there are no fitting bins (last chance).
        score = 80.0 + open_bins_count as f64 * 3.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        } else {
            // discourage new bin unless it would otherwise create dead space
            if post_residual == 0 { score -= 90.0; }
            if post_residual < dead_threshold { score += 40.0; }
            // if next item fits nicely in the new bin's residual, slight bonus
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // Lookahead: reward if next item can use this bin's post residual (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Mild penalty relative to mean residual: prefer bins below-average residual
    // (i.e., already well-filled bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Partial match: next item fits tightly (within small slack)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (8.0 * (1.0 - slack / 30.0)).max(0.0);
    }

    // Penalize dead space unusable by typical items (below min size 1..)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Compare residual against mean residual: prefer bins with less residual than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early stream: encourage packing tightly into few bins; late stream: allow new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate bias: slightly penalize opening a new bin unless residual is huge
    if bin_residual == bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (minimize dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Reward bins whose residual closely matches the item (tight coupling).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.35;

    // Penalize placing a small item into a large-residual bin (waste of space).
    let waste_ratio = item_size as f64 / bin_residual as f64;
    if waste_ratio < 0.4 {
        score += 18.0 * (0.4 - waste_ratio);
    } else if waste_ratio > 0.85 {
        score -= 12.0 * (waste_ratio - 0.85);
    }

    // Lookahead: if the next item fits exactly in the post-residual, this bin
    // is doubly valuable; if it clearly cannot use the leftover, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 * chain_tightness;
        } else {
            // Next item can't use leftover; leftover more likely becomes dead space.
            score += (post_residual as f64) * 0.25;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidation into
    // existing bins; when few bins are open, new bins are cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = 0.5 + 0.5 * progress;
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * consolidation;

    // Compare against mean residual: bins below mean residual are "fuller",
    // favor filling them further.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when the item is large relative to capacity or
    // no good existing fit exists (post_residual small already rewards reuse).
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Base new-bin cost: moderate, so tight existing fits win.
        score += 40.0;
        // Large items justify opening fresh bins (avoid fragmentation).
        score -= 30.0 * large_item;
        // Late in the stream, prefer closing out bins over opening new ones.
        score += 15.0 * progress;
        // If many bins already open, discourage yet another one.
        score += open_bins_count as f64 * 1.5;
        // If the next item is small and this bin is fresh, slight penalty
        // (a fresh bin is flexible, keep it for later big items).
        if next_item_size > 0 && next_item_size < 30 {
            score += 8.0;
        }
    }

    // Small time-varying tie-breaker to diversify exploration across the stream.
    let phase = ((step_index as f64 * 0.37).sin()) * 1.5;
    score += phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;

    // Early in the stream: tolerate larger residuals (bins stay flexible).
    // Late in the stream: penalize residuals super-linearly (compactness matters).
    let progress_weight = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += progress_weight * pr_norm * pr_norm * 60.0;

    // Reward tight fits smoothly: quadratic decay of penalty as post_residual -> 0
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 25.0;

    // Interaction: residual relative to mean residual across open bins
    let mean_diff = pr - mean_residual;
    score += 0.05 * mean_diff * mean_diff * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress_weight) + 20.0 * progress_weight;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let gap_norm = gap / bin_capacity as f64;
        score -= (1.0 - gap_norm) * (1.0 - gap_norm) * 15.0;
        // Penalize leaving a residual just barely too small for the next item
        if pr < next_item_size as f64 && pr > 0.0 {
            score += 10.0 * (1.0 - pr_norm) * progress_weight;
        }
    }

    // Mild penalty for proliferation of open bins, smoothed by progress
    score += (open_bins_count as f64).ln() * 2.0 * (0.3 + 0.7 * progress);

    // New-bin candidate handling: only attractive for very large items
    if bin_residual == bin_capacity {
        let item_norm = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 35.0 * item_norm * item_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classification
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward (harmonic resonance with capacity fractions)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0; // near-perfect: residual below min item size is dead anyway
    } else {
        // Penalize residuals that no item class (1..100) can use well
        // Residuals in (50, 100) can host almost anything; tiny ones are dead.
        // Use integer division thresholds on post_residual.
        let cls = post_residual / 10; // harmonic class 0..=10
        match cls {
            0 => score += 80.0,          // 1..9: dead space penalty
            1 => score += 30.0,          // 10..19: only small items fit
            2 | 3 => score += 10.0,      // 20..39: mid items fit
            4 | 5 => score -= 15.0,      // 40..59: good half-full zone
            _ => score -= 25.0,          // 60+: very reusable
        }
        // Modulo-10 resonance: residuals divisible by 10 pair with common sizes
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 + 0.3 * next_item_size as f64;
        } else {
            // next item won't fit here; penalize more if post_residual is small
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: prefer new bin only when open bins are fragmented
    if bin_residual == bin_capacity {
        // New bin starts full: base score high, discounted when many open bins
        score = cap * 0.85 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // new bin good for pairing large items
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        // Late in stream, consolidate into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Mild normalization toward mean residual: prefer bins tighter than average
    score -= 0.1 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= ~10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        // Risky gap: only useful if the lookahead item fits it exactly-ish.
        if next_item_size == 0 || next_item_size > post_residual {
            score += 25.0;
        } else {
            score -= 15.0; // lookahead item fits in the gap: great fit
        }
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // Reward tight fits (small post_residual relative to capacity).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer reusing existing space
    // rather than spreading; few open bins -> new-bin candidate is cheap.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New empty bin: penalize when many bins are already open,
        // discount when few are open or stream is early.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 + pressure * 3.0 - progress * 20.0;
        // If nothing open fits well, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    } else {
        // Existing bin: slight reward when many bins are open (consolidate).
        score -= pressure.min(15.0) * 0.5;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "small" bin — finishing it off is good; if far above mean,
    // placing here leaves many other bins with large residuals anyway.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Lookahead: if next item cannot fit this bin but could fit elsewhere,
    // mild penalty for consuming a large residual on a small item.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how much of the post residual it consumes.
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * usage;
        } else {
            // Next item cannot use this residual: penalize dead space creation.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits relative to item size (small waste ratio).
    score -= 80.0 * (item_size as f64 / bin_capacity as f64);

    // Prefer bins whose residual is below mean (consolidate waste into few bins).
    if (bin_residual as f64) < mean_residual {
        score -= 20.0;
    } else {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Late in the stream, favor closing bins tightly over spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New empty bin: only attractive when residual is unusable for the item anyway
    // (shouldn't happen since it's only called when it fits), so penalize mildly.
    if bin_residual == bin_capacity {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post residual so small leftovers are strongly preferred.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead: if the next item fits exactly into the post residual, reward this bin strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_left = post_residual - next_item_size;
            score -= 12.0 * (1.0 - (next_left as f64) / (bin_capacity as f64));
        } else {
            // Post residual too small for the next item: penalize creating dead space.
            score += 0.35 * (post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it over opening a new bin,
    // unless the fit is very loose (would strand most of the bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.5 {
            score -= 8.0 * fill_ratio;
        } else {
            score += 4.0 * (1.0 - fill_ratio);
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Late in the stream, avoid opening bins for loose fits; early, allow exploration.
        let openness = 1.0 - progress;
        // Penalize new bin if the item would leave a lot of space and open bins exist.
        let stranded = (bin_capacity - item_size) as f64;
        score += 15.0 + stranded * (0.5 + progress) - 10.0 * openness * (open_bins_count as f64).min(5.0) / 5.0;
        // If the next item is large, a fresh bin is more useful.
        if next_item_size >= item_size {
            score -= 6.0;
        }
    }

    // Prefer bins whose residual is close to the mean residual (keep bin states homogeneous),
    // which preserves large residuals in other bins for future big items.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.10 * deviation;

    // Slight preference for more-filled bins among equals (larger residual = less filled).
    score += 0.05 * (bin_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize post residual, with non-linear (quadratic/cubic) shaping.
    let mut score = pr * (1.0 + 0.8 * x * x) + 12.0 * x * x * x * cap;

    // Stream-progress coupling: later in stream, tighter packing matters more.
    let prog_coupling = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= prog_coupling;

    // Interaction of post residual with mean residual: prefer bins whose leftover
    // is close to the mean (keeps residual distribution coherent).
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: reward leaving space that still fits the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 8.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 6.0 * (ni - pr) / cap;
        }
    }

    // New-bin candidate: penalize mildly so it only wins when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress - 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition [0,100] into modulo-10 classes.
    // Small post-residuals (tight fits) are rewarded; mid-range dead space penalized.
    let pr = post_residual;
    let cls = pr % 10;
    let quot = pr / 10;

    // Class-based modulation: residuals that are exact multiples of 10 pair well
    // with typical item sizes; odd/prime-ish leftovers are less reusable.
    let class_bonus: f64 = match cls {
        0 => -12.0,
        1 | 3 | 7 | 9 => 6.0,
        2 | 4 | 6 | 8 => 2.0,
        5 => 4.0,
        _ => 0.0,
    };
    score += class_bonus;

    // Decile penalty: dead space in the middle deciles (30-70) is hardest to fill.
    match quot {
        0 => score -= 15.0,          // near-perfect fit
        1 => score -= 4.0,           // 10-19, still very usable
        2 => score += 3.0,           // 20-29
        3 => score += 8.0,           // 30-39
        4 => score += 10.0,          // 40-49 worst zone
        5 => score += 8.0,
        6 => score += 4.0,
        _ => {}                      // >=70: large residual, naturally fine
    }

    // Pairing with next item: reward if post_residual's class can host next_item_size.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here too: strong reward, especially for tight chains.
            score -= 10.0 + (pr - next_item_size) as f64 * 0.1;
            // Harmonic coupling: post_residual % next_item_size small => good chain
            if next_item_size != 0 {
                let rem = pr % next_item_size;
                score -= (10 - (rem as f64 * 0.5).min(10.0)) * 0.3;
            }
        } else {
            // Next item cannot fit: slight penalty if this bin was "reserved" for it
            score += 3.0;
        }
    } else {
        // Last item: only absolute tightness matters.
        score = pr as f64 - 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 3 {
        score += 2.0; // plenty of alternatives, no urgency
    }

    // New-bin candidate: only attractive when open bins are congested or the item
    // would leave bad mid-range dead space everywhere.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        // Opening a new bin is good late in the stream or when mean residual is low.
        let stream_pos = step_index as f64 / (total_items.max(1) as f64);
        let newbin_score = 55.0
            - 25.0 * stream_pos
            - 10.0 * congestion.min(2.0)
            - 8.0 * (item_size as f64 / 100.0);
        // Harmonic check: fresh bin gives residual 100-item, a "clean" class if item
        // is multiple of 10.
        let clean = if item_size % 10 == 0 { -6.0 } else { 0.0 };
        score = newbin_score + clean;
    }

    // Mild preference to consolidate across few bins.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // gap below the minimum item size -> pure dead space
        score += 60.0 * (10.0 - pr) / 10.0;
    } else if pr < 25.0 {
        // risky zone: only tiny items can use it later
        score += 15.0 * (25.0 - pr) / 25.0;
    }

    // Reward tight fits (post_residual near 0 but usable).
    if pr == 0.0 {
        score -= 40.0;
    } else if pr >= 10.0 && pr <= 20.0 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (pr - ni).abs() < 0.5 {
            score -= 30.0;
        } else if pr > ni && pr - ni < 10.0 {
            // placing here would leave a dead gap for the next item
            score += 25.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
        if pr <= 25.0 {
            score -= 15.0;
        }
    }

    // Open-bin pressure: discourage scattering across many bins; a new empty bin
    // should only win when open bins are numerous and fits are poor.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: make it moderately attractive only when it creates a fresh
    // large residual; it must lose to good fits but win over dead-space placements.
    if bin_residual == bin_capacity {
        score = 70.0 - item_size as f64 * 0.3 + open_bins_count as f64 * 1.5;
        if fitting_bins_count == 1 {
            // an existing last-chance bin beats opening a new one
            score += 35.0;
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (pr / 100.0);

    // Deviation from mean residual: prefer bins whose residual is close to the mean
    // to keep residuals balanced and reusable.
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward if the next item exactly matches post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect two-item packing
        } else if next_item_size < post_residual {
            // next item fits: reward proportionally to how tight the leftover after that would be
            let second_left = post_residual - next_item_size;
            score -= (30.0 - (second_left as f64) * 0.4).max(-20.0);
        } else {
            // next item cannot fit here: penalize, worse if gap is just barely too small
            let gap = next_item_size - post_residual;
            score += (gap as f64).min(40.0) * 1.5;
        }
    }

    // Compare post_residual relative to mean residual: leaving less than average is good.
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Penalize new empty bins unless the item is large and open bins are tight.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        // Prefer new bin when open bins have little room left or item is big.
        score += 45.0 - 80.0 * pressure - 40.0 * large_item;
    }

    // Slight preference for denser bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * 20.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

