    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of the fit: reward snug placements (small post_residual relative to item size)
    let snug = post_residual as f64 / (item_size.max(1) as f64);
    score += snug * 12.0;

    // Reward filling bins deeply when the bin is nearly full
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * fill_ratio * 30.0;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item cannot use the leftover space: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else {
        // mild penalty when many bins compete, to keep flexibility
        score += (fitting_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidation
    let global_pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    if bin_residual < bin_capacity {
        score -= global_pressure * 0.5;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        let mut new_bin_cost = 55.0;
        // Early in stream with few bins: opening is cheaper
        new_bin_cost -= (1.0 - progress) * 20.0;
        // If item fits poorly nowhere else (large item, few fitting bins), opening is attractive
        if fitting_bins_count == 0 {
            new_bin_cost -= 100.0;
        } else if fitting_bins_count == 1 {
            new_bin_cost += 30.0;
        }
        // If open bins are already tight on average, opening a new bin is more reasonable
        new_bin_cost -= (mean_residual / bin_capacity as f64) * 25.0;
        // Late in the stream, avoid proliferation of bins
        new_bin_cost += progress * 15.0;
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, slightly discounted since larger leftover is reusable
    let mut score = pr * (1.0 - 0.15 * pr_norm);

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: prefer tight fits (low post_residual); late: keep residuals usable.
    let w_tight = (1.0 - progress) * (1.0 - progress);
    let w_loose = progress * progress;
    score += w_tight * 8.0 * pr_norm * pr_norm * cap;
    score -= w_loose * 4.0 * pr_norm * (1.0 - pr_norm) * cap * 0.1;

    // Dead-space penalty: residual too small for any future item (min size 1..100 unknown,
    // assume small items possible but penalize very small leftovers smoothly).
    let dead = (1.0 - pr_norm) * (1.0 - pr_norm); // peaks when pr small
    score += dead * 6.0 * (1.0 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 12.0 + 6.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        let tightness = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= fits_next * (4.0 + 8.0 * tightness);
        // Penalize if next item nearly fits but not quite (encourage better reserve)
        let near_miss = ((next_item_size as f64 - pr) / cap).max(0.0);
        score += 5.0 * near_miss * near_miss * cap * 0.1 * (1.0 - fits_next);
    }

    // Mild preference for bins already diverging from mean residual (consolidate)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 1.5 * dev * dev;

    // Slight penalty when many bins are open (encourage closing bins out)
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: neutral-ish baseline with penalty so it's chosen only
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * (1.0 - progress) + 0.5 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residuals that fall into "dead zones" (too small for typical items,
    // i.e. below the minimum item size) more aggressively than raw residual.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Reward residuals that are exact harmonic divisions of capacity:
    // 50, 25, 20, 10 etc. — highly reusable classes.
    let harmonic_bonus = |r: u32| -> f64 {
        if r == 0 { 30.0 }                      // perfect fit
        else if bin_capacity % r == 0 { 15.0 }  // divisor of capacity
        else if r % 10 == 0 { 8.0 }             // multiple of 10
        else { 0.0 }
    };
    score -= harmonic_bonus(post_residual);

    // Coupling with lookahead item: strong reward if next item fits exactly,
    // penalty if next item cannot use the remaining space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // sets up a perfect chain
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: keep it competitive only when open bins are fragmented
    // or the item is large relative to current residuals.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if fragmentation > 20.0 || item_size > bin_residual - item_size.max(0) {
            score -= 10.0;
        } else {
            score += 15.0; // prefer existing bins when they are healthy
        }
    }

    // Modulo-class penalty on residual: odd/awkward classes get slight penalty.
    let class = post_residual % 7;
    score += match class {
        0 => -3.0,
        1 | 6 => 1.5,
        _ => 0.5,
    };

    // Early in the stream, allow slightly more bin opening for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 5.0;
    }

    // Mild tie-break toward fewer open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    // Gaps below the smallest possible item (assume ~10) are pure waste.
    let min_item = 10.0f64;
    if (post_residual as f64) < min_item {
        // fully dead gap: heavy penalty scaled by how close to zero
        score += (min_item - post_residual as f64) * 6.0;
    } else if (post_residual as f64) < 2.0 * min_item {
        // awkward gap: only usable by very small items
        score += (2.0 * min_item - post_residual as f64) * 2.5;
    }

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64);
        score -= tightness * 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so it gets penalized here)
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 4.0;
        // extra penalty if any open bin fits the item
        if fitting_bins_count >= 1 {
            score += 20.0;
        }
    } else {
        // mild reward for keeping bins consolidated when open count is high
        score -= open_bins_count as f64 * 0.3;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    } else if next_item_size > 0 && post_residual < next_item_size && (post_residual as f64) >= min_item {
        // next item cannot use this gap; the residual becomes semi-dead
        score += 4.0;
    }

    // Progress-based calibration: later in the stream, be more conservative about waste
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64) * progress * 0.5;

    // Mean residual coupling: if this bin's post residual deviates far below mean,
    // it fragments the residual distribution; slight penalty
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Dead space: post_residual too small for the next item (wasted capacity).
    if next_item_size > 0 && post_residual < next_item_size {
        let waste_ratio = (next_item_size - post_residual) as f64 / bin_capacity as f64;
        score += 25.0 * waste_ratio;
    }

    // If next item fits in post_residual but not perfectly, mild reward proportional to tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Prefer bins whose residual deviates favorably from the mean residual:
    // tighter-than-average bins should be filled first.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins exist and could fit reasonably,
    // unless the new bin would serve the next item perfectly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // Slight preference to consolidate into fewer bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward low post_residual non-linearly.
    score -= (cap - post_residual as f64).powi(2) / cap;

    // Penalize dead space: residual too small for any plausible future item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 80.0;
        } else if (post_residual as u32) >= next_item_size {
            score -= 15.0 * (nxt / cap);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 8.0 * (nxt / cap);
        }
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Early in the stream, be more willing to open new bins (keep options open);
    // late in the stream, consolidate into existing bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins count and time.
        score = cap * 0.75 + 20.0 * (1.0 - t) + open_bins_count as f64 * 0.5;
        // If nothing fits well anywhere (post_residual would be tiny in all bins),
        // opening fresh is attractive; approximate via mean residual being small.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 15.0;
        }
    } else {
        // Existing bin: later in stream, small residual waste is more acceptable.
        score *= 1.0 + 0.2 * t;
    }

    // Mild penalty for many open bins to encourage consolidation mid/late stream.
    score += open_bins_count as f64 * 0.1 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in stream, prefer tight fills (low post_residual) mildly;
    // late in stream, penalize dead space quadratically.
    let prog_sq = progress * progress;
    score += 12.0 * prog_sq * (post / cap) * (post / cap) * cap;

    // Reward tight fit smoothly: post_residual near 0 gets large discount
    let tightness = 1.0 - (post / cap);
    score -= 8.0 * tightness * tightness * tightness;

    // Last-chance bonus: smooth exponential-like decay with fitting_bins_count
    let fit_f = fitting_bins_count as f64;
    score -= 15.0 / (1.0 + fit_f * fit_f);

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 10.0 * (1.0 - ((post - nxt) / cap)) * (1.0 - progress);
        } else {
            score += 5.0 * (nxt - post) / cap;
        }
    }

    // Mild penalty for spreading across many open bins, smooth in open_bins_count
    let bins_f = open_bins_count as f64;
    score += 2.0 * (bins_f / (bins_f + 5.0));

    // Deviation from mean residual: prefer bins whose post residual approaches mean
    let dev = (post - mean_residual).abs();
    score += 3.0 * dev / cap;

    // Slight preference for placing larger items (smooth)
    score -= 0.05 * item * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of the residual: bucket by integer division of post_residual
    let class = post_residual / 10; // 0..=10 harmonic band
    let class_penalty = match class {
        0 => -30.0,           // near-perfect fill
        1 => -15.0,           // excellent
        2 => -7.0,            // good
        3 | 4 => 0.0,         // neutral
        5 => 5.0,             // half-full leftover, moderately reusable
        6 | 7 => 3.0,
        _ => 1.0,             // large residual, easy to reuse anyway
    };
    score += class_penalty;

    // Modulo coupling: residuals that align with common item sizes (multiples of 5/10)
    // are more reusable -> reward them.
    if post_residual % 10 == 0 { score -= 6.0; }
    else if post_residual % 5 == 0 { score -= 3.0; }

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
