            if (post_residual - next_item_size) % 10 != 0 { score += 2.0; }
        } else {
            // next item won't fit here; penalize proportionally to overflow
            score += 4.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer keeping it only when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        // base cost of opening a bin, softened when mean residual is large (waste elsewhere)
        score = cap * 0.85 + 8.0 - (mean_residual / cap) * 15.0;
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // if next item is small, a fresh bin stays flexible
        if next_item_size > 0 && next_item_size <= 20 { score -= 8.0; }
    }

    // Tight-fit bonus relative to item size (wasted fraction of the item's footprint)
    let waste_ratio = pr / (item_size as f64 + 1.0);
    score += 4.0 * waste_ratio;

    // Mean residual coupling: penalize creating residual far from current mean (fragmentation)
    score += 0.05 * (pr - mean_residual).abs();

    // Congestion: many open bins -> favor filling existing ones harder
    score -= 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
