        // More open bins -> more reluctance.
        score += (open_bins_count as f64).sqrt() * 2.0;
        // Large item with lookahead needing space: slightly favor fresh bin.
        if item_size > 60 {
            score -= 6.0;
        }
    }

    // Small nudge against fragmenting bins that could serve larger future items.
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with smooth polynomial sharpening.
    let mut score = norm_pr + 0.8 * norm_pr * norm_pr + 1.5 * norm_pr * norm_pr * norm_pr;

    // Tight-fit reward: items that fill the bin well get a smooth quadratic bonus.
    let fill_ratio = item_size as f64 / cap;
    score -= 2.0 * fill_ratio * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Stream-progress coupling: as the stream advances, penalize large dead space more strongly.
    let progress_coupling = 1.0 + 2.5 * progress * progress;
    score *= progress_coupling;

    // Last-chance bin: strongly favor using it (smooth reward scaled by fit quality).
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward if next item can fit in the post residual (smooth interaction).
    if next_item_size > 0 {
        let next_fits = if (next_item_size as f64) <= pr { 1.0 } else { 0.0 };
        let next_tightness = 1.0 - (next_item_size as f64 - pr).abs() / cap;
        score -= 1.2 * next_fits * next_tightness * next_tightness;
        // Penalize leaving residual just below next item size (smooth dead-space trap).
        let gap = (next_item_size as f64 - pr) / cap;
        score += 1.0 * gap * gap * (1.0 - next_fits);
    }

    // Mean residual context: prefer bins whose residual is below average when mean is high.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.5 * dev * dev;

    // Slight preference for consolidating into fewer bins when many are open.
    score -= 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but with harmonic (quantized) reward classes.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Harmonic class of post_residual: quantize into residue classes of 10.
    // Residuals in [0..=9] are "dead" (no item can be 1..10? items >=1, so small residual
    // classes matter). Reward residual classes that are multiples of common item sizes.
    let post_i = post_residual as i64;
    let dead_penalty = if post_i > 0 && post_i < 10 {
        25.0 // unusable sliver
    } else {
        0.0
    };
    score += dead_penalty;

    // Modulo-class bonus: residual exactly divisible by common sizes (10,20,25,50)
    // is more likely to be filled later.
    let div_bonus = if post_i > 0 {
        let mut b = 0.0;
        if post_i % 10 == 0 { b += 6.0; }
        if post_i % 20 == 0 { b += 3.0; }
        if post_i % 25 == 0 { b += 3.0; }
        if post_i % 50 == 0 { b += 2.0; }
        b
    } else {
        8.0 // perfectly closed bin is ideal
    };
    score -= div_bonus;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // harmonic class match: next item's complement also leaves good residue
            let after2 = post_residual - next_item_size;
            let class_ok = (after2 % 10 == 0) as f64 * 4.0;
            score -= 8.0 + class_ok - (after2 as f64) * 0.05;
        } else {
            // next item cannot use this bin's residual: mild penalty scaled by how wasted
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && post_i >= 0 {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default penalty so it is
    // only chosen when open bins have bad fits.
    if bin_residual == bin_capacity {
        score += 22.0 - 10.0 * (mean_residual / bin_capacity as f64).min(1.0);
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Slight pressure toward bins below mean residual (balancing harmonic classes)
    score += ((post_residual as f64) - mean_residual) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit the
    // minimum item (1..100 unknown, so treat < 10 as near-dead) are
    // heavily penalized; small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward very tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer
    // using it rather than opening a new bin (unless dead space results).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // fresh space; consolidate instead.
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate: the empty bin should only win when no open bin
    // offers a decent fit, or when the fit would create dead space.
    if bin_residual == bin_capacity {
        let dead_space_risk = (item_size < 20) as f64 * 40.0;
        score += 30.0 + dead_space_risk + 2.0 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item fits the post residual,
    // reward this placement (chaining two items in one bin).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for the lookahead item: penalize mildly.
        score += 8.0;
    }

    // Mean-residual coupling: placing into a bin far below mean residual
    // wastes the "roomy" bins; prefer bins already tighter than average.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Stream progression: late in the stream, be more conservative about
    // opening new bins (consolidation phase).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // Next item fits after this placement: reward tight sequential packing.
            let lookahead_gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - lookahead_gap / bin_capacity as f64);
            // Perfect chain: post_residual equals next item exactly.
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here: penalize leaving residual that traps the stream.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.08 * overshoot;
        }
    }

    // Penalize large dead space relative to mean residual (avoid creating unusable gaps).
    if post_residual as f64 > mean_residual {
        score += 0.35 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Mild penalty on tight fits that leave small unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Prefer filling bins more completely as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Discourage spreading across too many open bins when residual is still generous.
    if open_bins_count > 3 && post_residual as f64 > 0.5 * bin_capacity as f64 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual preferred).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize unusable dead space: residuals too small for typical items.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 100.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: prefer bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > bin_residual {
            // Next item can't fit here anyway; this bin is free real estate.
            score -= 6.0;
        } else {
            score += 8.0;
        }
        // Chain fit: post-residual exactly matches next item size.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used only when justified.
        score += 35.0;
        // Late in the stream, prefer consolidation into open bins.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * t;
        // Many open bins with slack: discourage opening another.
        score += (open_bins_count as f64).sqrt() * 4.0;
        // Large items relative to capacity may warrant a fresh bin.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 30.0;
        }
        // If mean residual is small, open bins are nearly full; new bin is fine.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
        // Lookahead: if next item is large and this item leaves big residual elsewhere, new bin ok.
        if next_item_size > 0 && next_item_size as f64 > post_residual as f64 && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Mild preference for fuller bins overall (waste-averse).
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    // Penalize bins whose residual deviates far below mean (fragmented state).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial coupling to stream progress.
    // Early on, larger residuals are tolerated; late in the stream, waste is penalized harder.
    let mut score = norm_pr * (1.0 + 1.5 * progress * progress) * cap;

    // Smooth non-linear interaction: quadratic coupling of post-residual with item fill ratio.
    let fill = item_size as f64 / cap;
    score -= 2.0 * fill * (1.0 - norm_pr) * cap;

    // Penalize dead space that can't fit the lookahead item (smooth soft term).
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 8.0 * gap * gap * cap * (0.5 + progress);
    }

    // Reward using a bin when it is the last chance to fit (avoid opening new bins).
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress * cap * norm_pr;
    }

    // Mild penalty when many bins are open and this placement leaves a mid-range residual
    // (hard-to-fill later) — smooth bump around norm_pr = 0.5.
    let bump = (norm_pr - 0.5) * (norm_pr - 0.5);
    score += (open_bins_count as f64).ln().max(0.0) * 4.0 * bump * cap;

    // Deviation from mean residual: prefer bins below mean residual (tighter packing).
    score += 0.5 * (pr - mean_residual);

    // New-bin candidate: keep it neutral-to-slightly-high unless residual waste is tiny elsewhere.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.3 * progress) + 0.5 * mean_residual;
        if next_item_size > 0 {
            score -= 0.2 * next_item_size as f64 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (harmonic class: post_residual in {0,1,2})
    if post_residual <= 2 {
        score -= 40.0 + (2 - post_residual) as f64 * 10.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize dead space in awkward classes: post_residual in 20..40 rarely refillable
    if post_residual > 20 && post_residual < 40 {
        score += 12.0;
    }
    if post_residual > 40 && post_residual < 55 {
        score += 6.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves residue; penalize by leftover class
            let nxt_post = post_residual - next_item_size;
            if nxt_post <= 2 {
                score -= 18.0;
            } else if nxt_post > 25 {
                score += 10.0;
            }
        } else {
            // next item cannot use this bin's residue: slight penalty for wasting space
            score += 5.0;
        }
    }

    // Prefer filling already-open bins when many bins are open (avoid bin proliferation)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 3.0 + 5.0 * progress;
    } else {
        // New-bin candidate: only attractive when nothing fits well
        let tight_exists = fitting_bins_count > 0 && (post_residual <= 5 || (next_item_size > 0 && next_item_size <= post_residual));
        if tight_exists {
            score += 30.0;
        }
        // opening new bin early in stream is cheaper than late
        score += 8.0 * (1.0 - progress);
    }

    // Harmonic modulo tweak on residual to break ties toward divisible classes
    let mod_class = post_residual % 10;
    if mod_class == 0 {
        score -= 2.0;
    } else if mod_class >= 8 {
        score += 2.0;
    }

    // Mean-residual coupling: prefer bins close to the mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for "dead space": gaps too small to ever be useful.
    // Smallest useful item is 1, but small gaps (< 12) are hard to fill;
    // gaps below the typical item size are nearly dead.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 + (12.0 - post_residual as f64) * 6.0;
    }
    // Perfect fit: zero waste, strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual == bin_residual {
        // item didn't actually fit meaningfully (shouldn't happen, guard)
        score += 100.0;
    }

    // Reward bins whose leftover can still hold the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // leftover cannot fit next item: dead space until later
            score += 8.0 + 0.25 * post_residual as f64;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (and discourage opening new bins) to avoid fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.6 + 0.8 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item is large relative to
    // mean residual spread or no open bin fits well; otherwise penalize opening.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual.max(0.0);
        score += 30.0 + 2.0 * open_bins_count as f64 - 0.15 * mean_r;
        // late in the stream, opening fresh bins is rarely worth it
        score += 20.0 * progress;
        // if item is small, opening a new bin wastes capacity
        if item_size < 40 {
            score += (40 - item_size) as f64 * 0.8;
        }
    }

    // Slight preference for bins tighter than the average residual (best-fit flavor).
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: big reward.
        if gap == 0.0 {
            score -= 40.0;
        } else {
            // Proximity bonus decaying with gap.
            score -= 30.0 * (-gap / 20.0).exp();
            // Penalize leaving dead space that next item cannot use.
            if post_residual < next_item_size {
                score += 0.35 * (next_item_size - post_residual) as f64;
            }
        }
    } else {
        // Last item: just prefer minimal waste.
        score += 0.1 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins already tighter than average are good targets;
    // very loose bins (large residual vs mean) are penalized slightly.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = res / mean_residual;
        if rel > 1.5 {
            score += 0.15 * (res - mean_residual);
        } else if rel < 0.7 {
            score -= 0.1 * (mean_residual - res);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.2 * open_bins_count as f64;
        // If lookahead suggests the new bin will be poorly used, discourage more.
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64) < 10 {
            score += 10.0;
        }
    }

    // Slight stream-progress term: early on, be more willing to open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space less than large dead space (already via base),
        // but add superlinear penalty for awkward residuals that few items can use.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 30.0; // tiny dead space is wasted capacity
        }
        // Reward residuals that the next item could exactly use
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            // next item still fits here: mild bonus scaled by leftover quality
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if next_item_size > post_residual {
            // next item cannot use this residual: penalize proportionally
            score += 8.0 * (next_item_size as f64 - pr).min(40.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoiding fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses
        // (early on we want consolidation; late, waste matters less).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_cost = 120.0 * (1.0 - 0.5 * progress);
        // If many bins are open with high mean residual, opening yet another is bad.
        open_cost += 2.0 * open_bins_count as f64;
        // If mean residual is large, open bins are underused -> avoid new bin.
        open_cost += mean_residual * 0.5;
        // If no open bin fits (this call happens alongside), the new bin is necessary:
        // fitting_bins_count counts fitting open bins; when 0, reduce cost.
        if fitting_bins_count == 0 {
            open_cost -= 200.0;
        }
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            open_cost -= 25.0;
        }
        score += open_cost;
    }

    // Mild global pressure: when few bins fit the item, tighten competition
    // among them so the tightest one wins clearly.
    if fitting_bins_count >= 2 && bin_residual < bin_capacity {
        score -= 5.0 * (bin_residual as f64 - post_residual as f64) / item_size.max(1) as f64;
    }

    // Prefer bins whose residual is close to capacity-mean alignment
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit), with non-linear sharpening.
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth polynomial coupling: residual decay value depends on stream progress.
    // Late in the stream, waste matters more -> amplify post-residual penalty.
    score *= 1.0 + 1.5 * progress * norm_pr;

    // Dead-space penalty: post-residual that is too small to fit a typical future item.
    let dead = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size as f64 - pr) / cap
    } else {
        0.0
    };
    score += dead * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 2.0 + 2.0 * progress;
    }

    // Mild pressure against spreading across many bins when mean residual is already low.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // New-bin candidate: empty bin should win only when it creates a clean large residual
    // and existing fits are poor. Give it a moderate default score.
    if bin_residual == bin_capacity {
        score = cap - pr; // = 0 for empty bin; recompute as neutral baseline
        score = norm_pr * cap; // post_residual == capacity -> norm_pr == 1
        score = 0.8 + 0.4 * progress + dead * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = post_residual / 10; // harmonic class 0..=10

    // Reward small post_residual (tight fits), super-linearly
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.01;

    // Penalize "dead space" classes: residuals too small for typical items (1..=100)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }
    // Harmonic residue bonus: residuals that are multiples of 10 are reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Class-based dead-space estimate: residual in (0, min item size) is waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    let _ = progress;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.1;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this residual: penalize proportionally to class
        score += class as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer fresh bin when current bin would leave large waste
    if bin_residual == bin_capacity {
        // neutral-ish baseline; opening new bin costs one bin
        score = bin_capacity as f64 * 0.6 - item_size as f64 * 0.2;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Prefer filling bins with larger mean residual less (spread load)
    score += (mean_residual - frac * bin_capacity as f64) * 0.02;

    // Tie-break: favor bins with more remaining relative space when many bins open
    if open_bins_count > 3 {
        score += frac * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item are pure waste -> heavy penalty.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 50.0;
    }
    // Penalize residual that cannot fit the lookahead item (k=2 lookahead):
    // dead space relative to the actual future demand.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < next_item_size as u64 {
        score += 8.0 + 0.15 * next_item_size as f64;
    }
    // Reward exact-ish fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }
    // Tightness reward: relative fit quality.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; with few bins, new bins are cheap.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open-bin pressure is high or the
        // item fits reasonably well somewhere else.
        score += 18.0 + 2.0 * pressure;
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    } else {
        // Existing bin: reward more when pressure is high.
        score -= 0.5 * pressure;
        // Favor bins tighter than the mean residual (already well packed).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Late in the stream, waste matters more (no future to recover it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual >= next_item_size {
            // next item fits exactly-ish in leftover: strong reward
            let gap = pr - nxt;
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 200.0;
            }
        } else {
            // leftover too small for next item: penalize dead space, worse if tiny
            let dead = pr;
            if dead > 0.0 && dead < 10.0 {
                score += 40.0;
            }
            score += 0.3 * dead;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large or many bins open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64;
        score += 120.0 - 0.5 * pressure - 30.0 * progress;
        if item_size >= 70 {
            score -= 80.0; // large items fine in fresh bin
        }
    }

    // Slight preference for filling larger residual bins with large items
    score -= 0.1 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powi(2));

    // Penalize dead space that no future item can plausibly fill.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 6.0; // next item won't fit here; wasted capacity
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, more when many bins are open or early stream.
    if bin_residual == bin_capacity {
        let mut penalty = 10.0 + 2.0 * open_bins_count as f64;
        penalty *= 1.0 - 0.5 * progress; // more willing to open bins late
        // Opening a new bin is attractive if no bin fits well (large residual gap).
        let gap = (bin_residual as f64 - item_size as f64).max(0.0);
        if gap > 30.0 {
            penalty -= 12.0; // poor fit elsewhere -> new bin OK
        }
        score += penalty.max(0.0);
    }

    // Prefer bins below mean residual (keeps residuals balanced).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep base on normalized residual
    let coupling = poly * (0.5 + progress) * cap;

    // Perfect fit bonus (strongly subtract)
    let mut score = pr + 0.35 * coupling;
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (next_item_size as f64 - pr);
    }
    // Reward residual that exactly accommodates the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin before opening a new one: reward using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Mild pressure toward consolidation when many bins are open
    score += 0.05 * (open_bins_count as f64) * (x - 0.5).abs();

    // Late-stream tightness: prefer tighter fills as stream progresses
    score -= (1.0 - x) * progress * 8.0;

    // New-bin candidate: mildly discouraged unless existing residuals are poor
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - (cap - item_size as f64)).abs();
        if mean_residual < item_size as f64 {
            score -= 10.0; // nothing fits well -> open new bin
        } else {
            score += 20.0 + mean_gap * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 act as "dead-space classes"
    let residue = post_residual % 10;
    score += residue as f64 * 0.35;

    // Perfect (or near-perfect) fits get strong rewards
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Integer-division thresholds: post_residual bucketed by quarters of capacity
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score -= 8.0; // small leftover is efficient
    } else if post_residual > 3 * quarter {
        score += 10.0; // large leftover means wasteful fill
    }

    // Lookahead coupling: reward leaving space exactly usable by next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            // harmonic class: gap that is itself a small residue is good
            score -= 10.0 - (gap % 10) as f64 * 0.5;
        } else {
            // next item cannot use this bin's leftover; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last-chance bin before opening a new one: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New empty bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // prefer new bin when mean residual is large (open bins are fragmented)
        score += 15.0 - pressure * 25.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin can serve future big items too
        }
    }

    // Early stream: be slightly conservative with open bins (keep flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A post_residual that is too small for the smallest item (1) is pure waste,
    // but gaps below a "usefulness threshold" are far less valuable.
    let dead_threshold = 8.0;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    } else {
        // Reward leaving a gap that could fit a typical small/medium item
        score -= 6.0;
    }

    // Perfect fit bonus: post_residual == 0 is ideal
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this bin (chain of good fits).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }
    // Penalize if post_residual is just barely too small for the next item
    // (dead space relative to known future demand).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // rather than spreading; with few open bins, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 5.0 * pressure;

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already "dense"; finishing it is good.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= 3.0 * diff.min(50.0) / 10.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // unattractive unless the item is large and no good fit exists.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild non-linearity
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 20.0;

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly well
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect 2-step match: chain two items into this bin
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (gap / 100.0).min(1.0);
        }
    }

    // Relative to mean residual: prefer bins that are already more filled than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 18.0 - 20.0 * fragmentation; // cheap to open new bin when others are nearly full
        if next_item_size > 0 && next_item_size > bin_residual {
            score += 5.0; // next item can't fit an empty bin anyway (unlikely), mild guard
        }
        // early stream: opening fresh bins is cheap and useful
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress);
    }

    // Slight preference to fill bins with larger items first (bigger item in tighter bin)
    score -= (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near zero).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 40.0;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.6;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * fill_frac * 25.0 * (open_bins_count as f64).ln().max(1.0);

    // Global state coupling: if this bin's residual is far below mean residual,
    // it is "dirtier" than average; slight penalty to encourage even filling.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // Time horizon: early in stream, be more willing to open new bins
    // (score for empty bin relatively higher); late in stream, pack tightly.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate score: baseline cost of a fresh bin, discounted early.
        score = 95.0 - 30.0 * (1.0 - progress) + 20.0 * progress;
        if fitting_bins_count == 1 {
            score += 70.0; // don't abandon a last-chance bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 10.0;
        }
    } else {
        // Late stream: tighten more aggressively.
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening
    let mut score = pr * (1.0 + 0.5 * (pr / cap).powi(2));

    // Stream-progress coupling: early on, keep bins flexible (penalize small residuals mildly);
    // late in the stream, squeeze harder (reward small post_residual more aggressively)
    let squeeze = 1.0 + 1.5 * progress * progress;
    score *= squeeze;

    // Non-linear interaction: normalized residual vs mean residual deviation
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev - 4.0 * dev * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward if next item fits in post_residual (smooth term)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt) / cap;
        let fits_next = if gap >= 0.0 { 1.0 } else { 0.0 };
        score -= 6.0 * fits_next * (-gap.abs() * 6.0).exp() * (1.0 + fit);
        // Penalize leaving residual that neither fits next item nor is useful
        score += 3.0 * (1.0 - fits_next) * (1.0 - (pr / cap).powi(2));
    }

    // Mild penalty for spreading across many open bins early (encourage consolidation)
    score += 0.15 * open_bins_count as f64 * (1.0 - progress) * fit;

    // Slight preference to fill existing bins over opening new ones
    if bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is a multiple of 10
    // are "usable" for typical item sizes; odd leftovers are dead space.
    let pr = post_residual;
    let class = pr % 10;
    score += match class {
        0 => -12.0,                 // perfectly harmonic leftover
        1 | 9 => 6.0,
        2 | 8 => 3.0,
        3 | 7 => 1.0,
        4 | 6 => -1.0,
        _ => 4.5,                   // class 5: half-cap dead space
    };

    // Integer-division thresholds: leftover usable by next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here -> strong reward, scaled by tightness
            let tight = (pr - next_item_size) as f64;
            score -= 10.0 - (tight / 10.0).min(8.0);
        } else {
            // next item cannot use this leftover -> penalize proportional dead gap
            score += ((next_item_size - pr) as f64) * 0.35;
        }
        // exact pairing bonus: leftover exactly equals next item
        if next_item_size == pr {
            score -= 8.0;
        }
    } else {
        // last item: just minimize leftover
        score += 0.0;
    }

    // Capacity-fraction coupling: reward leaving residual near small divisors of capacity
    let frac = pr as f64 / bin_capacity as f64;
    if (frac - 0.5).abs() < 0.02 {
        score += 5.0; // half-empty bin is risky dead space
    }
    if frac < 0.1 {
        score -= 4.0; // nearly full bin: great packing
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let base = 25.0;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score = base + scarcity + (open_bins_count as f64) * 0.5;
        // late in stream, prefer reusing bins
        if total_items > 0 {
            let t = step_index as f64 / total_items as f64;
            score += t * 10.0;
        }
        // if next item is huge, opening fresh bin may be wise
        if next_item_size >= 60 && (bin_residual < next_item_size) {
            score -= 12.0;
        }
    }

    // Mean residual context: if this bin is far below mean residual, it's a good filler
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.15;
    } else {
        score += (-dev) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to plausibly
    // fit any future item (min item size 1, but realistically small slivers)
    // are heavily penalized. Treat gap <= 15 as near-dead space, ramping up.
    let gap = post_residual as f64;
    if gap < 15.0 {
        score += (15.0 - gap) * 6.0; // steep penalty for unusable slivers
    } else if gap < 30.0 {
        score += (30.0 - gap) * 1.5; // mild penalty for medium gaps
    } else {
        // Large residual: slight reward to encourage filling big bins first
        score -= gap * 0.1;
    }

    // Perfect fit gets a strong bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward it
    if next_item_size > 0 && next_item_size as f64 == gap {
        score -= 25.0;
    }
    // Penalize leaving a gap just below the next item's size (near-miss dead space)
    if next_item_size > 0 && gap > 0.0 && (gap - next_item_size as f64) < 3.0 && gap >= next_item_size as f64 {
        score += 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    // Applied as a penalty on the new-bin candidate (bin_residual == bin_capacity)
    // and scaled by the number of open bins.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * open_bins_count as f64;
    } else {
        // Reward using existing bins more when many bins are open
        score -= open_bins_count.min(10) as f64 * 1.2;
    }

    // Mean residual coupling: if open bins are already loose on average,
    // prefer this bin less if it leaves a big gap (spread capacity instead).
    if gap > mean_residual {
        score += (gap - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - gap) * 0.2;
    }

    // Late-stream tightening: as the stream progresses, be more aggressive
    // about packing tightly (avoid opening new bins late).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 25.0;
    } else {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit, but with diminishing returns for tiny residuals
    score = score * (1.0 + 0.02 * (post_residual as f64).sqrt());

    // 2-step lookahead: exact match of post_residual to next item is excellent
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // If next item can also fit into this bin after placement, reward it
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - 0.1 * slack;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: next item won't fit here -> penalize proportionally
        let dead = (next_item_size - post_residual) as f64;
        score += 0.35 * dead.min(40.0);
    }

    // Relative to mean residual: placing in a below-average-residual bin is good
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild pressure against proliferating bins late in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: make it attractive only when the item is large
    if bin_residual == bin_capacity {
        score -= 5.0 + 0.3 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste relative to capacity
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 18.0;

    // Penalize small unusable residuals (dead space), especially < next item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 0.6;
    }

    // Lookahead: reward leaving space exactly usable by the next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score -= 14.0 / (1.0 + diff as f64);
    } else {
        // Last item: prefer minimal leftover
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless it is genuinely useful
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base_penalty = 12.0 + 20.0 * (1.0 - progress);
        // Opening a new bin is more attractive when mean residual of open bins is low
        score += base_penalty - mean_residual * 0.35;
        // If no open bin can fit (fitting_bins_count == 0 semantics aside), new bin is fine
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Crowd control: many open bins -> prefer consolidating into existing ones
    score += open_bins_count as f64 * 0.4;

    // Mild time pressure: late in the stream, keep bins tighter
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.15;

    // Deviation from mean residual: prefer bins whose residual is below average (denser bins)
    score += ((bin_residual as f64 - mean_residual) / (bin_capacity as f64)) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress;
    score += 40.0 * coupling;

    // Reward tight fits, penalize large dead space non-linearly
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * item_size as f64 * 0.3;

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item can use post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - (nxt / (pr + 1.0)) * (nxt / (pr + 1.0)));
        } else {
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // Mean residual context: prefer bins close to mean (balance) early, extreme fits late
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 20.0 * (1.0 - progress) - dev.abs() * 5.0 * progress;

    // Mild penalty for opening new bins when many bins already fit the item
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 12.0 + 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality classes.
    // Class 0: perfect fit (0). Class 1: tiny unusable sliver (1..=5).
    // Class 2: medium usable (6..=15). Class 3: large useful remainder (>15).
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit: strongly reward
    } else if pr <= 5 {
        score += 25.0; // dead sliver: penalize
    } else if pr <= 15 {
        score += 8.0; // awkward medium gap
    } else {
        score -= 6.0 + (pr as f64) * 0.15; // large remainder still useful
    }

    // Modular structure: post_residual divisible by common item sizes is reusable.
    if pr > 0 {
        let reusable = [10u32, 20, 25, 30, 40, 50];
        for m in reusable {
            if m <= pr && pr % m == 0 {
                score -= 10.0;
                break;
            }
        }
    }

    // Coupling with lookahead: if next item fits exactly into post_residual,
    // this bin remains perfectly harmonic across two steps.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let npr = post_residual - next_item_size;
            if npr == 0 {
                score -= 20.0;
            } else if npr <= 5 {
                score += 10.0; // chains into dead space
            } else {
                score -= 4.0;
            }
        } else {
            // next item cannot fit here: residual likely stranded
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer tightest bins via residual fraction.
    score += (bin_residual as f64 / bin_capacity as f64) * 12.0;

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses or many bins open.
        score += 15.0 + 40.0 * progress + (open_bins_count as f64).sqrt() * 3.0;
        // But if nothing fits elsewhere it competes fairly (fitting_bins_count==0 handled by caller).
    }

    // Slight preference for bins tighter than average (fragmentation control).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small for the
    // minimum plausible future item are "dead". Penalize them quadratically.
    let dead_threshold = 12.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * (dead_threshold - pr) * 1.5;
    }

    // Medium gaps (just above typical small items) waste capacity; slight penalty.
    if pr >= dead_threshold && pr < 30.0 {
        score += (30.0 - pr) * 0.6;
    }

    // Reward perfect / near-perfect fits strongly.
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 5 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins; when many bins
    // are open, tighten preference for tight fits (amplify post_residual).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * pr * 0.05;

    // Lookahead: if the next item can use the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0;
    } else if next_item_size > 0 && pr > 0.0 {
        // Next item cannot use the leftover: penalize proportional to leftover.
        score += pr * 0.3;
    }

    // Slight global tightness: when mean residual is high, prefer consuming
    // the fullest bins (lower post_residual already does this; add coupling).
    score -= mean_residual * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: leftover exactly fits the next item -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Leftover still usable by next item: reward proportionally,
            // extra credit when the remainder after the next item is small.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - slack * 0.15;
        } else {
            // Leftover too small for the next item: penalize dead space,
            // worse when it is a tiny unusable sliver.
            let dead = post_residual as f64;
            score += dead * 0.5;
            if dead > 0.0 && dead < 10.0 {
                score += 15.0;
            }
        }
    } else {
        // Last item: just minimize leftover.
        score += post_residual as f64 * 0.2;
    }

    // Exact fill of the bin is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Compare against mean residual: placing into a bin with residual far
    // below the mean concentrates waste; placing into a large-residual bin
    // keeps small residuals available elsewhere.
    let res = bin_residual as f64;
    if res < mean_residual {
        score += (mean_residual - res) * 0.3;
    } else {
        score -= (res - mean_residual) * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild late-stream consolidation: fewer open bins relative to progress
    // encourages closing out bins as the stream ends.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.8 {
            score += open_bins_count as f64 * 0.5;
        }
    }

    // Discourage opening a new bin when a decent fit exists in an open bin.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 20.0 + post_residual as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual relative to capacity (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that likely cannot be reused: post_residual below
    // the minimum plausible item size is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't chain here: mild penalty scaled by how far off.
        score += 0.15 * (next_item_size as f64 - post_residual as f64).max(0.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins are crowded or the item fits perfectly.
    if bin_residual == bin_capacity {
        if item_size == bin_capacity {
            score -= 100.0; // perfect fit: always open new bin
        } else if mean_residual < item_size as f64 * 0.9 {
            score -= 6.0; // existing bins too full on average
        } else {
            score += 15.0 + 0.2 * mean_residual; // discourage wasting open space
        }
    }

    // Global state: with many open bins, prefer consolidating into fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    score -= 0.03 * (bin_residual as f64 - mean_residual).max(0.0);

    // Late-stream consolidation pressure: as stream ends, avoid opening bins.
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit_ratio = item_size as f64 / cap;

    // Base: post residual, with non-linear penalty for awkward leftover space
    let mut score = pr;

    // Smooth quadratic coupling: mid-range residuals are least useful
    let awkward = norm_pr * (1.0 - norm_pr);
    score -= 12.0 * awkward * (1.0 - fit_ratio);

    // Stream-progress modulation: late in the stream, tight fits matter more
    let urgency = progress * progress;
    score -= 15.0 * urgency * fit_ratio * (1.0 - norm_pr);

    // Reward using nearly-full bins (small post residual) more strongly over time
    score -= 8.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Dead-space penalty grows with leftover size, amplified by bin count pressure
    score += 0.05 * pr * pr / cap * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Lookahead: penalize if the next item cannot use this bin's leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += 6.0 * progress * (1.0 - pr / nxt.min(cap));
        } else {
            score -= 4.0 * (pr - nxt) / cap;
        }
    }

    // Mild preference away from bins already near mean residual (diversity of fills)
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: discourage opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / cap);
        score = pr + 10.0 + 25.0 * avg_tightness * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect fits are best, tiny slivers are dead space.
    match post_residual {
        0 => score -= 1000.0,                       // perfect fit
        1..=5 => score += 60.0,                     // unusable sliver
        6..=10 => score += 25.0,
        11..=20 => score += 5.0,
        21..=40 => score -= 10.0,                   // useful mid-range gap
        _ => {}
    }

    // Modulo-10 harmony: leftover divisible by 10 pairs well with typical item sizes.
    let rem10 = post_residual % 10;
    if rem10 == 0 {
        score -= 15.0;
    } else if rem10 >= 8 {
        score += 10.0;
    }

    // Capacity-fraction classes of the bin's fill level.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill > 0.9 {
        score -= 40.0;                              // nearly full: close it out
    } else if fill > 0.7 {
        score -= 20.0;
    } else if fill < 0.3 && post_residual != bin_capacity {
        score += 8.0;                               // barely touched bin: deprioritize
    }

    // Lookahead coupling: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 30.0 - (gap as f64).min(30.0);
        } else {
            // next item cannot use this residual; penalize small residuals more
            if post_residual < next_item_size && post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && post_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when existing bins are crowded or fit is bad.
    if post_residual == bin_capacity {
        let crowding = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 - 60.0 * crowding.min(2.0) - 30.0 * progress;
        if item_size > 70 {
            score -= 25.0;                          // huge items: fresh bin is fine
        }
    }

    // Mean-residual context: if this bin's residual is far below average, it's an outlier worth filling.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= 0.3 * dev.min(50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny post-residuals are unusable
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual tightly matches the item (good fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins
    score += 3.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly
    if bin_residual == bin_capacity {
        score += 15.0; // default mild penalty
        if tightness > 0.5 || fitting_bins_count == 0 {
            score -= 80.0; // open new bin when fits are poor / none
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 30.0; // next item needs space; fresh bin helps
        }
    }

    // Lookahead coupling: if next item fits the post-residual well, reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / 20.0);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 15.0; // post-residual unusable for lookahead
    }

    // Progress: late in stream, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: exact match with next item is gold.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 / (1.0 + diff));
        // Penalize post_residual that can't fit the next item (dead space for lookahead).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
        // Reward post_residual slightly above next item (usable for it).
        if post_residual >= next_item_size && post_residual <= next_item_size + 20 {
            score -= 10.0;
        }
    }

    // Relative to mean residual: bins below mean residual are more "loaded"; prefer them.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless no good fit exists.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Allow new bin late in stream or when few bins fit (future flexibility).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Prefer filling bins when many are open (consolidation pressure).
    score -= 0.05 * open_bins_count as f64;

    // Progression: tighten packing as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is already good, amplify it.
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else {
        let pr = post_residual as f64;
        // Dead-space penalty grows super-linearly for small residuals that
        // can no longer fit typical items.
        if pr < 10.0 {
            score += 8.0; // tiny sliver, nearly useless
        } else {
            score -= (10.0 / pr) * 4.0; // mildly reward larger leftover utility
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 45.0; // next item fills bin perfectly
            } else if slack < 10.0 {
                score -= 25.0;
            } else {
                score -= 12.0 * (10.0 / (slack + 10.0));
            }
        } else {
            // Next item cannot fit here; slight penalty proportional to gap.
            score += (nxt - pr).min(30.0) * 0.3;
        }
    }

    // Last-chance dynamics: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is costly; make the empty
    // bin attractive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score += 30.0;
        // If few alternatives fit, opening is fine.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // If open bins have plenty of residual space on average, discourage waste.
        if mean_residual > (bin_capacity as f64) * 0.5 && fitting_bins_count > 2 {
            score += 20.0;
        }
    } else {
        // Favor reusing bins with lower residual relative to the mean
        // (compact the bins, keep large gaps free for big items).
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.4;
        // Mild bonus for keeping the number of open bins in check early on.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += open_bins_count as f64 * (1.0 - progress) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 + progress);
    score += 40.0 * poly;

    // Penalize wasted space more strongly as stream progresses
    score += progress * x * 20.0;

    // Reward tight fits (small post residual) smoothly
    score -= (1.0 - x) * (1.0 - x) * 15.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: penalize if next item cannot use this residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx) / cap;
        if gap < 0.0 {
            score += 12.0 * (-gap).powf(1.5);
        } else {
            score -= 8.0 * gap * (1.0 - gap);
        }
    }

    // Encourage spreading across bins via mean residual deviation
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 and 25
    let pr = post_residual as u32;
    let mod10 = pr % 10;
    let mod25 = pr % 25;

    // Dead-space classes: tiny unusable gaps are worse than moderate gaps.
    // Penalize post_residual in (0,10) heavily — nothing (min item 1) may still fit well.
    if pr > 0 && pr < 10 {
        score += 25.0 - pr as f64; // dead space penalty, worst near 9
    }
    // Harmonic sweet spots: residuals that are multiples of 25 or 10 are reusable
    if pr == 0 {
        score -= 30.0; // perfect fill
    } else if mod25 == 0 {
        score -= 12.0;
    } else if mod10 == 0 {
        score -= 6.0;
    } else {
        // fractional-capacity coupling: distance to nearest harmonic fraction
        let frac = pr as f64 / cap;
        let harm = (frac * 4.0).round() / 4.0; // nearest quarter of capacity
        score += (frac - harm).abs() * 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == pr {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // reward if next item also lands on a harmonic class after pairing
        let after = pr - next_item_size;
        if after % 25 == 0 { score -= 10.0; }
        else if after % 10 == 0 { score -= 5.0; }
        else if after < 10 { score += 8.0; }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item won't fit here regardless; slight penalty for wasting this bin's future
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer tight fits overall: reward small post_residual relative to item size
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    // New-bin candidate handling: only open a new bin when no open bin fits well
    let is_new = bin_residual == bin_capacity;
    if is_new {
        // new bin baseline: attractive if few fitting bins or mean residual is small
        score = 55.0 - (fitting_bins_count as f64) * 8.0 - mean_residual * 0.3;
        if open_bins_count == 0 { score -= 50.0; }
    } else {
        // existing-bin bonus scaled by stream progress (consolidate early, stay flexible late)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 5.0;
    }

    // Mild coupling with mean residual: prefer bins below mean (tighter bins)
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps much harder.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Penalize wasted large residual when the bin was nearly full already.
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 0.8;
    }

    // Open bins pressure: more open bins -> prefer filling existing bins,
    // penalize opening new ones.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Last chance bin: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && !new_bin_candidate {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover < 10 {
            score -= 35.0;
        } else {
            score -= 8.0;
        }
    }
    // If next item would NOT fit in post_residual, mild penalty for creating dead space.
    else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Progression: late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if new_bin_candidate {
        score += 10.0 * (1.0 - progress);
    }

    // Mean residual coupling: if mean residual across bins is high, prefer
    // bins that reduce dispersion (post_residual close to mean).
    let disp = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * disp;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if next item exactly fits post_residual, strongly reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // dead space relative to next item
            score += 30.0 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare against mean residual: bins with small residual (tight) preferred
    let diff = mean_residual - bin_residual as f64;
    score += 2.0 * diff;

    // Last chance bonus: if only this bin can fit the item, use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalize opening new bins late in stream when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 150.0 + 100.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer using nearly-full bins
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space).
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tight * 4.0).max(0.0);

    // Penalize leaving residuals that no typical item can use (dead space below min item size).
    if post_residual < item_size.min(10).max(1) {
        score += 50.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward if the next item fits into the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // extra reward for a snug lookahead fit
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // spread load: mildly prefer bins with more residual than the mean
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, pack aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 12.0 * (1.0 - tight);

    // Prefer fuller bins overall (residual closer to item_size means tighter fit already captured).
    score += 0.03 * (open_bins_count as f64);

    // New-bin candidate: penalize opening a new bin unless the item is large and fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let mut new_bin_penalty = 55.0;
        // large items are hard to place later; opening a bin for them is less bad
        new_bin_penalty -= 40.0 * fill_ratio;
        // if many bins fit the item, no reason to open a new one
        if fitting_bins_count > 1 {
            new_bin_penalty += 30.0;
        }
        // late in stream with many open bins, prefer consolidation
        if progress > 0.7 {
            new_bin_penalty += 15.0 * progress;
        }
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear (quadratic/cubic) shaping.
    let mut score = pr + 40.0 * norm_pr * norm_pr + 25.0 * norm_pr * norm_pr * norm_pr;

    // Smooth stream-progress coupling: later in the stream, dead space matters more.
    let tightness = 1.0 + 1.5 * progress * progress;
    score *= tightness;

    // Perfect fit reward (smooth, non-piecewise).
    let perfect = (pr / cap).powi(2);
    score -= 30.0 * (1.0 - perfect.min(1.0)) * (if pr == 0 { 1.0 } else { 0.0 } as f64).max(0.0);
    if pr == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but not perfectly: mild reward scaled by fill ratio
        let r = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * r * r;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this dead space: penalize proportionally
        score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly early, more when open bins are well-filled.
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score = cap * (1.2 + 0.5 * progress) - 30.0 * mean_fill * mean_fill;
        // encourage new bin when existing residuals are all poor for this item
        let waste = (bin_residual - item_size) as f64;
        if fitting_bins_count > 0 && waste > 40.0 {
            score -= 15.0;
        }
    }

    // Mild penalty for bin fragmentation relative to mean residual.
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "useful" modular classes.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Perfect-fit reward
    if pr == 0 {
        score -= 1000.0;
    }

    // Harmonic class: residuals divisible by small divisors pair well with
    // typical item sizes; penalize residuals in "dead" ranges.
    if pr % 10 == 0 {
        score -= 8.0; // clean decade residual, highly reusable
    } else if pr % 5 == 0 {
        score -= 4.0;
    }

    // Dead-space thresholds: residuals below typical minimum item size are nearly useless.
    if pr > 0 && pr < 10 {
        score += 60.0;
    } else if pr < 20 {
        score += 12.0;
    } else if pr < 30 {
        score += 3.0;
    }

    // Integer-division class of next_item_size: if next item fits exactly into
    // post_residual, strongly reward (lookahead pairing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            // how many times next item divides into post residual
            let k = pr / next_item_size.max(1);
            score -= 10.0 * k.min(4) as f64;
            // penalize leaving a sliver the next item barely misses
            if pr < next_item_size && pr >= 1 {
                score += 15.0;
            }
        } else {
            // next item won't fit here; mild penalty proportional to gap
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when current bin would leave
    // bad dead space or stream is early with few open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream position.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 30.0 + 25.0 * progress;
        // If this bin would be very full (item large), opening fresh is fine.
        if (item_size as f64) / cap > 0.7 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Tightness reward: prefer bins where item fills a large fraction of residual.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_frac;

    // Prefer bins below mean residual (consolidate emptier space usage pattern:
    // actually prefer filling fuller bins -> penalize bins above mean residual).
    if bin_residual as f64 > mean_residual + 1.0 {
        score += 0.2 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: small post_residual gaps (< 10) are unusable
    // since items are at least size 1..100; penalize gaps that no plausible item fits.
    if post_residual > 0 && post_residual < 10 {
