    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement (chained packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 5.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins rather than opening new ones.
    score += (open_bins_count as f64) * 0.8;

    // New-bin candidate handling: an empty bin has high post_residual;
    // make it attractive only when the item is large relative to capacity
    // or no good fit exists (implicit via baseline comparison).
    if bin_residual == bin_capacity {
        // Neutral baseline for a fresh bin: post_residual = capacity - item.
        // Penalize slightly so tight fits in open bins win, but keep it
        // competitive against bins that would leave dead space.
        score += 10.0;
        // If item is large, a fresh bin is often best.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Mild preference for bins with residual below mean (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small post_residual).
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 25.0;
    }

    // 2-step lookahead: reward when next item exactly fills the leftover space.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 == next_item_size as i64 {
            score -= 80.0; // perfect chain: bin closes after next item
        } else if next_item_size as u32 <= post_residual {
            score -= 40.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 10.0 + gap * 0.3;
        }
    }

    // Compare against mean residual: prefer bins whose residual deviates well.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(30.0) * 0.5;
    } else {
        score += (pr - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin, unless it enables a
    // perfect 2-step chain that no open bin offers.
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 30.0;
        }
    }

    // Late in the stream, be more conservative: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can't fit typical items: post residual in awkward zone (1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.3 * next_item_size as f64;
    }
    // If next item doesn't fit but nearly fits, mild penalty for stranding space.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 0.2 * (next_item_size - post_residual) as f64;
    }

    // Prefer fuller bins relative to mean residual of open bins.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.5 * diff;
    } else {
        // New-bin candidate: penalize mildly, more when open bins exist and fit well.
        score += 15.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).sqrt();
        }
        // Early in stream, new bins are cheaper to open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Slight penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    // Reward exact fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post_residual, with non-linear coupling to stream progress.
    // Early in the stream, keep residuals flexible (mild penalty);
    // later, compactness matters more (steeper penalty on large residuals).
    let mut score = pr * (0.5 + 1.5 * progress * progress);

    // Smooth non-linear term: reward filling the bin tightly (post_residual near 0)
    // using a saturating exponential of the normalized residual.
    score += 12.0 * (1.0 - (-3.0 * norm_pr).exp()) * (0.5 + progress);

    // Polynomial coupling between post_residual and progress:
    // large residuals become increasingly costly as the stream advances.
    score += 8.0 * norm_pr * norm_pr * (0.3 + progress) * (0.3 + progress);

    // Lookahead coupling: if the next item fits into the post_residual,
    // reward this bin; scale reward by how well it fits (smoothly).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - ((pr - nxt) / cap);
            score -= 6.0 * fit_quality * (1.0 + progress);
        } else {
            // Next item does not fit: gently penalize leaving awkward gaps
            let gap = (nxt - pr) / cap;
            score += 4.0 * gap * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 * (1.0 - norm_pr);
    }

    // Mild preference for bins with below-mean residual (tighter bins first),
    // smoothly interpolated.
    let mean_diff = (mean_residual - bin_residual as f64) / cap;
    score += 2.0 * mean_diff * (1.0 + progress);

    // Slight penalty for proliferating bins early on.
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: capacity/6 = 16.67 -> class boundaries
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Modulo classes on post_residual: leftovers that divide capacity cleanly are reusable
    let r = post_residual % (bin_capacity / 4).max(1);
    let harmonic_bonus = match r {
        0 => -12.0,                      // perfectly divisible leftover (25/50/75/100)
        _ => (r as f64) * 0.15,          // penalize off-class leftovers
    };
    score += harmonic_bonus;

    // Dead space penalty: tiny leftovers below smallest plausible next fit
    if post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits strongly
    let fill_ratio = item_size as f64 / cap;
    score -= fill_ratio * fill_ratio * 20.0;

    // Lookahead coupling: does post_residual fit the next item's harmonic class?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward if next item lands with small slack (good chain)
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // post_residual cannot host next item: penalize proportionally to wasted class
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 10.0;
        // cheaper to open a bin early when few bins exist or stream is early
        score -= (open_bins_count as f64).min(8.0) * 0.8;
        score -= progress * 8.0;
        // if many bins already fit this item, opening new is bad
        if fitting_bins_count > 1 {
            score += 20.0;
        }
        // if next item is large and this item is small, opening fresh bin preserves big slots
        if next_item_size > 0 && next_item_size > item_size * 2 {
            score -= 12.0;
        }
    }

    // Mean residual alignment: prefer bins whose residual is close to the mean (balanced packing)
    let dev = ((bin_residual as f64) - mean_residual).abs();
    score += dev * 0.05;

    // Mild tie-break toward fuller bins late in the stream
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use
    // are heavily penalized. Anything below the smallest possible item (1)
    // is pure waste; small gaps below next_item_size are likely waste too.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill: best possible outcome
    } else if post_residual < 10 {
        score += 200.0; // unusable sliver
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 60.0 + 0.5 * (next_item_size - post_residual) as f64;
    } else {
        // Usable leftover: mild reward scaled by how well it hosts next item
        if next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 - slack / bin_capacity as f64).min(1.0);
        }
    }

    // Reward tight fits (item fills most of the residual)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage fragmenting further
    // unless the fit is excellent; with few bins, be more permissive.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing fits are poor
        // (large dead space would be created elsewhere) or stream is late.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 20.0 * pressure - 15.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can host the lookahead item
        }
    } else {
        score += 3.0 * pressure * (1.0 - fill_ratio);
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (below-mean residual = already committed bin, use it up).
    score -= 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item still fits after this placement: mild reward proportional to tightness
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack / 20.0);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize creating dead space below next_item_size
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Penalize leaving tiny unusable slivers (dead space < 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Tight fit reward: waste relative to bin capacity
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste_ratio) * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
        // More open bins with high mean residual -> prefer reusing
        if mean_residual > item_size as f64 * 1.5 {
            score += 30.0;
        }
    }

    // Early stream: be more conservative with open bins (keep flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += 8.0 * (1.0 - progress / 0.3);
    }

    // Slight preference for bins with residual near mean (balanced usage)
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good; amplify near-perfect fits.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 8.0;

    // Penalize dead space that becomes unusable for typical items (small post_residual but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement: mild penalty scaled by mismatch.
        score += ((next_item_size - post_residual) as f64) * 0.15;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, prefer it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the current item
    // fits poorly everywhere (large post_residual in all bins) or late fragmentation.
    if bin_residual == bin_capacity {
        // Base reservation cost for opening a new bin.
        score += 35.0;
        // More attractive when existing bins have low mean residual (poor fits everywhere).
        score -= (mean_residual / bin_capacity as f64) * 20.0;
        // Less attractive when many bins could fit the item (good alternatives exist).
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 6.0;
        }
        // Early in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Prefer filling bins that are already relatively full (reduce bin count pressure).
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fullness * 5.0;

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear (quadratic/cubic) shaping
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth progress coupling: early stream tolerates slack, late stream punishes it
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * norm_pr * cap * 0.1;

    // Interaction of post_residual with mean residual: avoid creating residual unlike others
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * cap * 0.05;

    // Lookahead: reward if next item fits the post-residual (smooth kernel)
    if next_item_size > 0 {
        let fits = (pr - next_item_size as f64) / cap;
        let kernel = (-8.0 * fits * fits).exp();
        score -= 6.0 * kernel;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Penalize opening new bins when open bins exist and fit is decent
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // Exception: opening a new bin is fine if it would be nearly perfectly filled
        let perfect = (item_size as f64 / cap - 1.0).abs();
        score -= 15.0 * (-20.0 * perfect * perfect).exp();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space value classes
    let class = post_residual / 10; // 0..=10 harmonic buckets
    let phase = post_residual % 10;

    // Penalize residuals in "awkward" classes (small dead space that nothing fits)
    let awkward = match class {
        0 => 0.0,          // perfect fit
        1 => 22.0,         // residual 10-19: only tiny items fit
        2 => 14.0,         // residual 20-29
        3 => 18.0,
        4 => 8.0,
        5 => 4.0,          // half bin: very reusable
        6 => 6.0,
        7 => 10.0,
        8 => 12.0,
        9 => 9.0,
        _ => 0.0,          // full-ish / empty bin
    };
    score += awkward + phase as f64 * 0.15;

    // Reward tight fits: exact fill is ideal
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Harmonic coupling with lookahead item: if next item fits post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = (post_residual - next_item_size) as f64;
        score -= 20.0 + 0.5 * (100.0 - chain_quality).max(0.0);
    } else if next_item_size > 0 {
        // next item cannot chain here: penalize slightly if this bin becomes a trap
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: opening fresh bin is only attractive when current fit is bad
    if bin_residual == bin_capacity {
        // empty bin baseline: prefer it when item leaves a large, awkward residual elsewhere
        score = 55.0 + post_residual as f64 * 0.1;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        if open_bins_count == 0 {
            score -= 60.0; // must open first bin
        }
    }

    // Progress-based modulation: late in stream, consolidate harder
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates positively from the mean (larger holes)
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny gap is almost certainly dead space
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits strongly.
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open bins pressure: prefer consolidating into existing bins.
    score += (open_bins_count as f64) * 2.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 1.0;
        // But if the next item is large and this item fits poorly elsewhere, keep escape hatch
        if post_residual < 10 && next_item_size as f64 > mean_residual {
            score -= 55.0;
        }
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Mean residual coupling: avoid wasting bins with large residuals when mean is high.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

