        score -= 40.0 * (1.0 - diff / 100.0).max(0.0);

        // Perfect chain: post_residual exactly equals next item size -> strong reward.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If next item cannot fit into post_residual, penalize unusable dead space,
        // scaled by how large the dead space is.
