        score -= 30.0;
    }

    // Penalize opening a new bin when open bins exist, unless stream is early.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // New bin is acceptable if item is large and would leave tiny waste elsewhere.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild bonus for tight fits (small waste ratio).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 15.0 * (1.0 - waste_ratio) * (1.0 - waste_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (low post-residual).
    let mut score = post;

    // Reward excellent fits: small dead space relative to capacity.
    let fit_ratio = post / cap;
    if fit_ratio < 0.15 {
        score -= 25.0 * (0.15 - fit_ratio);
    }

    // Penalize very large leftover space that likely becomes dead space,
    // unless the bin is fresh (empty bin candidate).
    let is_empty_bin = bin_residual == bin_capacity;
    if !is_empty_bin && fit_ratio > 0.5 {
        score += 30.0 * (fit_ratio - 0.5);
    }

    // Lookahead: if next item could exactly fill this bin's post-residual,
    // strongly favor this bin (perfect pair).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            score -= 20.0 * (1.0 - gap / cap);
        } else {
            // Next item won't fit here; slight penalty scaled by mismatch.
            score += 8.0 * (gap / cap);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && !is_empty_bin {
        score -= 35.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (preserve flexibility); late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_empty_bin {
        // New-bin candidate: attractive early, expensive late.
        score = score * 0.5 + 40.0 * (1.0 - progress);
        // Opening a new bin is good if current mean residual is small (all bins tight).
        score -= (mean_residual / cap) * 30.0;
    } else {
        // Late stream: reward using existing bins more strongly.
        score -= 15.0 * progress;
        // If many bins are open and this bin is below mean residual, prefer it
        // (consolidate into emptier bins, keep tight bins available).
        if post as f64 > mean_residual {
            score += 5.0;
        } else {
            score -= 5.0;
        }
    }

    // Mild penalty for opening new bins when plenty already fit elsewhere.
    if is_empty_bin && fitting_bins_count > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress) - 12.0 * norm_pr * (1.0 - norm_pr) * (1.0 + progress);

    // Penalize large post-residuals more aggressively as stream progresses (dead space matters later)
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a super-linear bonus
    score -= 6.0 * (1.0 - norm_pr).powi(3);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 7.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards; mild penalty scaled by mismatch
        score += 4.0 * ((next_item_size as f64 - pr) / cap).max(0.0);
    }

    // Slight preference for bins with residuals below the mean (consolidating slack)
    score += 0.15 * ((bin_residual as f64 - mean_residual) / cap) * (1.0 + progress);

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: perfect fits (0) heavily rewarded,
    // small dead-space classes (1..=9) heavily penalized.
    let cls = (post_residual % 10) as f64;
    if post_residual == 0 {
        score -= 500.0; // perfect closure
    } else if post_residual <= 9 {
        score += 120.0 * (10.0 - cls) / 10.0; // unusable sliver penalty
    } else if post_residual <= 20 {
        score += 25.0;
    }

    // Reward residuals in "usable" harmonic classes divisible by common item sizes.
    if post_residual % 20 == 0 { score -= 40.0; }
    if post_residual % 25 == 0 { score -= 30.0; }
    if post_residual % 50 == 0 { score -= 20.0; }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 { score -= 60.0; } else { score -= 10.0; }
        } else {
            // next item cannot fit here: mild penalty scaled by dead space fraction
            score += 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin only when the current
    // fit is poor (large dead space) and many bins are open.
    if bin_residual == bin_capacity {
        let dead = post_residual as f64;
        let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0);
        score = 60.0 + dead * 0.5 - pressure.min(40.0);
        if next_item_size > 0 && next_item_size >= bin_capacity { score -= 200.0; }
    }

    // Slight bias toward tighter bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += (10.0 - dead) * 8.0; // tiny gaps are wasted capacity
        } else if dead < 20.0 {
            score += (20.0 - dead) * 2.0; // moderately risky gaps
        }
        // Reward perfect fits strongly.
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Reward tight fills relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.35 * (0.5 + progress);

    // New-bin candidate handling: empty bin gets a baseline cost so it is
    // only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 20.0; // next item will seal this bin nicely
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += (post_residual.min(next_item_size)) as f64 * 0.5; // dead space ahead
    }

    // Prefer bins already below mean residual (consolidating emptier space usage).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    score -= (bin_capacity as f64 - post_residual as f64).powf(1.5) * 0.05;

    // 2-step lookahead: reward bins whose post_residual exactly matches next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 40.0; // perfect chain: next item fills this bin exactly
        } else {
            score -= 20.0 * (-gap / 10.0).exp(); // near-chain reward decaying with gap
        }
    } else if next_item_size > 0 {
        // Penalize dead space that cannot fit the next item.
        score += 12.0;
    }

    // Relative to mean residual: prefer bins with residuals near/below mean
    // (concentrate filling in emptier bins to keep big residuals elsewhere).
    score += (mean_residual - bin_residual as f64).abs() * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make a fresh bin attractive only when it is
    // genuinely better than squeezing into existing bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a new bin
        } else if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Pairing lookahead: a fresh bin can host this item and the next one.
            score -= 18.0;
        } else {
            score += 15.0 + (fitting_bins_count as f64) * 3.0; // discourage wasting fresh bins
        }
    }

    // Late in the stream, prefer closing bins out (reduce fragmentation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual < 10 {
        score += 8.0;
    } else if post_residual < 25 {
        score += 3.0 * (25.0 - post_residual as f64) / 15.0;
    }

    // Lookahead: penalize if next item cannot fit into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 5.0;
            // Extra penalty if wasted space is close to next item size (near-miss).
            let gap = post_residual as f64 / next_item_size.max(1) as f64;
            if gap > 0.5 {
                score += 3.0 * gap;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is justified when existing fits are poor.
    if bin_residual == bin_capacity {
        // Slight bias against opening new bins when current bins are reasonably full.
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        score += 6.0 * mean_fill;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin can absorb the next item too
        }
    }

    // Time horizon: early in the stream, be more conservative (favor filling existing bins);
    // late in the stream, minimize bin count more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * fit_ratio;
    score += 2.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64);

    // Encourage consolidation when many bins are open.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 0.5 * (open_bins_count.min(20) as f64).ln() * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = post_residual as f64;
    let residual = bin_residual as f64;
    let cap = bin_capacity as f64;
    let size = item_size as f64;

    // Base: prefer tight fits (low post_residual), smoothly scaled by progress.
    let mut score = fit * (1.0 + 0.8 * progress * progress);

    // Non-linear coupling: post_residual squared penalizes dead space more as stream matures.
    let dead = (fit / cap).powi(2);
    score += 60.0 * dead * (0.4 + 0.6 * progress);

    // Reward filling bins deeply (couple item size with residual usage).
    score -= 15.0 * (size / cap) * (1.0 - fit / cap) * (1.0 - progress);

    // Last-chance bonus: only bin that fits — strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= fit {
        score -= 8.0 + 6.0 * (next_item_size as f64 / cap);
    }
    // If next item would NOT fit in post_residual, mild penalty growing with progress.
    if next_item_size > 0 && (next_item_size as f64) > fit {
        score += 5.0 * progress * (1.0 - fit / cap);
    }

    // Penalize spreading across many open bins mildly, scaled by mean residual.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap);

    // New-bin candidate: penalize opening a new bin when it wastes potential,
    // but relax the penalty late in the stream or when this is the only fitting option.
    let is_new_bin = (bin_residual as u32 == bin_capacity);
    if is_new_bin {
        let openness = (mean_residual / cap).clamp(0.0, 1.0);
        score += 30.0 * (1.0 - progress) + 40.0 * openness;
        if fitting_bins_count == 1 {
            score -= 45.0; // allow new bin if no open bin fits
        }
        if next_item_size > 0 && (next_item_size as f64) <= fit {
            score -= 10.0;
        }
    }

    // Smooth interaction term: post_residual * progress coupling.
    score += 0.05 * fit * progress * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 5.0)));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: values that other items can still fill well
    // Class A: post_residual divisible by 10 (matches common size granularity)
    if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    } else {
        // Odd dead-space penalty, stronger for small odd residuals
        score += (10 - (post_residual % 10)) as f64 * 0.8;
    }

    // If lookahead item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if post_residual - next_item_size <= 5 {
            score -= 60.0;
        } else if post_residual - next_item_size <= 15 {
            score -= 20.0;
        }
    } else if next_item_size > post_residual {
        // Lookahead can't use this residual: penalize proportional to wasted fraction
        let waste = post_residual as f64 / bin_capacity as f64;
        score += waste * 25.0;
    }

    // Integer-division thresholds on post_residual: tiny residuals are dead space
    let dead_class = post_residual / 10; // 0 => residual < 10 (nearly dead)
    score += match dead_class {
        0 => 45.0,
        1 => 18.0,
        2 => 6.0,
        _ => 0.0,
    };

    // Last-chance bonus: only bin that fits item
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: opening fresh bins early is fine, late is costly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = 30.0 + 60.0 * progress;
        // If current bin choice would leave bad residual, new bin becomes attractive
        let bad_fit = (post_residual > 0 && post_residual < 10) || (next_item_size > post_residual && post_residual < 20);
        if bad_fit {
            score -= 70.0;
        }
        score += base;
        // Prefer reusing open bins when mean residual is large enough
        if mean_residual > item_size as f64 + 10.0 {
            score += 15.0;
        }
    }

    // Mild pressure toward fuller bins as stream progresses
    score *= 1.0 - 0.15 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (< 10) are unusable, waste them heavily.
    if post_residual < 10 {
        score += 50.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Reward tight fits (small relative post-residual).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (penalize the empty-bin candidate implicitly via fitting count logic,
    // and add pressure proportional to open bins).
    score += (open_bins_count as f64) * 0.5;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slightly penalize leaving a gap
        // that nothing can use.
        score += 5.0;
    }

    // Prefer bins whose residual is below mean (consolidating fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match of post_residual with next item size
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 60.0; // perfect 2-step fit: chain continues exactly
        } else {
            // penalize leftover that next item cannot use well
            let usable = if gap >= 10.0 { gap } else { gap * 3.0 };
            score += usable * 0.5;
        }
    }

    // dead-space penalty: small post_residual is bad unless it's exactly zero
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // prefer tightest bins relative to mean residual
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // new-bin candidate: neutral-ish baseline, slightly worse than a good fit
    if bin_residual == bin_capacity {
        score += 15.0;
        // open a new bin if next item is huge and would fit fresh bin better
        if next_item_size > post_residual + item_size as u32 {
            score -= 10.0;
        }
    }

    // late in stream: consolidation matters more
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Penalize dead space: residuals too small for any item (min size 1..10 typical).
    let dead_threshold = 9.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Lookahead: reward if the next item fits exactly into the resulting residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0; // perfect pairing
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward more when the leftover after next item is small.
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to how much space is wasted relative to next item.
            score += 2.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Global pressure: many open bins with high mean residual -> encourage consolidating
    // into existing bins rather than opening new ones.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 1.5 * (mean_residual / bin_capacity as f64);
    }

    // Time horizon: early in the stream, keep bins open/flexible (mild penalty for very
    // small residuals that fragment bins); late in the stream, fill aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.5 {
        // Early: penalize leaving residuals in the awkward 10..30 range (hard to fill later).
        if post_residual >= 10 && post_residual <= 30 {
            score += 3.0;
        }
    } else {
        // Late: reward any placement into an existing bin.
        score -= 2.0 * progress;
    }

    // New-bin candidate (bin_residual == bin_capacity): make it unattractive unless
    // no decent existing option exists; the base post_residual is already large,
    // add a fixed opening cost offset.
    if bin_residual == bin_capacity {
        score += 5.0;
        // But if stream is late and mean residual is low, opening may still win via
        // other bonuses; keep offset moderate.
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, with smooth non-linear shaping (favor tight fits quadratically)
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post-residual with stream progress:
    // later in the stream, dead space matters more (smooth cubic ramp)
    let progress_coupling = 0.5 + 2.0 * progress * progress * progress;
    score += progress_coupling * norm_pr * cap * 0.3;

    // Smooth interaction: wasted space relative to next item's needs
    let next_norm = next_item_size as f64 / cap;
    let usable_waste = (pr - next_item_size as f64).max(0.0) / cap;
    score += (1.0 - next_norm) * usable_waste * usable_waste * cap * 0.6;

    // Reward near-perfect fits smoothly (gaussian-like bump around zero residual)
    score -= 6.0 * (-(norm_pr * norm_pr) / 0.01).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Smooth penalty when this bin deviates from mean residual (prefer balanced bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev * cap * 0.1;

    // New-bin candidate handling: empty bin gets a smooth penalty that decays
    // with progress and with how poorly the item would otherwise fit
    if bin_residual == bin_capacity {
        let openness = 1.0 / (1.0 + open_bins_count as f64);
        let urgency = (1.0 - norm_item).max(0.0);
        score += 8.0 * openness * (1.0 - progress) * (0.5 + urgency);
    }

    // Mild reward for bins that keep room for typical mid-size follow-ups
    score -= 0.4 * (-(norm_pr - 0.3).powi(2) / 0.08).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "usable"
    // residue classes (multiples of small denominators) are more attractive.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Reward exact small-integer fractions of capacity (perfect harmonic fits).
    for d in [1u32, 2, 4, 5, 10].iter() {
        if post_residual == bin_capacity / d && post_residual > 0 {
            score -= 18.0;
        }
    }

    // Penalize dead space: leftover that cannot fit typical items (1..100).
    // A residual < 10 (or < smallest plausible item) is nearly dead.
    if post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64; // small but nonzero residual is worst
    }

    // Modulo-10 classes: residuals divisible by 10 pair well with decile item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual > 0 {
        // distance to nearest multiple of 10 penalizes awkward leftovers
        let r = (post_residual % 10) as f64;
        let dist = r.min(10.0 - r);
        score += dist * 0.8;
    }

    // Harmonic coupling with the lookahead item: if next item fits the leftover,
    // strongly reward this bin (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.25 * (next_item_size as f64);
        // extra reward if leftover becomes exactly zero or a nice residue after next item
        let pr2 = post_residual - next_item_size;
        if pr2 == 0 {
            score -= 12.0;
        } else if pr2 % 10 == 0 {
            score -= 4.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_capacity {
        // leftover can't host the next item: mild penalty scaled by mismatch
        let gap = (next_item_size - post_residual) as f64;
        score += 0.15 * gap.min(40.0);
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline; discourage opening a new bin when
    // decent fits exist, encourage it when residual would be badly fragmented.
    if bin_residual == bin_capacity {
        // fresh bin score ~ its own residual minus a small opening cost
        score = cap_f - 20.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits anywhere: must open
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0; // room for a clean pair in a fresh bin
        }
    }

    // Progress-aware tightening: late in the stream, prefer filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * progress * (mean_residual - post_f).abs();

    // Prefer bins below the mean residual (fill the emptiest reasonable bins first
    // keeps large residuals available for large items), but not too aggressively.
    score += 0.10 * (post_f - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else if post_residual < 20 { 0.45 } else { 0.0 };
        score += dead * 60.0;
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 25.0;
        } else {
            score += 12.0; // creates a gap the next item cannot use
        }
        // Exact pairing: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Open-bin pressure: with many bins open, prefer filling existing ones
    // rather than spreading; a new-bin candidate gets penalized more.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 8.0 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction
    // of the residual (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Mean-residual coupling: prefer bins below mean residual (tighter bins),
    // spreading waste evenly is discouraged.
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Stream progression: later in the stream, be more conservative about
    // opening new bins (sunk cost of open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_gap = (post_residual - next_item_size) as f64;
        // Perfect 2-chain: item + next item exactly fills the bin.
        if lookahead_gap == 0.0 {
            score -= 120.0 + 40.0 * (1.0 - progress);
        } else {
            score -= 60.0 * (1.0 - lookahead_gap / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize dead space, worse when it's small.
        score += 0.5 * next_item_size as f64;
    }

    // Reward tight fits relative to bin capacity (small absolute post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Penalize residuals far above the mean residual (wasteful vs. fleet average).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate: only attractive when the item is huge relative to
    // typical residuals or the fit here is very poor.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.6 * bin_capacity as f64;
        if poor_fit && fitting_bins_count > 1 {
            score -= 35.0;
        } else {
            score += 20.0 + 30.0 * (1.0 - progress);
        }
    }

    // Mild penalty for scattering across many open bins late in the stream.
    score += 0.4 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no future item (min size 1) can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly in post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual as f64 - nxt;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            score += 4.0 * (nxt - post_residual as f64) / cap;
        }
    } else {
        // last item: prefer any bin, minimize post residual
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early in stream, prefer consolidating into existing bins;
    // late in stream, allow new bins more freely since fewer items remain
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bias = (1.0 - progress) * 15.0;
    if bin_residual == bin_capacity {
        score += new_bin_bias;
        // opening a new bin is good if mean residual across open bins is fragmented
        score -= (mean_residual / cap) * 8.0 * progress;
    }

    // Penalize spreading across many open bins when mean residual is high
    score += (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap) * 3.0;

    // Prefer bins whose residual is close to item size (best-fit flavor)
    let gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with a non-linear polynomial penalty
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post-residual with stream progress:
    // late in the stream, dead space becomes costlier
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Polynomial interaction between post_residual and mean residual:
    // placing into a bin whose residual is close to the mean is "typical";
    // reward smoothness via a quadratic term
    let mean_term = (pr - mean_residual) / cap;
    score += 8.0 * mean_term * mean_term * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead: if next item fits perfectly into post_residual, reward heavily
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if next_item_size as f64 <= pr {
            score -= 15.0 * (1.0 - gap / cap);
        } else {
            // penalize leaving a residual that the next item can't use
            score += 5.0 * (gap / cap);
        }
    }

    // Slight preference for consolidating into fewer bins when many are open
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Penalize wasteful near-empty placements (item barely reduces a large residual)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += 10.0 * (1.0 - fill_ratio) * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: prefer post_residual in "useful" classes
    let capacity = bin_capacity as f64;

    // Reward small post_residual (tight fit), with harmonic-class modulation
    let tightness = 1.0 - (post_residual as f64) / capacity;
    score -= 12.0 * tightness * tightness;

    // Harmonic classes: post_residual divisible structure (dead-space classes)
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fill
    } else {
        // class by residue modulo common item sizes
        let class_bonus: f64 = if pr % 10 == 0 {
            -6.0 // aligns with typical size grid
        } else if pr < 10 {
            8.0 // tiny unusable sliver
        } else {
            0.0
        };
        score += class_bonus;

        // Penalize residuals that no plausible next item can use
        if next_item_size > 0 && next_item_size > pr {
            score += 6.0;
        } else if next_item_size > 0 && next_item_size == pr {
            score -= 25.0; // next item exactly fills this bin
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 18.0;
        // If lookahead item is large and current item leaves bad residue, new bin less bad
        if next_item_size > 0 && post_residual > 0 && (post_residual % next_item_size.max(1)) != 0 {
            score -= 5.0;
        }
    }

    // Progress-based scaling: later in stream, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Prefer bins below mean residual (consolidate emptier bins)
    score += 0.15 * ((post_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: reward leaving space for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
