    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: prefer packing into existing bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // Penalize the brand-new empty bin unless item is large relative to capacity.
    if bin_residual == bin_capacity {
        score += (bin_capacity as f64) * 0.6 - (item_size as f64) * 0.6;
    }

    // Slight preference for tighter bins (larger item fraction of residual).
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
