pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < item_size.min(20) {
        score += 6.0; // near-dead space
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use the residual: penalize proportionally to waste.
            score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: empty bins should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases as stream progresses (fewer
        // future opportunities to fill it) and with many open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 45.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity / 2 {
            score -= 10.0; // roomy bin useful for upcoming larger items
        }
    } else {
        // Slight preference for filling bins that are already partially used
        // when the global mean residual is high (fragmentation pressure).
        let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 5.0 * frag * (bin_residual as f64 / bin_capacity as f64);
    }

    // Mild bonus for consolidating when many bins are open.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual (tight fit), non-linearly.
    let mut score = x * x * (1.0 + 2.0 * progress) * cap;

    // Smooth interaction: post residual vs. next item lookahead.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
