        score -= 12.0 * fit_quality * fit_quality * (1.0 - progress);
        // Penalize post residual that is too small for next item (dead space risk).
        let unusable = ((nxt - pr) / cap).max(0.0);
        score += 8.0 * unusable * unusable * cap;
