    // Last-chance bin: smooth reward for using the only fitting bin.
    if fitting_bins_count <= 1 {
        score -= 6.0 + 4.0 * progress;
    } else {
        // Mild penalty when many alternatives exist, scaled by waste.
        score += (fitting_bins_count as f64).ln() * x * 2.0;
