        }
        // Integer-division thresholds: leftover big enough for typical items is fine,
        // tiny unusable slivers are the worst.
        if post_residual < 10 {
            score += 60.0; // dead space below the minimum item size
        } else if post_residual <= 30 {
            score -= 10.0;
        } else if post_residual <= 60 {
            score += 0.0;
        } else {
            score += 8.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement chains nicely.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 40.0;
            } else {
                score -= 20.0 / (1.0 + (gap as f64 / 20.0));
            }
        } else {
            // next item cannot follow here; penalize more if leftover is small
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when open bins are congested
    // (mean residual small) or stream is early and we want many partial bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = (mean_residual - item_size as f64).max(0.0);
        score = cap * 0.9 - congestion * 2.0 + progress * 30.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: new bin is fine
        }
        if open_bins_count > 0 && mean_residual >= item_size as f64 + 5.0 {
            score += 100.0; // existing bins still roomy: discourage new bin
        }
    }

    // Mild preference for tighter bins overall.
    score -= (cap - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    let dead_threshold = 20.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }
    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward placements where this bin can also host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size > 0 {
        // Lookahead won't fit here; mild penalty if it leaves awkward gap.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, prefer filling.
    let pressure = open_bins_count as f64;
    score += pressure * 0.5 * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when open bins have poor fits
    // (item barely fits or would leave large unusable residue everywhere).
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        let open_pressure = if open_bins_count == 0 {
            -100.0
        } else if poor_fit < dead_threshold {
            -20.0 // current best placement would create dead space anyway
        } else {
            30.0 + mean_residual * 0.3
        };
        score += open_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: post_residual exactly matches next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect chain: next item fits with small slack left.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 25.0 - (post_residual - next_item_size) as f64;
    }
    // Penalize if next item cannot fit here (chain broken), scaled by wasted space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Relative to mean residual: bins tighter than average are good targets.
    score -= (mean_residual - post_residual as f64) * 0.6;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals of open bins are very tight.
    if bin_residual == bin_capacity {
        score += 55.0 - 0.35 * mean_residual;
    }

    // Late in stream: consolidate harder, avoid leaving many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Slight penalty for creating tiny unusable dead space (<10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on post-residual (dead space).
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0;
        }
        // Chain fit: post-residual exactly matches next item -> excellent.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins early in the stream when many bins are open.
        score += 20.0 + (open_bins_count as f64) * 0.5;
        // But reward new bin late in stream (consolidation matters less).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 15.0;
        // Attractive if the item is large relative to capacity (hard to place later).
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Prefer filling bins with larger residuals (below mean) to balance load.
    let res = bin_residual as f64;
    if res > mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Small item into big residual: mild penalty (wasteful pairing).
    if (item_size as f64) < res * 0.25 && !is_new_bin {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer tight fits, but weight tightness more as stream progresses.
    let mut score = pr / cap * (1.0 + 2.5 * progress * progress);

    // Non-linear penalty on dead space: unusable residual (< smallest plausible item) hurts.
    let dead = (pr / 40.0).max(0.0) - 1.0;
    if dead > 0.0 {
        score += dead * dead * (1.0 + progress);
    }

    // Smooth coupling of post_residual with mean residual: avoid bin that keeps mean high.
    let norm_mean = mean_residual / cap;
    score += 0.8 * (pr / cap) * norm_mean * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead: reward leaving residual that still fits the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 3.0 * (nx - pr) / cap;
        }
    }

    // Mild bonus for placing into a bin that exactly matches item size.
    score -= 2.0 * (1.0 - (pr / cap).powi(2)) * (item_size as f64 / cap);

    // New-bin candidate: prefer opening a new bin early or when fits are scarce.
    if bin_residual == bin_capacity {
        score += pr / cap * (1.0 + 0.15 * open_bins_count as f64 * (1.0 - progress));
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect closure.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead-space classes (small residuals)
    // are penalized; usable classes (large residuals) are rewarded.
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;
    let class = pr / 8; // integer-division threshold classes
    let class_score = match class {
        0 => -40.0,          // 0..7: near-closed, good
        1 => 30.0,           // 8..15: awkward dead space
        2 => 20.0,           // 16..23
        3 => 5.0,            // 24..31
        4 => -5.0,           // 32..39
        5 => -10.0,          // 40..47
        _ => -15.0,          // large residual: plenty of room left
    };
    score += class_score;

    // Modulo coupling: residual divisible by common item sizes is reusable.
    if pr > 0 {
        for m in [10i64, 20, 25, 50] {
            if pr % m == 0 {
                score -= 12.0;
            }
        }
    }

    // Lookahead: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 200.0; // chain of exact fits
        } else if slack <= 10 {
            score -= 60.0;
        } else {
            score -= (slack as f64).ln() * 8.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize proportionally.
        score += (next_item_size as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // the stream is early or open bins are fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bin when existing bins are tight (low mean residual)
        // and this item is large.
        let tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let large_item = (item_size as f64 / bin_capacity as f64) * 40.0;
        score += 90.0                      // base cost of opening a bin
               - tightness * 70.0
               - large_item
               - (1.0 - progress) * 30.0;  // early stream: fresh bins pay off
    }

    // Mild penalty for spreading across many open bins when mean residual is low.
    score += (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        score -= 40.0; // perfect fill
    }

    // If the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover: leftover is likely dead space.
        if post_residual < next_item_size {
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: penalize adding load when many bins are open,
    // but only mildly so it doesn't override dead-space logic.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins tighter than the mean residual (better fits).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Early in the stream, be slightly more willing to open fresh bins
    // for large items to keep structure clean.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty keeps it as fallback,
        // relaxed when the item is large or no bin fits well.
        let mut nb = 45.0;
        if item_size > 60 {
            nb -= 20.0;
        }
        if fitting_bins_count == 0 {
            nb -= 100.0;
        }
        if post_residual > 0 && post_residual < 10 {
            nb -= 30.0; // avoid creating slivers via new bin
        }
        score += nb * (1.0 - 0.3 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness: squared penalty on wasted space (dead space is quadratic bad).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Reward near-perfect fits strongly.
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead (k=2): if the next item can fit in the post-residual, this bin
    // remains useful -> reward; otherwise penalize leaving awkward leftovers.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else if next_item_size > bin_residual {
            // Next item won't fit here regardless; leftover waste matters less.
            score -= 4.0;
        } else {
            // Dead space trap: residual too small for the known next item.
            score += 15.0;
        }
    }

    // Last chance: this is the only open bin that fits the item.
    // Strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Crowding: many open bins -> encourage filling existing ones rather than
    // spawning more (encourages consolidation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + progress);

    // Relative residual vs mean: prefer bins with less residual than average
    // (use up the emptiest-but-fitting bins first, keep roomy bins flexible).
    score -= (mean_residual - bin_residual as f64) * 0.6;

    // New-bin candidate handling: an empty bin gets a baseline penalty so it is
    // only chosen when all fitting bins have poor scores (large post_residual).
    if bin_residual == bin_capacity {
        score += 55.0 + 20.0 * (1.0 - progress);
        // But if item is large relative to capacity, opening a fresh bin is
        // often fine/needed to avoid fragmenting other bins.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
        // If no open bin fits tightly, new bin is more attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Early stream: keep bins flexible (mild penalty for very tight commits early on).
    if progress < 0.2 && post_residual > 0 && post_residual < 10 {
        score += 8.0 * (1.0 - progress * 5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: keep residuals moderate (flexibility matters).
    // Late in the stream: strongly prefer tight fills (small post_residual).
    let flex = 1.0 - progress;
    let coupling = pr * (0.5 + 1.5 * progress * progress);
    score += 0.8 * coupling * flex;
    score -= 0.6 * pr * progress * progress;

    // Reward tight fits via a smooth saturating term on fill ratio.
    let fill = (bin_residual as f64 - pr) / cap;
    score -= 18.0 * fill * fill * (2.0 - fill);

    // Penalize very small dead space that is likely unusable (smooth bump around small residuals).
    let dead = pr / cap;
    score += 12.0 * dead * (1.0 - dead) * (1.0 - dead) * 4.0;

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty proportional to leftover.
        score += 4.0 * dead * progress;
    }

    // New-bin candidate: neutral-ish baseline, slightly worse late in stream
    // so we prefer filling existing bins unless they are poor fits.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.2 * progress) + 5.0 * (1.0 - progress);
    }

    // Mild penalty for bins far below mean residual (keeps bin residuals balanced).
    score += 0.15 * (mean_residual - pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable" residue
    // classes (i.e., still able to host typical small items) get rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional fill of the bin: reward tight packing (high fill ratio).
    let fill = 1.0 - pr / cap;
    score -= 30.0 * fill * fill;

    // Modulo-class logic on post_residual: leftovers that are multiples of common
    // small sizes (or near-multiples) are more likely to be filled later.
    let post = post_residual as u32;
    let mut harmonic_bonus = 0.0;
    if post > 0 {
        for m in [10u32, 20, 25, 50].iter() {
            let r = post % m;
            let d = (*m as i32 - r as i32).abs().min(r as i32);
            harmonic_bonus += (d as f64) / *m as f64; // 0 when exact multiple
        }
        score += 6.0 * harmonic_bonus / 4.0;
    }

    // Dead-space penalty: leftover too small for the minimum plausible item.
    if post > 0 && post < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 40.0;
        } else if next_item_size < post {
            score -= 8.0 * (next_item_size as f64 / post as f64);
        } else {
            score += 10.0; // next item won't fit here; this bin risks becoming dead space
        }
        // Harmonic class of next item: big items prefer roomy bins
        if next_item_size > 60 && post < next_item_size {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when open bins
    // are mostly full or numerous; otherwise penalize slightly to prefer reuse.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - mean_residual / cap;
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing fits, must open
        } else {
            score += 12.0 + 20.0 * (1.0 - avg_fill) - 10.0 * progress;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 * (1.0 + (12 - post_residual) as f64 / 12.0);
    }
    // Perfect / near-perfect fits strongly rewarded
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual >= 13 {
        // usable residual: mild reward proportional to its usefulness
        score -= 0.15 * post_residual as f64;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 12 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    }
    // Penalize leaving a gap that the next item cannot use at all
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 13 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: discourage spreading across many bins
    score += 0.6 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a new bin unless it's genuinely needed
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * open_bins_count as f64;
        // but if no other bin fits well (this is the only fitting option), soften
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Tight fit relative to item size: reward high fill ratio
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (item exactly fills the bin).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the leftover space can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chaining: next item exactly fills the remainder.
            if next_item_size == post_residual {
                score -= 800.0;
            } else {
                // Reward proportional to how snugly the next item fits.
                let slack = (post_residual - next_item_size) as f64;
                score -= 300.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Penalize leftovers too small for the next item (dead space risk),
            // scaled by how close the residual is to being useless.
            let deadness = (next_item_size - post_residual) as f64 / next_item_size as f64;
            score += 150.0 * deadness;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
    score -= 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make it unattractive unless all open bins are nearly full.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        score += 400.0 * avg_fill;
    }

    // Late-stream pressure: tighten packing as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small to likely fit future items.
    if post_residual < 10 {
        score += 12.0;
    } else if post_residual > 80 {
        score += 3.0; // near-empty bin wasted on a small item
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        // Post residual blocks the next item: penalize proportionally.
        score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    }

    // Perfect-fill chase: reward when item nearly empties the bin.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Global state: many open bins with high mean residual -> favor filling
    // existing bins rather than spreading.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 4.0;
    }
    // Few open bins and large mean residual: opening a new bin is less costly.
    if open_bins_count <= 2 && (bin_residual as f64 - mean_residual).abs() < 1.0 && bin_residual == bin_capacity {
        score -= 2.0;
    }

    // New-bin candidate: make it attractive only when the item is large and
    // existing bins would be left with awkward residuals.
    if bin_residual == bin_capacity {
        let awkward = fitting_bins_count > 0
            && open_bins_count > 0
            && open_bins_count.iter().count() == open_bins_count; // placeholder no-op
        let _ = awkward;
        // penalize default new bin mildly; lookahead can overcome it
        score += 5.0 - 4.0 * (item_size as f64 / bin_capacity as f64);
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 3.0; // big next item: fresh bin useful
        }
    }

    // Prefer bins whose residual is "just above" the item (snug fit).
    let snug = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * snug * snug;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress and fill ratio (smooth, in [0,1])
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = (item_size as f64) / (bin_capacity as f64);
    let post_norm = (post_residual as f64) / (bin_capacity as f64);

    // Non-linear polynomial coupling: post_residual penalized more heavily
    // as the stream progresses and as the item is large (good fits matter late).
    let coupling = (1.0 - post_norm).powi(3) * (0.5 + 0.5 * progress) * (0.5 + fill);
    score -= 40.0 * coupling;

    // Smoothly reward tight fits: quadratic in item size, damped by progress
    let tightness = (fill * fill) * (1.0 - post_norm * post_norm);
    score -= 15.0 * tightness * (0.3 + 0.7 * progress);

    // Dead-space penalty: small post_residual that next item cannot use
    // (smooth interaction with lookahead size)
    if next_item_size > 0 {
        let gap = post_residual as f64;
        let next = next_item_size as f64;
        if gap < next {
            let waste = (next - gap) / (bin_capacity as f64);
            score += 25.0 * waste * (1.0 - progress);
        } else {
            // smooth reward when next item fits the leftover
            let usable = (gap - next) / (bin_capacity as f64);
            score -= 8.0 * (1.0 - usable) * (1.0 - usable) * (1.0 - progress);
        }
    }

    // Last-chance bin: smooth urgency term (few fitting bins => favor this bin)
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / (1.0 + (fitting_bins_count - 1) as f64);
        score -= 12.0 * scarcity * (0.4 + 0.6 * progress);
    }

    // Mild diversity penalty relative to mean residual (avoid unbalanced bins)
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 5.0 * dev * dev;

    // New-bin candidate: penalize slightly so it's chosen only when open bins
    // score poorly (smooth pressure growing with open bin count)
    if bin_residual == bin_capacity {
        score += 6.0 + 0.5 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // coarse buckets via integer division thresholds (capacity fractions).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits strongly (post_residual small relative to capacity).
    score += (pr / cap).powf(2.0) * 60.0;

    // Harmonic class via integer division on post_residual (classes of 10 units).
    let class = post_residual / 10;
    match class {
        0 => score -= 40.0,          // near-perfect fit: dead space < 10
        1 => score -= 25.0,          // excellent: leaves a 10-19 slot
        2 => score -= 12.0,          // good: leaves a 20-29 slot
        3 => score -= 5.0,           // moderate: leaves a 30-39 slot
        4 => score += 3.0,           // awkward mid-range leftover
        5 => score += 8.0,           // 50-59 leftover: hard to fill
        6 => score += 14.0,          // 60-69 leftover
        7 => score += 20.0,          // 70-79 leftover
        _ => score += 25.0,          // 80+: nearly empty bin, wasteful placement
    }

    // Coupling with next item: reward if the next item can exactly fill
    // or nearly fill the post-residual (harmonic pairing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() <= 5.0 {
            score -= 35.0; // next item completes this bin perfectly
        } else if nxt <= pr {
            score -= (pr - nxt).min(30.0) * 0.8; // next item fits with slack
        } else {
            score += 10.0; // next item won't fit here
        }
        // Modulo harmony: next item shares residue class with post_residual
        if next_item_size % 10 == post_residual % 10 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening a new bin when existing bins already have plenty of room.
    if bin_residual == bin_capacity {
        // New-bin candidate: its raw score is post_residual == capacity.
        // Only attractive if the stream is early or mean residual is small.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress); // early stream: new bins cheaper
        score -= (mean_residual / cap) * 20.0; // if open bins are full-ish, new bin ok
    } else {
        // Existing bin: reward when it is tighter than the average open bin.
        score -= (mean_residual - pr) * 0.5;
    }

    // Mild penalty for bin proliferation late in the stream.
    score += (open_bins_count as f64).ln() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any item
    // (min size 1, but small gaps < ~10 are practically unusable) are penalized hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 10.0;
    } else {
        // Reward leaving a gap that many item sizes can still use
        score -= 8.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling: dead space hurts more when the bin pool is already large
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded / mean residual is small
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64);
        score = 120.0 - pressure * 10.0;
        // If the next item could combine with current one in a fresh bin, mild bonus
        if next_item_size > 0 && next_item_size + item_size >= bin_capacity as u32 {
            score -= 15.0;
        }
    }

    // Lookahead: if the post residual exactly accommodates the next item, reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 10.0;
    }

    // Slight late-stream conservatism: prefer filling existing bins as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact or near-exact fits (low post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins where the next item fits the post-residual exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_waste = (post_residual - next_item_size) as f64;
        score -= 50.0 - 0.5 * lookahead_waste;
        if post_residual == next_item_size {
            score -= 500.0; // perfect 2-item chain fill
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize relative to how much would be stranded.
        let stranded = next_item_size as f64 - post_residual as f64;
        score += 0.3 * stranded;
    }

    // Compare post_residual against mean residual: avoid creating outlier dead space.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.2 * dev;
    } else {
        score += 0.1 * dev; // slightly reward tighter-than-average residuals
    }

    // Last-chance bin before opening a new bin: strong incentive to use it.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize opening new bins when existing bins can fit (new-bin candidate detection).
    if bin_residual == bin_capacity {
        score += 40.0 + 5.0 * open_bins_count as f64;
        // Allow a new bin only if lookahead suggests it will pair well with the next item.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 45.0;
        }
    }

    // Slight preference for denser bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize large post_residual quadratically
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 {
            score -= 20.0; // perfect two-item packing chain
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize dead space proportionally to how much is wasted
        score += 0.15 * (post_residual as f64) * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: only bin that can fit the item — avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Global state: many open bins with low mean residual -> prefer filling existing bins
    let density = mean_residual / bin_capacity as f64;
    score += 4.0 * density * (open_bins_count as f64).ln().max(0.0);

    // Time horizon: early in the stream, be more willing to open new bins (explore);
    // late in the stream, strongly prefer existing bins (exploit)
    let exploration = 10.0 * (1.0 - t) * (1.0 - t);
    score -= exploration;

    // New empty bin candidate: penalize unless it enables a much better packing
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * t; // opening new bins gets costlier as stream progresses
        // But if the item is large and no open bin fits well, allow it
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 1 {
            score -= 14.0;
        }
        // If next item is large too, a fresh bin can host the pair
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && item_size + next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild preference for bins whose residual is closest above the item (best-fit flavor)
    score += 0.05 * ((bin_residual - item_size) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post residual, but non-linearly (dead-space penalty grows quadratically).
    let mut score = norm_pr * (1.0 + 1.7 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on tolerate larger residuals (future items can fill them),
    // later on demand tighter fits.
    let progress_weight = 0.9 + 2.2 * progress * progress;
    score *= progress_weight;

    // Reward near-perfect fits smoothly (bell-shaped around zero residual).
    score -= 1.3 * (-norm_pr * norm_pr * 8.0).exp();

    // Penalize bins far from the mean residual (fragmentation avoidance).
    let dev = (pr - mean_residual) / cap;
    score += 0.45 * dev * dev;

    // Lookahead: bonus if next item fits the post residual, smooth coupling with progress.
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as i32 as f64;
        let gap = ((next_item_size as f64 - pr) / cap).abs();
        score -= 0.8 * fits_next * (1.0 - progress);
        score += 0.3 * gap * (1.0 + progress);
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 1.5 * (1.0 - norm_item);
    }

    // Slight preference for consolidating into fewer bins when many are open.
    score -= 0.02 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // New-bin candidate: make it attractive only when the item is large relative
    // to typical residuals; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count == 0) as i32 as f64;
        score += 0.6 * (1.0 - scarcity) * (1.0 + 2.0 * progress * (1.0 - norm_item));
        score -= 0.7 * norm_item * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let mut harmonic_bonus = 0.0;
        // post residual exactly divisible by common size classes -> very reusable
        for &d in &[10u32, 20, 25, 50] {
            if pr % d == 0 {
                harmonic_bonus += 6.0;
            }
        }
        // near-harmonic: within 2 of a multiple of 10/20
        let m10 = ((pr as f64 / 10.0).round() * 10.0) as u32;
        if m10 != pr && (m10.abs_diff(pr) <= 2) {
            harmonic_bonus += 2.5;
        }
        score -= harmonic_bonus;

        // Dead-space penalty: leftover too small for the smallest plausible item
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 8.0;
        }

        // Integer-division threshold: leftover in [20,30) or [45,55) are prime slots
        let bucket = pr / 15; // coarse harmonic bucket
        if bucket == 1 || bucket == 3 {
            score -= 3.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does post_residual accommodate next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0 + 0.1 * (next_item_size as f64);
            // harmonic: post_residual % next_item_size small => chain fit
            let r = post_residual % next_item_size;
            if r <= 5 {
                score -= 3.0;
            }
        } else {
            // leftover can't host next item: penalize proportionally
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless stream is early
    // or current bin would leave huge waste anyway.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_avoided = (bin_residual - item_size) as f64;
        score += 30.0 - 20.0 * progress;
        // opening a new bin is fine if the item is large (keeps big slot fresh)
        if item_size >= 50 {
            score -= 12.0;
        }
        // penalize more when many bins already open and mean residual is low
        score += 0.3 * open_bins_count as f64 * (1.0 - mean_residual / cap);
        let _ = waste_avoided;
    }

    // Mild tightness reward: filling a bin well
    score -= 0.05 * (item_size as f64);

    // Spread against mean residual: prefer bins below mean (tighter bins)
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10 units)
    // much more strongly than larger residuals, since tiny gaps are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward near-perfect fits (post_residual == 0) strongly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward residuals that could still fit a plausible future item.
    if post_residual >= 10 {
        score -= 5.0;
    }

    // Open-bins pressure: penalize spreading into many open bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make empty bins less attractive unless the current
    // bin would leave a bad dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual < 10 || post_residual > 50 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Penalize if next item would not fit and residual is small-ish.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 20 {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins close to the mean residual (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Stream progression: later in stream, be slightly more frugal with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits in the post residual -> moderate reward scaled by tightness
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does not fit: penalize leaving dead space that blocks the lookahead
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Penalize large dead space relative to mean residual (wasted capacity)
    let dead = post_residual as f64;
    if dead > mean_residual {
        score += 0.5 * (dead - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - dead);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Slight preference to fill existing bins rather than open new ones
    if bin_residual != bin_capacity {
        score -= 10.0;
    } else {
        // New-bin candidate: penalize unless residual is tiny (poor fits elsewhere)
        score += 5.0 + 0.1 * open_bins_count as f64;
    }

    // Early in stream: be more conservative, prefer tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual already does this).
    // Reward near-perfect fits extra strongly.
    let cap = bin_capacity as f64;
    let fill_ratio = 1.0 - (post_residual as f64) / cap;
    if post_residual == 0 {
        score -= 60.0; // perfect closure is always best
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect fit
    } else if post_residual < 25 {
        score -= 10.0 * fill_ratio;
    }

    // Penalize dead space: residual too small for the smallest plausible item (1..100 stream)
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // tiny unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 12.0 * (1.0 - chain_fit);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; mild penalty if this bin becomes a dead bin
        score += 4.0;
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when placement elsewhere is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with how many bins are already open
        score += 35.0 + 2.0 * open_bins_count as f64;
        // But late in the stream, opening fresh bins is safer
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * progress;
        // If no open bin can fit at all (fitting_bins_count counts only open ones + this?),
        // strongly encourage opening: item_size > all residuals means this is forced anyway.
        if item_size as f64 > mean_residual {
            score -= 40.0;
        }
        // Perfect packing potential: opening a bin when item is large wastes less
        if item_size >= 50 {
            score -= 10.0;
        }
    }

    // Global state coupling: if mean residual is high, prefer spreading load into
    // bins with above-average residual (balance utilization across bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Prefer bins that are already fairly full when many bins are open (consolidation).
    score -= 0.05 * fill_ratio * open_bins_count as f64;

    // Time horizon: early in stream, keep residuals flexible (penalize very tight
    // non-closing fits slightly); late in stream, squeeze hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 30 && post_residual < 60 {
        score += 6.0 * (1.0 - progress);
        score -= 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = pr;

    // Reward tight fits: quadratic coupling of post_residual with item fraction
    let fit_frac = item_size as f64 / cap;
    score -= 12.0 * fit_frac * (1.0 - fit_frac) * (1.0 - fit_frac) * cap * 0.5;

    // Smooth polynomial coupling: penalize large post_residual as stream progresses
    let norm_pr = pr / cap;
    score += (0.5 + 2.0 * progress) * norm_pr * norm_pr * cap * 0.3;

    // Penalize dead space below smallest plausible item, smoothly
    let dead = (20.0 - pr).max(0.0) / 20.0;
    score += dead * dead * (30.0 + 40.0 * progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 45.0 + 25.0 * progress;
    }

    // Lookahead: reward residual that can fit next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 6.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 5.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
    }

    // Prefer bins with below-mean residual (consolidate space), smooth term
    let dev = (mean_residual - bin_residual as f64) / cap;
    score -= 10.0 * dev * dev * dev.signum();

    // Mild penalty for opening new bins when good fits exist, easing late stream
    if is_new_bin {
        score += 15.0 + 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (integer division thresholds).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful get punished.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic classes: post_residual falling in [0,C/4), [C/4,C/2), [C/2,3C/4), [C/4*3,C)
    let class = (post_residual * 4) / bin_capacity; // 0..3 integer class
    match class {
        0 => score -= 8.0,                 // nearly full bin: good
        1 => score += 6.0,                 // quarter-ish leftover: mediocre
        2 => score += 2.0,                 // half-ish leftover
        _ => score += 12.0,                // mostly empty bin: wasteful placement
    }

    // Modulo arithmetic on residual: residual mod 10 measures granularity waste.
    let mod10 = post_residual % 10;
    score += mod10 as f64 * 0.7;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // penalize by leftover after the lookahead item, scaled
            score += slack * 0.35;
            // harmonic class of slack
            if (post_residual - next_item_size) * 4 / bin_capacity == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this bin's leftover; mild penalty
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when the item is
    // large relative to residual or residuals across bins are already small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is attractive when existing bins are tightly packed
        // (low mean residual) or the item is big.
        let tightness = (cap - mean_residual) / cap;
        score -= 15.0 * tightness + 10.0 * progress;
        if item_size >= 50 {
            score -= 8.0;
        }
    } else {
        // Penalize using an open bin when mean residual is large (bins scattered)
        score += (mean_residual / cap).max(0.0) * 4.0;
    }

    // Mild penalty for proliferating open bins.
    score += open_bins_count as f64 * 0.3;

    // Progress-scaled tightness bonus: late in the stream, favor filling bins fully.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (item_size as f64 / cap) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1 unit, but practically small gaps) are heavily penalized.
    let dead_threshold = 12.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 45.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < item_size {
        // Gap too small for any future item of at least this size class:
        // mild extra penalty scaled by tightness.
        score += 8.0 * (1.0 - post_residual as f64 / item_size as f64);
    }

    // Open-bins pressure: penalize adding load to bins when many are open,
    // encouraging consolidation; but relax near end of stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.6 * (1.0 - 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // mean residual across open bins is small (poor fits everywhere).
    if bin_residual == bin_capacity {
        score -= 12.0 * mean_residual / bin_capacity as f64;
        score += 25.0 * (1.0 - mean_residual / bin_capacity as f64);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the gap: penalize proportionally.
        score += 5.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit (low post residual).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    }

    // 2-step lookahead: if the next item exactly matches the post residual,
    // this placement is highly desirable.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs();
        if lookahead_gap == 0 {
            score -= 300.0;
        } else if next_item_size as u32 <= post_residual {
            // next item still fits in this bin afterwards: reward proportionally
            score -= 40.0 + 0.5 * (post_residual as f64 - next_item_size as f64);
        } else {
            // next item would NOT fit here: penalize leftover dead space
            score += 0.6 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize creating tiny unusable slivers relative to the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when the item is large relative to capacity or all
    // fits are poor.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        if large_item > 0.6 {
            score -= 70.0;
        } else {
            score += 30.0;
        }
        // prefer opening new bins early when few bins are open and mean residual is low
        if open_bins_count as f64 <= mean_residual / 10.0 {
            score -= 10.0;
        }
    }

    // Mild preference for bins tighter than the mean residual (best-fit bias).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for older bins to encourage closing them out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose leftover is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit gets an extra discount.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: reward bins where the next item also fits in the leftover.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
        score -= 6.0 + 4.0 * chain_quality;
    }
    // Penalize leftovers that are too small for the next item (likely dead space).
    else if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Penalize spreading across too many open bins; encourage consolidation
    // when open bins are mostly full (low mean residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 0.4;
    score -= mean_residual * 0.05 * progress;

    // New-bin candidate handling: opening a fresh bin wastes capacity.
    // Only attractive when the item is large (would leave big unusable
    // fragments in existing bins) or when no open bin is a good fit.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        let poor_alternatives = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let waste_penalty = 25.0 * (1.0 - large_item) + 15.0 * (1.0 - poor_alternatives);
        score += waste_penalty;
        // Late in the stream, prefer closing out existing bins.
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize wasted residual, modulated smoothly by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress);

    // Non-linear polynomial coupling: residual^2 scaled by progress.
    score += 0.35 * pr_norm * pr_norm * cap * (0.3 + 0.7 * progress);

    // Reward tight fits (low post residual) more strongly later in stream.
    score -= 12.0 * (1.0 - pr_norm).powi(3) * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly favor if this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: bonus if next item fits into post residual (smooth coupling).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (n / cap)) * (0.5 + 0.5 * progress);
        } else {
            score += 5.0 * (n - pr) / cap * (1.0 - progress);
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.25 * (mean_residual - pr) * (0.5 + 0.5 * progress);

    // Mild penalty when many bins open: encourage consolidation.
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: keep it attractive only when residuals are poor.
    if bin_residual == bin_capacity {
        score = pr * (1.0 + progress) + 6.0 * (1.0 - progress)
            + 10.0 * ((mean_residual / cap).powi(2));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual falls into
    // "small residue classes" (unusable dead space) are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual <= 10 -> perfect fit, strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Class B: post_residual in (10, 20] -> still useful for small items.
    if post_residual > 10 && post_residual <= 20 {
        score -= 8.0;
    }

    // Class C: dead-zone check via integer division thresholds.
    // If post_residual is in a band where the next item (lookahead) cannot fit,
    // penalize heavily (creating unusable space).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // reward leaving room exactly for the lookahead item
            score -= 6.0;
            // harmonic bonus: post_residual % next_item_size small => tight packing
            let m = (post_residual % next_item_size.max(1)) as f64;
            score -= 4.0 * (1.0 - m / next_item_size.max(1) as f64);
        }
    }

    // Modulo arithmetic on capacity fractions: bins whose residual is a
    // "nice" fraction of capacity (e.g. multiples of 25) are preferred sinks.
    let quarter = bin_capacity / 4;
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only open a new bin if current bins are crowded
    // (mean residual low) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = mean_residual / cap;
        // penalize new bin when open bins still have room; reward when crowded
        score += 30.0 * crowd;
        score -= 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer fuller bins overall (tightness coupling).
    score -= 10.0 * (1.0 - pr / cap);

    // Slight preference for bins already below mean residual (balancing).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftover gaps are hard to fill later.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0 - 2.0 * post_residual as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual >= 20 && post_residual < 40 {
        score += 8.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating
    // rather than spreading; with few open bins, opening new is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are open (pressure),
        // but allow it when existing fits would leave terrible dead space.
        score += 15.0 + pressure;
        if post_residual == bin_capacity as f64 as u32 && item_size > 70 {
            score -= 10.0; // big item into fresh bin is fine
        }
    } else {
        score -= pressure * 0.15;
    }

    // Lookahead: if next item fits the post-residual exactly, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item can't use this gap -> gap likely dead
        score += 12.0;
    }

    // Prefer bins below mean residual (balancing), slight effect.
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: penalize leftover space (tight fits win).
    let mut score = post * (1.0 + 0.02 * (post / cap));

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Dead-space penalty: leftover that no plausible item can use.
    // Items range 1..=100, so residual < 1 is impossible; but residual that
    // is smaller than typical small items is waste. Penalize tiny residuals
    // relative to capacity more than large usable ones.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post).abs() < 0.5 {
            score -= 300.0; // chain fit
        } else if nxt <= post {
            // next item can still fit here: mildly reward keeping room
            score -= 10.0 + 0.1 * (post - nxt);
        } else {
            // next item won't fit here: penalize blocking
            score += 5.0 + 0.15 * (nxt - post);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - post / cap);
    }

    // New-bin candidate: residual == capacity means empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin should only win when the item is large and would
        // otherwise leave bad residue, or when no open bin fits well.
        let waste_elsewhere = if fitting_bins_count == 0 { 0.0 } else { 0.0 };
        let _ = waste_elsewhere;
        // Base cost of a new bin: proportionally worse late in the stream.
        let mut new_bin_cost = 60.0 + 40.0 * progress;
        // Large items fit better in fresh bins.
        new_bin_cost -= 0.5 * item;
        // If many open bins already, spreading is fine.
        new_bin_cost -= (open_bins_count as f64).min(10.0) * 2.0;
        // If mean residual is high, open bins are roomy; prefer them.
        new_bin_cost += 0.3 * (mean_residual - item).max(0.0);
        score += new_bin_cost;
    }

    // Global state coupling: prefer bins whose residual is below the mean
    // (fill the tightest bins first), scaled by stream progress.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.1 * dev * (0.5 + progress);
    }

    // Slight preference to consolidate into fewer bins.
    score += 0.5 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;

    // Base: post residual, with non-linear shrinkage of very small residuals (dead space).
    let mut score = pr
        - 30.0 * (1.0 - pr / cap).powi(3)              // reward near-full fills
        - 8.0 * (pr / cap) * (1.0 - pr / cap) * 4.0;   // smooth mid-residual shaping

    // Stream-progress coupling: early on, tolerate leftover space; late, penalize it harder.
    let prog_term = (pr / cap) * (0.5 + progress) * (1.0 + fit_ratio);
    score += 15.0 * prog_term;

    // Smooth lookahead interaction: penalize residuals that neither fit nor exclude next item.
    if next_item_size > 0 {
        let diff = pr - next_ratio * cap;
        score += 5.0 * (diff / cap).powi(2) * (1.0 - progress);
        // reward residuals that exactly anticipate the next item
        score -= 6.0 * (-(diff / cap).powi(2) * 8.0).exp();
    }

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mean-residual coupling: prefer bins deviating from the mean (consolidation).
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap).powi(2);

    // New-bin candidate: penalize opening a bin unless current residual is truly unusable.
    if bin_residual == bin_capacity {
        let waste = (pr / cap).powi(2);
        score += 40.0 * (1.0 - 0.5 * progress) + 20.0 * waste;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Crowding pressure: with many open bins, favor filling existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect-fit reward: post_residual exactly divisible into harmonic classes (0, 25, 50, 75, 100)
    if post_residual == 0 {
        score -= 1000.0; // perfect fill, ideal
    } else {
        let harmonic = [
            bin_capacity / 4,
            bin_capacity / 2,
            (3 * bin_capacity) / 4,
            bin_capacity,
        ];
        let mut best_diff = u32::MAX;
        for h in harmonic.iter() {
            let d = if *h >= post_residual { *h - post_residual } else { post_residual - *h };
            if d < best_diff { best_diff = d; }
        }
        // Reward proximity to a harmonic class (dead space aligned to divisible sizes)
        score -= 2.0 * (cap - best_diff as f64) / cap;
    }

    // Penalize dead space that cannot be used by next item (modulo logic)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // next item cannot fit here; dead space penalty scaled by waste size
            score += 0.5 * post as f64;
        } else {
            // next item fits: reward, especially if next fills to another harmonic class
            let next_post = post_residual - next_item_size;
            if next_post == 0 {
                score -= 400.0;
            } else if next_post % (bin_capacity / 4) == 0 {
                score -= 100.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Modulo class of item_size relative to quarter-capacity: big items on big residuals
    let quarter = bin_capacity / 4;
    let item_class = item_size / quarter.max(1);
    let residual_class = bin_residual / quarter.max(1);
    if item_class == residual_class {
        score -= 30.0; // matching harmonic tiers
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty so it's chosen only when fits are bad
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative
        }
    }

    // Mild global pressure: as stream progresses, tighten packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Prefer bins with residuals below mean (tighter bins first)
    score -= 0.1 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps harder (dead space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Fit that still accommodates the lookahead item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from many open bins: discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * open_bins_count as f64;
    } else {
        score -= 5.0 * open_bins_count as f64;
    }

    // Prefer filling bins with larger residuals when mean residual is high.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Early stream: be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight residual against mean residual.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Tightness reward: superlinear penalty for large post_residual.
    score += 40.0 * norm_post * norm_post;

    // Aggressive 2-step lookahead: strongly reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post && nxt > 0.0 {
            // Perfect chain fit: next item exactly fills the bin.
            let gap = (post - nxt) / cap;
            // Subtract heavily; perfect match (gap ~ 0) gets the biggest bonus.
            score -= 90.0 * (1.0 - gap);
            score -= 60.0 * (1.0 - gap) * (1.0 - gap);
        } else if post > 0.0 && nxt > post {
            // Next item does NOT fit: this bin becomes dead space unless post is tiny.
            // Penalize proportionally to how stranded the residual is.
            let stranded = post / cap;
            score += 70.0 * stranded * stranded;
            // Extra penalty if residual is in the awkward middle zone (unusable for 1..100 items).
            if post < 10.0 && post > 0.0 {
                score += 25.0; // tiny slivers are near-useless
            }
        }
        // Moderate reward if next item would fit better here than the average open bin.
        if nxt <= post && mean_residual > 0.0 && post >= mean_residual {
            score += 10.0; // mild nudge: this bin is above-average roomy for the chain
        }
    } else {
        // Last item: just minimize residual as tightly as possible.
        score += 20.0 * norm_post;
    }

    // Last-chance bin: if this is the only bin that fits, strongly discourage opening a new bin
    // unless the fit is truly awful (huge post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let badness = norm_post;
        if badness < 0.5 {
            score -= 50.0 * (1.0 - 2.0 * badness);
        }
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity - item_size.
    // Make empty bins attractive only when existing bins would leave bad residuals.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; competing bins with worse fits will beat it via bonuses above.
        score = post + 15.0;
        // Late in the stream, slightly prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If many bins are open, discourage proliferation.
        score += 2.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: placing into a bin far below mean residual keeps spread balanced.
    if mean_residual > 0.0 && bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 8.0 * dev; // prefer bins with residual near/below mean (tighter bins)
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    } else if post_residual < 20 {
        score += 5.0;
    }

    // Lookahead: if the next item fits in the post residual, this is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.2 * next_item_size as f64;
    }
    // If next item would exactly fill the bin, huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // Penalize if next item is large and would NOT fit here (we'd strand space).
    if next_item_size > post_residual && next_item_size > 50 && post_residual > 0 {
        score += 0.15 * (next_item_size as f64 - post_residual as f64);
    }

    // Last chance: if this is the only fitting bin, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // fit into an existing bin is poor (large post residual) or when we have
    // very few open bins late in the stream.
    if bin_residual == bin_capacity {
        // Baseline modest penalty so decent existing fits win.
        score += 12.0;
        // But if the best existing fit would waste a lot, new bin is attractive.
        let waste = post_residual as f64; // = capacity - item for new-bin call
        if waste > 45.0 {
            score -= (waste - 45.0) * 0.8;
        }
        // Late in the stream, consolidate: discourage opening bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If many bins are already open, slightly discourage more.
        score += 0.5 * open_bins_count as f64;
    }

    // Prefer bins tighter than average (pack dense bins first).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.1 * diff;
    }

    // Mild global pressure: with many open bins, favor filling existing ones.
    score -= 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = post * (1.0 + 0.8 * progress + 0.6 * p2 + 0.4 * p3);

    let mut score = coupling;

    // Reward tight fits with a smooth saturating term on fill fraction.
    score -= 30.0 * fill * fill * fill;

    // Penalize dead space relative to mean residual (smooth quadratic).
    let dead = (post - mean_residual).max(0.0);
    score += 0.15 * dead * dead / cap;

    // Lookahead: reward bins whose post residual fits the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (post - nx).abs();
        score -= 12.0 * (1.0 - gap / cap).max(0.0);
    }

    // Last-chance bin: smooth urgency bonus growing with progress.
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    }

    // Slight preference for reusing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins, smoothed by progress.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction slot it falls into
    let pr = post_residual;
    let frac = pr as f64 / cap; // fraction of capacity wasted if bin ends here

    // Class 0: near-perfect fit (residual <= 10) -> strong reward
    if pr <= 10 {
        score -= 60.0;
    } else if pr <= 20 {
        score -= 25.0;
    } else if pr <= 30 {
        score -= 8.0;
    }

    // Modulo-10 harmonic band of post residual: dead space in [1..10] slots
    let band = pr % 10;
    score -= (10 - band) as f64 * 0.8; // reward residuals close to the next decade line

    // Integer division thresholds: residual above half capacity is reusable
    if pr > bin_capacity / 2 {
        score -= 12.0;
    } else if pr > bin_capacity / 3 {
        score -= 4.0;
    } else {
        score += 4.0; // small residuals (< C/3) are hard to reuse
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match: next item lands in a compatible class
            let diff = pr - next_item_size;
            if diff <= 5 {
                score -= 18.0;
            } else if diff <= 15 {
                score -= 8.0;
            } else {
                score -= 3.0;
            }
        } else {
            // next item won't fit here: penalize leaving this residual pattern
            score += (next_item_size - pr) as f64 * 0.25;
        }
    } else {
        // last item: only tightness matters
        score -= (cap - frac * cap) * 0.0;
        score -= (100.0 - pr as f64) * 0.0;
        score += pr as f64 * 0.5; // prefer filling as much as possible at the end
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening a new bin, scaled by how many bins already fit the item
        // and by how much residual capacity is idling in open bins
        let idle = mean_residual.max(0.0);
        score += 45.0 + 6.0 * (fitting_bins_count as f64) + idle * 0.35;
        // early in the stream, opening bins is cheaper (build diversity)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
        // large items relative to residual: new bin fine
        if item_size as f64 > cap * 0.7 {
            score -= 20.0;
        }
    }

    // Mild penalty for proliferating open bins when residuals are fragmented
    if open_bins_count > 4 && (mean_residual > 40.0) {
        score += 2.0;
    }

    // Small tie-breaker: tighter fit (smaller post_residual relative to item) preferred
    score += (post_residual as f64 / (item_size.max(1) as f64)) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A post_residual below the minimum plausible item size (1..100 stream,
    // conservatively < 20) is likely dead space.
    if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 8.0;
    } else if post_residual == 0 {
        score -= 50.0; // perfect fit reward
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 15.0;

    // Open-bin pressure: when many bins are open, prefer packing into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 3.0);
    score += pressure * 2.0;

    // New-bin candidate handling: an empty bin gets a moderate baseline so
    // it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 60.0 + pressure;
    }

    // Last-chance bin: strongly favor using the only bin that can fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward it;
    // if the post-residual is too small for the next item, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Coupling with mean residual: prefer bins whose residual is below
    // average (tighter bins) to consolidate space.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual closely
    // matches the next item size (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 30.0 * (1.0 - gap / (bin_capacity as f64));
        if gap < 3.0 {
            score -= 25.0; // near-perfect chain bonus
        }
    } else if next_item_size > post_residual {
        // Post residual cannot host the next item: penalize proportional to waste.
        score += 0.15 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
    }

    // Prefer tight fits overall.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Relative-to-mean adjustment: bins tighter than average are preferred.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // New-bin candidate: keep it neutral-to-slightly-high unless the item is
    // large relative to remaining space in typical open bins.
    if bin_residual == bin_capacity {
        score += 5.0;
        if (item_size as f64) > mean_residual {
            score -= 8.0;
        }
    }

    // Slight stream-aware bias: later in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Lookahead: if the next item fits the post residual, reward strongly.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 20.0;
        } else if (bin_residual as u32) >= next_item_size {
            score -= 4.0;
        } else {
            score += 8.0;
        }
        // Perfect chain: current + next exactly fill the bin.
        if (item_size + next_item_size) as u32 == bin_residual {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when current item leaves huge dead space in every open bin.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 10.0;
        // If item nearly fills a fresh bin, opening is good.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 35.0;
        }
        // Late in the stream, prefer packing into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Many open bins with slack: discourage another bin.
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 20.0;
        }
    }

    // Global state coupling: high mean residual means slack exists elsewhere;
    // penalize wasting this bin's space if it's much tighter than average.
    if (bin_residual as f64) < mean_residual - 20.0 {
        score += 6.0;
    } else if (bin_residual as f64) > mean_residual + 20.0 {
        score -= 4.0;
    }

    // Mild penalty for proliferation of open bins.
    score += 0.3 * open_bins_count as f64;

    // Time horizon: as the stream ends, prefer minimal post residual aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Tight fits rewarded more as stream progresses (smooth polynomial coupling)
    let tight = 1.0 - norm_pr;
    score -= tight * tight * (40.0 + 60.0 * progress);
    // Penalize dead space: post_residual too small to fit typical future items
    let dead = (norm_pr * (1.0 - norm_pr)).sqrt();
    score += (1.0 - dead) * 30.0 * (1.0 - progress);
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }
    // Lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 15.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 10.0;
        }
    }
    // Prefer bins below mean residual slightly (balance)
    score += 0.05 * (pr - mean_residual);
    // New-bin candidate: neutral baseline, mildly discouraged unless residuals are tight
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress * (1.0 - norm_pr);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo small divisors: prefer residuals
    // that form "good" capacity fractions of C=100 (multiples of 10, 25, 50).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward post-residuals that are exact capacity fractions (harmonic classes)
    let frac = pr / cap;
    if frac == 0.5 { score -= 40.0; }
    else if frac == 0.25 { score -= 30.0; }
    else if frac == 0.75 { score -= 25.0; }
    else if post_residual % 10 == 0 && post_residual > 0 { score -= 12.0; }

    // Penalize tiny dead space (wasted capacity) more than large residual
    if post_residual < 10 && post_residual > 0 { score -= 15.0; } // near-perfect fill is great
    if post_residual == 0 { score -= 60.0; } // exact fit: best possible

    // Integer division thresholds: residuals in [1..9] are hard to reuse
    if post_residual >= 1 && post_residual <= 9 { score += 0.0; }
    if post_residual > 50 { score += (post_residual as f64 - 50.0) * 0.5; } // discourage leaving huge gaps

    // Lookahead coupling: if next item fits into post_residual, reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        // harmonic match: next item leaves another harmonic residual
        let pr2 = post_residual - next_item_size;
        if pr2 % 10 == 0 { score -= 10.0; }
        if pr2 == 0 { score -= 25.0; }
    } else if next_item_size > post_residual {
        score += 8.0; // next item won't fit here; mild penalty
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty that
    // grows with how well the item could have fit elsewhere, so we only
    // open new bins when existing fits are poor.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // same as post_residual, but add penalty
        score += 30.0 * (1.0 - (item_size as f64 / cap));
        if open_bins_count == 0 { score -= 100.0; } // must open a bin
        if fitting_bins_count == 0 { score -= 50.0; } // no open bin fits
        // if item is large, opening fresh bin is reasonable
        if item_size >= 60 { score -= 15.0; }
    }

    // Mild stream-phase modulation: early on, be more willing to open bins
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - phase) * 2.0 * (bin_residual == bin_capacity) as i32 as f64;

    // Prefer bins with below-average residual (tighter bins used first)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: penalize creating extra bins when many are open.
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * open_bins_count as f64;
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward leaving space for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff < 0.5 {
            score -= 60.0; // exact 2-step match: chain the next item perfectly
        } else if pr >= nxt {
            // next item fits, reward proportional to tightness of the pair
            let tight = 1.0 - (diff / bin_capacity as f64);
            score -= 25.0 * tight;
        } else {
            // post_residual too small for next item: dead space penalty
            score += 12.0 * (1.0 - pr / nxt.max(1.0));
        }

        // Combined pair fill: how full the bin becomes after both items
        let pair_fill = (item_size as f64 + nxt) / bin_capacity as f64;
        if pr >= nxt {
            score -= 20.0 * pair_fill * pair_fill;
        }
    } else {
        // Last item: just reward tightest fit
        score -= 30.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Prefer bins with residual below mean (tight bins), discourage hoarding space
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating very small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Mild preference for using existing bins over opening new ones as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress; // new-bin candidate penalty
    } else {
        score -= 5.0 * progress;
    }

    // Slight preference for larger residual bins when many bins open (balance load)
    score -= 0.05 * (bin_residual as f64) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize high post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that can never be filled by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 {
        // residual is reusable; scale value by how close it is to common item sizes
        score -= 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for leaving awkward residual
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Crowding pressure: many open bins with large mean residual -> prefer consolidating
    // into bins below mean residual (smaller residuals), discouraging bin proliferation.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 2 {
        let spread = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 10.0 * spread * (0.5 + 0.5 * t);
    }

    // Early in stream: be more willing to open new bins (exploration); late: consolidate.
    score += (1.0 - t) * 4.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bin fits are poor or none exist.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced early in the stream or when
        // the item is large relative to capacity (hard to place later).
        let large_item = item_size as f64 / bin_capacity as f64;
        let mut newbin_cost = 30.0 - 25.0 * (1.0 - t) - 20.0 * large_item;
        if fitting_bins_count == 0 {
            newbin_cost = 0.0;
        }
        // If next item is small, a fresh bin keeps flexibility.
        if next_item_size > 0 && (next_item_size as f64 / bin_capacity as f64) < 0.3 {
            newbin_cost -= 6.0 * (1.0 - t);
        }
        score += newbin_cost.max(0.0);
    }

    // Mild penalty for wasting a big residual bin on a small item late in stream.
    if t > 0.6 && (item_size as f64 / bin_residual as f64) < 0.35 && bin_residual != bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping.
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills less aggressively; later, demand tightness.
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * norm_pr * norm_pr * cap;

    // Penalize very small residuals (dead space) with cubic term.
    score += 0.35 * norm_pr * norm_pr * norm_pr * cap;

    // Reward near-perfect fits smoothly (Gaussian-like bump around zero residual).
    let fit_bonus = (-norm_pr * norm_pr * 40.0).exp();
    score -= 12.0 * fit_bonus * (1.0 + progress);

    // Lookahead: if next item fits into post_residual, reward this placement smoothly.
    if next_item_size > 0 {
        let slack = (pr - next_item_size as f64) / cap;
        if slack >= 0.0 {
            score -= 6.0 * (-slack * slack * 25.0).exp();
        } else {
            score += 2.0 * slack.abs();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier about residual quality.
        score += 3.0 * norm_pr;
    }

    // Mild preference to keep mean residual balanced across open bins.
    score += 0.05 * (pr - mean_residual).abs();

    // Slight nudge toward reusing existing bins as stream matures.
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers that are "nice"
    // (multiples of common item sizes / small residues) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut nice = 0.0f64;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 { nice += 3.0; }
        }
        if pr <= 10 { nice += 2.0; }          // tiny dead space is cheap
        if pr % 5 == 0 { nice += 1.0; }       // divisible by 5 is semi-nice
        score -= nice;
        // penalize awkward leftovers (prime-ish / odd classes)
        if pr % 2 == 1 { score += 2.0; }
        if pr % 7 == 0 { score -= 1.5; }
    }

    // Perfect fit is always best.
    if pr == 0 { score -= 100.0; }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement sets up a chain — reward it.
    if next_item_size > 0 {
        if next_item_size == pr { score -= 20.0; }
        else if next_item_size <= pr { score -= 4.0; }
        else { score += 3.0; } // next item won't fit here anyway
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or mean residual across open bins is already fragmented.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let penalty = 12.0 + 30.0 * frac
            - 8.0 * (mean_residual / bin_capacity as f64)
            + 5.0 * (open_bins_count as f64).ln().max(0.0);
        score += penalty;
        // big items near stream end: fresh bin can still absorb future items
        if frac > 0.6 { score -= 6.0; }
    }

    // Mild late-stream tightening: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
