        let gap = (next_item_size - post_residual) as f64;
        score += 10.0 * (gap / bin_capacity as f64);
    }

    // Penalize leaving small unusable dead space (hard to fill later)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
