    let tightness = 1.0 - (pr / cap).powf(2.0);
    let mut score = pr * (1.0 + 0.35 * tightness * tightness);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early stream -> tolerate moderate residuals; late stream -> punish dead space harder.
    let prog_term = progress * progress * (3.0 - 2.0 * progress); // smoothstep in [0,1]
    score += 18.0 * prog_term * (pr / cap).powf(3.0) * cap;

    // Reward near-perfect fills more strongly as stream advances.
    let fill = 1.0 - pr / cap;
    score -= 12.0 * fill * fill * fill * (0.4 + 0.6 * prog_term);

    // Last-chance bonus: smooth reward when few fitting bins exist.
    let last_chance = 1.0 / (fitting_bins_count as f64);
    score -= 8.0 * last_chance * (0.5 + 0.5 * prog_term);

    // Lookahead: smooth penalty if post-residual can't fit the next item but bin_residual could.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_now = (bin_residual as f64 >= nxt) as f64;
        let fits_after = (pr >= nxt) as f64;
        score += 6.0 * fits_now * (1.0 - fits_after) * (0.3 + 0.7 * prog_term) * (nxt / cap);
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    let mean_norm = mean_residual / cap;
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * mean_norm * mean_norm * prog_term;

    // New-bin candidate shaping: empty bin gets a smooth mid-range score so it wins
    // only when open bins would waste substantial space.
    if bin_residual == bin_capacity {
        score = cap * (0.55 - 0.25 * prog_term) + 5.0 * (it / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction slot does it land in?
    let quarter = bin_capacity / 4;
    let class = match post_residual {
        0 => 0,                      // perfect fit — golden
        r if r < quarter / 2 => 1,   // dead space class (unusable by mid items)
        r if r < quarter => 2,
        r if r < 2 * quarter => 3,
        r if r < 3 * quarter => 4,
        _ => 5,                      // large residual, very reusable
    };

    // Reward/penalize by harmonic class
    score += match class {
        0 => -60.0,
        1 => 25.0,   // tiny dead space is wasted capacity
        2 => 10.0,
        3 => 0.0,
        4 => -8.0,
        _ => -20.0,
    };

    // Modulo structure: residuals that are multiples of 10 are more reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chainable placement — reward, more if exact-ish
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + 10.0 * (1.0 - slack / cap);
        } else {
            // next item will not chain here; penalize proportionally to mismatch
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 * (gap / cap);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only sensible when
    // the item is large relative to the best reuse option, or when residuals
    // in open bins are in a bad harmonic class.
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score += 40.0;
        // large items deserve fresh bins more often
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
        // if many bins are open but residuals are poor, new bin is cheaper
        if mean_residual < cap * 0.25 && open_bins_count > 2 {
            score -= 20.0;
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // reusing an existing bin: reward proximity of fill level to capacity
        let fill = (bin_capacity - bin_residual) as f64 / cap;
        score -= 10.0 * fill;
        // many fitting bins: prefer the fullest (lowest residual naturally wins,
        // add small tie-breaker toward tight fits)
        if fitting_bins_count > 1 {
            score += 0.5 * (post_residual as f64 % 7.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 15 {
        score += 25.0;
    }

    // Reward tight fits strongly (small usable leftover).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.0 * tightness * tightness * (item_size as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage
    // filling existing bins rather than opening new ones.
    score += 3.0 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: only attractive when the item fits poorly
    // everywhere else (large residual gap or dead-space risk).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with stream progress.
        score += 30.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // If the item would leave a small dead space in any existing bin,
        // a fresh bin becomes more appealing.
        if post_residual < 10 {
            score -= 45.0;
        }
        // Lookahead: if next item is large, a fresh bin is useful.
        if next_item_size > 50 {
            score -= 10.0;
        }
    } else {
        // Existing bin that leaves a dead gap AND next item can't use it:
        // penalize slightly to prefer alternatives.
        if post_residual > 0 && post_residual < 10 && next_item_size > post_residual && next_item_size > 0 {
            score += 15.0;
        }
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += 0.5 * ((bin_residual as f64 - item_size as f64) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: exact match of post_residual with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0; // chain fill: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            // next item fits here too: reward tightness of the gap
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit: penalize dead space that blocks it
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to use it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fits exist, scaled by stream progress
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 25.0 + 25.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            penalty -= 15.0; // fresh bin can host the next item too
        }
        if fitting_bins_count > 0 {
            penalty += 10.0; // only open new bin if alternatives are bad
        }
        score += penalty;
    }

    // Small bonus for many open bins: encourage consolidation
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills a large fraction.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 2.5 * fit_ratio * post_residual as f64;

    // Penalize large dead space with non-linear growth.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.6) * 0.05;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, penalize heavily unless fit is tight,
    // since wasting it forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let waste = post_residual as f64;
        score += 15.0 + 0.3 * waste;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // still useful for the lookahead item
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot follow here; mild penalty proportional to unusable gap
        score += 0.15 * (post_residual as f64).min(next_item_size as f64);
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with stream progress (sunk capacity waste).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + 40.0 * progress;
        // If many bins already fit the item, opening a new one is bad.
        score += 10.0 * fitting_bins_count as f64;
        // If the item is large relative to capacity, a fresh bin is more attractive.
        score -= 0.3 * item_size as f64;
        // If open bins are congested (low mean residual), a new bin is more reasonable.
        score -= (bin_capacity as f64 - mean_residual).max(0.0);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host both current and next item
        }
    }

    // Prefer bins whose residual is below the mean (consolidate emptier space usage).
    if bin_residual < bin_capacity {
        score += 0.2 * (bin_residual as f64 - mean_residual);
    }

    // Mild preference for using more open bins when many exist (balance load).
    score -= 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits, penalize post residual non-linearly.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early on, keep flexibility (penalize very small residuals slightly);
    // later, reward tight packing more aggressively.
    let flex = norm_post * (1.0 - norm_post); // peaks at 50% fill
    score -= 6.0 * flex * progress;
    score += 4.0 * flex * (1.0 - progress);

    // Last-chance bin: strong reward, modulated smoothly by progress.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward residual that can still host the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post >= n {
            score -= 3.0 * (1.0 - (post - n) / cap) * (0.5 + 0.5 * progress);
        } else {
            score += 2.0 * (n - post) / cap * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across many bins, smoothed over stream.
    score += 0.5 * open_bins_count as f64 / (total_items as f64).max(1.0) * (1.0 - progress);

    // Prefer bins whose residual deviates favorably from mean residual.
    score += 0.05 * (post - mean_residual) * (1.0 - progress);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * (fitting_bins_count == 1 as usize) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fit classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact fit => perfect closure
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space is bad: penalize residuals that can't hold a typical item
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic classes of residual: multiples of common item sizes (10..80)
    // reward residuals divisible into useful future chunks.
    let mut harmony = 0.0;
    for d in [10u32, 20, 25, 40, 50, 80] {
        if post_residual % d == 0 && post_residual > 0 {
            harmony += 12.0;
        }
    }
    // Semi-harmonic: within 2 of a multiple of 10
    let m10 = post_residual % 10;
    if m10 == 1 || m10 == 9 {
        harmony += 4.0;
    } else if m10 >= 5 {
        harmony -= 3.0;
    }
    score -= harmony;

    // Lookahead coupling: does next item fit harmonically after placement?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next fits exactly or near-exactly
            if post_residual - next_item_size < 5 {
                score -= 25.0;
            } else {
                score -= 10.0;
            }
        } else {
            // next item won't fit here: mildly penalize leaving big residual it can't use
            score += 5.0;
        }
        // next item is huge: prefer keeping a big bin for it
        if next_item_size >= 60 && post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it slightly unattractive unless current bin is very tight
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        // but attractive if item is huge and would leave bad residue elsewhere
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Progress scaling: later in stream, waste matters more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * pr * progress;

    // Tight-fit bonus: small post residual relative to capacity is good
    score -= 20.0 * (1.0 - pr / cap).max(0.0).min(1.0);

    // Mean residual context: placing into a bin below mean residual is efficient
    score -= 0.1 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1..100 range)
    // are unusable unless they can host the lookahead item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size) && next_item_size == 0 {
        score += 1000.0; // fully dead space at end of stream
    } else if post_residual > 0 && (next_item_size == 0 || post_residual < next_item_size) {
        score += 40.0 + 0.5 * post_residual as f64; // dead gap penalized, worse if large
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0; // residual remains usable for lookahead: reward
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // but prefer new bin if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // avoid opening a new bin early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0;
    }

    // Mild tie-break toward bins tighter than the mean residual
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight fits (small post_residual).
    score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: this bin will be exactly filled next step
        } else if post_residual >= next_item_size {
            // next item fits here; penalize leftover slack after the chain
            let chain_left = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.35 * chain_left;
        } else {
            // next item cannot use this bin's residual: dead-space penalty grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer using bins with below-average residual (fill the emptier ones first,
    // keeping large residuals available for large future items).
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate handling: a fresh empty bin has residual == capacity.
    // Make it attractive only when the current item leaves a very awkward fit,
    // otherwise keep open bins preferred.
    if bin_residual == bin_capacity {
        // neutral base for new bin: score = post_residual (already = capacity - item)
        // add a mild penalty so tight existing fits win, but relax it late in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 - 10.0 * progress;
        // if the item is large relative to capacity, a fresh bin is safer
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        // if next item won't fit anywhere after this placement, fresh bin is fine
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Slight preference to consolidate when many bins are open (reduce fragmentation)
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead: residual that can host the next item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.15;
    } else if next_item_size > 0 {
        // Dead space relative to the next item is penalized.
        score += (next_item_size - post_residual) as f64 * 0.08;
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer filling bins that are already relatively full.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Global state: when many bins are open, discourage fragmentation;
    // prefer compacting into existing bins rather than spreading.
    if open_bins_count > 3 {
        score += 2.0;
        score -= (mean_residual - post_residual as f64).abs() * 0.05;
    }

    // Time horizon: early in the stream, be more liberal with new bins
    // (keep flexibility); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * (1.0 - progress);

    // New-bin candidate handling: only attractive for large items that
    // leave little waste, or early in the stream.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        if waste <= 20.0 {
            score -= 18.0;
        } else if progress < 0.3 && waste <= 40.0 {
            score -= 6.0;
        } else {
            score += waste * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Penalize dead space more sharply as the stream matures (non-linear in norm_pr).
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: small post_residual relative to capacity gets a discount.
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + progress);

    // Last-chance bin bonus (smoothly weighted).
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Coupling with mean residual: prefer bins whose post-state tracks the mean.
    let drift = (pr - mean_residual) / cap;
    score += 8.0 * drift * drift;

    // Lookahead: if next item fits the post-residual exactly-ish, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 10.0 * (1.0 - gap) * (1.0 - progress);
    } else if next_item_size > post_residual {
        score += 4.0 * progress;
    }

    // Mild pressure against bin proliferation early on.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover falls into
    // "small residue" classes (0..=10) are excellent; mid-range leftovers (11..=50)
    // are dead-space risk; large leftovers are fine (still roomy).
    let cls = post_residual / 10; // integer division class 0..=10
    match cls {
        0 => score -= 40.0,                       // near-perfect fit
        1 => score -= 20.0,                       // good fit
        2 | 3 => score += 15.0,                   // awkward dead zone
        4 | 5 => score += 5.0,                    // mild waste
        _ => {}                                   // roomy leftover acceptable
    }

    // Modulo-10 harmonic: residues congruent to small sizes (1..=10 mod 10)
    // are more reusable for typical small items.
    let r10 = post_residual % 10;
    if r10 >= 1 && r10 <= 5 {
        score -= 4.0;
    } else if r10 >= 6 {
        score += 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward; if it cannot fit, penalize proportionally.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let diff = post_residual - next_item_size;
            if diff == 0 {
                score -= 45.0;
            } else if diff <= 10 {
                score -= 12.0;
            } else {
                score += diff as f64 * 0.15;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bonus: sole fitting bin should be preferred over opening new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the item is
    // large relative to typical residuals and open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0
            - item_size as f64 * 0.2
            - fragmentation * 0.3
            - progress * 10.0;
    }

    // Mild pressure to consolidate: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (strict dead-space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Pressure from number of open bins: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 12.0 * open_bins_count as f64;
        // but new bin is fine if current fit would leave bad dead space
        if post_residual < 10 && post_residual > 0 {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    }
    // Penalize if post_residual is smaller than next item (dead space for lookahead)
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Stream progression: as stream advances, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Two-step lookahead: reward if the next item exactly/nearly fits the post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chained fit: huge reward
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how well it fills
            let chain_fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 60.0 * chain_fill;
        } else {
            // Next item won't fit: penalize leaving a residual that is too small to be useful
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(60.0);
        }
        // Penalize post_residuals that are dead space (smaller than min item size ~1)
        if post_residual < next_item_size.min(10) {
            score += 25.0;
        }
    } else {
        // Last item: minimize post_residual strongly
        score += 0.8 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual far above mean are good targets
    score -= 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; escalate late in the stream or with many open bins
        score += 30.0 + 2.0 * open_bins_count as f64 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // But if next item is large and current fit is bad, opening fresh is less bad
        if next_item_size > post_residual + item_size {
            score -= 25.0;
        }
    }

    // Early stream: be slightly more willing to open bins for flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * (1.0 - progress) * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can never fit typical future items:
    // small residuals (< next_item_size, or < 10) are wasted.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) { 1.0 } else { 0.0 };
        let tiny = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 8.0 * dead + 6.0 * tiny;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0 * (next_item_size as f64) / 100.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_ratio = (item_size as f64) / (bin_residual as f64);
        if fit_ratio > 0.5 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are poor fits or bins are scarce.
    if bin_residual == bin_capacity {
        // Time-varying aggression: later in the stream, prefer closing out open bins.
        let progress = (step_index as f64) / (total_items.max(1) as f64);
        let scarcity = 1.0 / (1.0 + open_bins_count as f64);
        let mean_tightness = 1.0 - mean_residual / (bin_capacity as f64);
        // Large items justify fresh bins; small items should reuse space.
        let size_pull = (item_size as f64) / 100.0;
        score += 6.0 + 10.0 * progress + 8.0 * (1.0 - scarcity) - 6.0 * size_pull - 4.0 * mean_tightness;
        // A new bin is great if the next item is large too (reserve space pairing).
        if next_item_size >= 40 {
            score -= 4.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier bins).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits (low post_residual); late, tolerate larger residuals
    let progress_coupling = (0.5 - progress) * (norm_pr * (1.0 - norm_pr) * 4.0);
    score += 40.0 * progress_coupling * pr / cap;

    // Reward using nearly-full bins (smooth quadratic in fill ratio)
    let fill = (cap - pr) / cap;
    score -= 30.0 * fill * fill;

    // Last-chance bonus (smoothly scaled by scarcity of fitting bins)
    if fitting_bins_count <= 1 {
        score -= 25.0;
    } else {
        score -= 10.0 / fitting_bins_count as f64;
    }

    // Penalize bins whose residual deviates from mean (smooth quadratic)
    score += 0.3 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Lookahead: reward leaving space for the next item (smooth interaction)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = pr - ns;
        if gap >= 0.0 {
            let closeness = 1.0 - (gap / cap) * (gap / cap);
            score -= 20.0 * closeness;
        } else {
            // next item can't fit here; mild penalty proportional to overshoot
            score += 5.0 + (-gap / cap) * 15.0;
        }
    }

    // New-bin candidate: penalize slightly so we prefer existing bins unless they're poor fits
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * progress;
    }

    // Slight crowding penalty to avoid unbounded bin proliferation
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small residue" classes (<=10, <=20) are near-perfect packs; reward heavily.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // dead-space class: residual smaller than the smallest item is unusable
        if pr < 10 {
            score += 45.0; // unusable dead space penalty
        } else {
            // residue class via integer division thresholds (harmonic bands)
            let band = pr / 10; // 1..=10 harmonic class
            score -= (band as f64) * 3.0; // larger usable residue rewarded mildly
            // modulo-structure bonus: residues that are multiples of 5 pair well
            if pr % 5 == 0 {
                score -= 4.0;
            }
            if pr % 10 == 0 {
                score -= 4.0;
            }
        }
    }

    // Lookahead: if next item fits the post-residual exactly or well, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 - slack * 0.15; // tighter next-fit is better
        } else {
            // next item won't fit here: mild penalty scaled by overflow
            score += ((next_item_size - pr) as f64).min(40.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        let good_fit = item_size >= 60 || (pr < 10 && pr > 0);
        score += if good_fit { 80.0 } else { 40.0 };
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 20.0;
    }

    // Prefer tighter existing bins: compare residual to mean residual
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Fraction-of-capacity fill reward
    score -= (item_size as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it's too small to hold a plausible future item.
    let min_item = 1.0f64;
    if post_residual > 0 {
        let dead = (min_item + (post_residual as f64).max(0.0) * 0.0 - post_residual as f64).max(0.0);
        let _ = dead;
        // treat gaps below ~10 as fully wasted: quadratic penalty
        if post_residual < 10 {
            score += (10.0 - post_residual as f64) * (10.0 - post_residual as f64) * 3.0;
        }
        // gaps that can't fit the lookahead item are less useful
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // reward bins that can also host the next item (chaining)
            score -= 8.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size)
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 20.0 + open_bins_count as f64 * 2.0;
        // but if mean residual across open bins is small (all bins nearly full),
        // opening fresh is attractive
        score -= (mean_residual * 0.8).min(35.0);
        // large lookahead item favors a fresh bin
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Progression: late in the stream, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // good chaining, but penalize leftover slack after the chain
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 - 0.15 * slack;
        } else {
            // next item won't fit here: penalize wasted small post_residual
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter/looser than average appropriately.
    let residual_f = bin_residual as f64;
    let dev = residual_f - mean_residual;
    if dev > 0.0 {
        // bin is looser than average: good place to dump a big item
        score -= 0.10 * dev * (item_size as f64 / 50.0);
    } else {
        // bin is tighter than average: mild penalty unless it's a near-perfect fit
        score += 0.05 * (-dev);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
        if post_residual > 0 && post_residual < 10 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 20.0;
        if next_item_size > 0 {
            // a fresh bin pairs perfectly with two items if item+next <= capacity
            if item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
                score -= 35.0;
            }
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Slight preference for filling bins with more items already implied (tighter residual).
    score += 0.02 * (bin_capacity as f64 - residual_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    if post_residual > 0 {
        let tightness = item_size as f64 / (post_residual as f64 + 1.0);
        score -= 8.0 * tightness;
    } else {
        // Perfect fill is ideal.
        score -= 40.0;
    }

    // Penalize leaving dead space that no future item (>=10) could use well.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny sliver, effectively sealed bin: fine
    } else if post_residual >= 10 && post_residual < item_size {
        // medium gap: mild penalty scaled by gap size
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0; // blocks next item
        }
        // Compatibility with next item's tightness
        if post_residual >= next_item_size && post_residual > 0 {
            let next_tight = next_item_size as f64 / post_residual as f64;
            score -= 5.0 * next_tight;
        }
    }

    // Global state coupling: many open bins with slack -> prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
    score -= 0.5 * pressure * (0.5 + progress);

    // New-bin candidate handling: penalize opening a new bin unless the fit
    // into this empty bin is genuinely better than squeezing elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_penalty = 55.0;
        // If other bins can fit the item, opening a new bin is wasteful unless
        // the item is huge (poor fit everywhere anyway).
        if fitting_bins_count > 1 {
            new_bin_penalty += 30.0;
        }
        // Early in stream, opening bins is cheaper (more future items to fill them).
        new_bin_penalty *= 1.0 - 0.4 * progress;
        // Large items leave awkward residuals in partially filled bins; new bin ok.
        if item_size >= 60 {
            new_bin_penalty -= 15.0;
        }
        // If next item is small, residual of this bin may pair well.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    }

    // Small tie-breaker: prefer bins with lower residual overall (best fit).
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual (waste minimization)
    let mut score = pr;

    // Smooth non-linear coupling: quadratic + cubic shaping of normalized post residual,
    // weighted by stream progress (late stream => prefer tight fits more strongly).
    let shape = norm_pr * norm_pr * (1.0 - norm_pr) * cap;
    score -= shape * (0.5 + 1.5 * progress);

    // Penalize dead space relative to mean residual (coupled smoothly)
    let dead = (pr as f64 - mean_residual) / cap;
    score += dead * dead * cap * (0.3 + 0.7 * progress);

    // Reward last-chance bins smoothly (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 8.0 + 12.0 * progress;
    } else {
        score += 2.0 / fitting_bins_count as f64;
    }

    // Lookahead coupling: smooth bonus if next item fits the post residual
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 / cap).min(1.0);
        let room = norm_pr;
        let compat = (room - fits_next).abs();
        score -= (1.0 - compat.min(1.0)) * (6.0 * (1.0 - progress) + 3.0);
    }

    // Mild pressure against bin proliferation, smoothed by progress
    score += (open_bins_count as f64).ln() * (1.0 + 2.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity/8 granularity
    let class = post_residual / (bin_capacity / 8);
    let next_class = if next_item_size > 0 { next_item_size / (bin_capacity / 8) } else { 0 };

    // Reward if next item's harmonic class matches the leftover class
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        // Perfect class match bonus
        if class == next_class {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize dead space
        score += 6.0;
    }

    // Penalize tiny unusable remainders (dead space under smallest item)
    if post_residual < 10 {
        score += 15.0;
    } else if post_residual < 20 {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: keep it slightly worse than a good existing fit,
    // but better than a bad fit when residuals are large
    if bin_residual == bin_capacity {
        score = 55.0 - mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score = 0.0;
        }
    }

    // Mild penalty for scattering across many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward perfect fits
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Open-bin pressure: mild cost per open bin to encourage consolidation
    score += open_bins_count as f64 * 0.4;

    // New-bin candidate penalty: only wins when existing fits are bad
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if next item is large, opening a fresh bin early can pay off
        if next_item_size > 60 && item_size > 50 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a superlinear penalty on dead space.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain: this bin will be exactly filled next step
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover; penalize proportionally to wasted potential
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    } else {
        // Last item: just minimize leftover.
        score -= 5.0;
    }

    // Relative-to-mean coupling: a bin with much-above-average residual is a better host
    // for large items; a bin already below mean should be drained (kept for small items).
    score += 0.6 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is discouraged unless the item
    // fits poorly everywhere. Make the fresh bin's score a moderate default that
    // tight fits and last-chance bins beat, but poor fits lose to.
    if bin_residual == bin_capacity {
        // A new bin is attractive for large items or late in the stream
        // (future items will amortize it) and when many bins are already open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0
            - 0.25 * item_size as f64          // large items start fresh bins well
            - 10.0 * progress                  // late stream: commit to new bins
            - (open_bins_count as f64).min(20.0) * 0.3; // mild consolidation pressure
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // new bin can also chain the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post residual gets strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space that no plausible item can use (items >= 1, but
    // typical sizes larger): residual < next item size means likely waste.
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 8.0 + 0.15 * (next_item_size - post_residual as u32) as f64;
    }

    // Lookahead synergy: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bin before opening a new one: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize spreading across too many open bins when mean residual is low.
    if open_bins_count > 0 {
        let fill_pressure = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += fill_pressure * 5.0;
    }

    // New-bin candidate: make it moderately attractive only when current bin
    // would leave a large unusable gap, otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Fresh bin can host a pair cleanly; slightly encourage.
            score -= 4.0;
        }
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
    }

    // Time horizon: early in the stream, be conservative with new bins;
    // late in the stream, prioritize tight fits even more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild coupling with item size: large items deserve tighter packing priority.
    score -= 0.05 * item_size as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: prefer small post residual, with a non-linear (quadratic) penalty
    // on large leftover space, whose strength grows with stream progress.
    let mut score = pr * (1.0 + 1.5 * progress * fit_norm);

    // Cubic coupling: dead space that is too small for typical future items
    // is penalized super-linearly.
    score += 4.0 * fit_norm * fit_norm * fit_norm * cap * (0.3 + 0.7 * progress);

    // Tight fits (post_residual near 0) rewarded smoothly.
    score -= 10.0 * (-2.0 * pr).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (smoothly scaled by progress).
    if fitting_bins_count <= 1 {
        score -= 8.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 6.0 * (-gap / cap).exp();
    } else {
        // Last item: strongly prefer filling bins as tightly as possible.
        score -= 12.0 * (1.0 - fit_norm);
    }

    // Diversification: mildly penalize bins whose residual deviates from the
    // mean, encouraging a coherent residual profile across open bins.
    score += 0.5 * ((pr - mean_residual) / cap).abs();

    // Late in the stream, prefer closing bins (fewer open bins) smoothly.
    score += 0.3 * progress * open_bins_count as f64;

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a good fit; make empty-bin score mildly unattractive by
    // default but allow it late in the stream to spread load.
    if bin_residual == bin_capacity {
        score += 3.0 - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 define "dead space classes".
    let residue = post_residual % 10;
    // Residuals that are multiples of 10 are highly reusable -> reward.
    if residue == 0 {
        score -= 8.0;
    } else if residue <= 3 {
        // Tiny unusable slivers -> penalize (dead space).
        score += 6.0 + 2.0 * residue as f64;
    } else if residue >= 7 {
        // Large-ish residue but awkward class -> mild penalty.
        score += 2.0;
    }

    // Integer-division threshold on post_residual: quarters of capacity.
    let quarter = bin_capacity / 4;
    if post_residual >= 2 * quarter {
        score -= 5.0; // bin still half-full-capable, keep it attractive
    } else if post_residual < quarter {
        score += 4.0; // nearly full, low future utility
    }

    // Perfect fit detection: post_residual exactly matches next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0; // chains perfectly with lookahead
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 3.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 3.0; // next item cannot follow here
        }
    }

    // Last-chance bonus: only this bin fits -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a fresh bin is only good if the item
    // is large and current bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if item_size > bin_capacity / 2 && fragmentation > 15.0 {
            score -= 4.0;
        } else {
            score += 10.0; // prefer existing bins by default
        }
    }

    // Late in the stream, tighten packing (less tolerance for loose residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // Coupling with mean residual: prefer bins close to the mean (balanced classes).
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small gaps that could only fit tiny items are penalized proportionally.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 30.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a compact fit exists.
    score += (open_bins_count as f64) * 1.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use the gap; penalize leaving a gap sized near it.
            if post_residual >= next_item_size.saturating_sub(10) {
                score += 8.0;
            }
        }
    }

    // Prefer filling bins with larger residuals early (keep small-residual bins for small items).
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Mild stream-progression coupling: tighten packing as stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;

    // New-bin candidate baseline: empty bin must not win unless open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead: reward exact match of next item into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-item packing
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64); // tight fit bonus
        } else {
            // next item cannot fit here: penalize large dead space
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize residual far above mean (wasteful bin) but reward below-mean tight fits.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Tight fit reward: small post_residual is good.
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        score += 5.0; // default penalty: prefer existing bins
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 10.0; // big item that would fragment any bin -> open fresh bin
        }
        if post_residual as f64 > mean_residual * 1.5 && fitting_bins_count <= 1 {
            score -= 12.0; // existing fits are poor -> new bin is fine
        }
    }

    // Late-stream consolidation: be pickier about dead space as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.4 * post_residual as f64;

    // Avoid spreading across too many open bins with tiny items.
    if open_bins_count > 4 && item_size < 30 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = post_residual - next_item_size;
        if chain_waste == 0 {
            score -= 20.0; // perfect chain fit
        } else {
            score -= 8.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize proportional waste.
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bonus: only one open bin fits; avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // the current item is large (would leave big waste in any open bin)
    // or when open bins are already crowded (low mean residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let large_item = item_size as f64 / bin_capacity as f64;
        let new_bin_bonus = 40.0 * large_item * crowding
            + 20.0 * progress * large_item
            + (post_residual as f64 / bin_capacity as f64) * 10.0;
        score -= new_bin_bonus;
        // Slight baseline penalty so a new bin is not opened for trivially small items.
        score += 12.0 * (1.0 - large_item);
    }

    // Mild global regularization: many open bins -> prefer consolidating
    // into bins with larger residuals (spread load evenly).
    score += 0.05 * open_bins_count as f64 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Time-horizon shaping: early in the stream, be more conservative with
    // existing bins (favor flexibility); late, pack aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fits (low post_residual); later, dead space
    // becomes more costly as future item supply is uncertain.
    let mut score = pr * (1.0 + 1.7 * progress * progress);

    // Smooth cubic interaction: penalize mid-range residual space that is
    // hard to fill, reward near-full bins.
    score += 12.0 * norm_pr * (1.0 - norm_pr) * (0.5 - norm_pr) * (1.0 + progress);

    // Lookahead: reward bins whose post_residual fits the next item,
    // smoothly scaled by how well it fits.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_quality = 1.0 - ((pr - nxt) / cap).abs();
            score -= 9.0 * fit_quality * (1.0 - progress * 0.5);
        } else {
            score += 4.0 * (1.0 - nxt / cap) * progress;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - progress);
    }

    // Mild penalty for spreading residual mass across many bins vs mean.
    score += 0.4 * (pr - mean_residual) * (1.0 + progress);

    // New-bin candidate: make empty bins less attractive unless residuals
    // across open bins are large (smooth gating via mean_residual).
    if bin_residual == bin_capacity {
        score += 8.0 + 0.15 * mean_residual - 10.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" residue class (multiples of 10 / small residues) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional fill: prefer bins that become tightly packed.
    let fill = 1.0 - pr / cap;
    score -= 40.0 * fill * fill;

    // Dead-space penalty: residuals that are too small to host the smallest
    // plausible future item are worthless.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Modulo harmonic classes on post_residual: leftover congruent to 0 mod 10
    // is highly reusable; residues 1..5 are near-useless slivers.
    let m = post_residual % 10;
    match m {
        0 => score -= 12.0,
        1 | 2 => score += 15.0,
        3 | 4 | 5 => score += 8.0,
        _ => {}
    }

    // Integer-division threshold coupling: does post_residual still fit the
    // next item (lookahead)? Reward exact future compatibility.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // How tightly will the next item fit here?
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 30.0; // perfect two-item chain
            } else if gap < 10 {
                score -= 15.0;
            } else {
                score -= 5.0 * (10.0 - (gap as f64 / 10.0)).max(0.0);
            }
        } else {
            // Next item cannot use this leftover: penalize proportionally.
            score += 10.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when residuals are globally large or
    // the item simply does not fit well anywhere.
    if bin_residual == bin_capacity {
        let avg_waste = (mean_residual - pr).max(0.0);
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        let penalty = 55.0 + 0.5 * pressure + 0.3 * avg_waste;
        // Opening a new bin is cheap if mean residual is small (all bins tight).
        score += penalty * (mean_residual / cap).clamp(0.0, 1.0);
        // But if item leaves a huge hole in any existing bin, new bin wins.
        if post_residual > 60 {
            score -= 10.0;
        }
    }

    // Mild stream-phase adaptation: later in the stream, prefer tighter packing.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * phase * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

