    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for the next item -> future dead space risk.
        score += 5.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; a new empty bin
    // candidate gets penalized proportionally to open_bins_count.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.5 * open_bins_count as f64;
        // But if no open bin fits well, allow opening: soften when item is large.
        if item_size > 60 {
            score -= 10.0;
        }
    }

    // Mild bias toward tighter bins relative to mean residual.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = 1.0 - (post / cap); // 1.0 = perfect fit
    score -= 3.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post).abs() < 1.0 {
            score -= 25.0; // perfect chain: next item completes this bin
        } else if nxt <= post {
            // next item fits: reward proportionally to how well it uses leftover
            let use_ratio = nxt / post.max(1.0);
            score -= 10.0 * use_ratio;
        } else {
            // next item cannot fit here: penalize dead space, worse for big overshoot
            let waste = (nxt - post) / cap;
            score += 8.0 * waste;
        }
    }

    // Relative to mean residual: bins tighter than average are good targets
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        // new bin attractive early or when many bins are open (fragmentation)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 - 4.0 * progress;
        if open_bins_count > 3 {
            score += 2.0 * (open_bins_count as f64);
        }
        // still allow new bin if item is huge and would leave tiny residue elsewhere
        if item_size as f64 / cap > 0.8 {
            score -= 5.0;
        }
    }

    // Prefer filling nearly-full bins completely (eliminate dead space)
    if post == 0 {
        score -= 20.0;
    } else if post < 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty (dead space is quadratically bad).
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it, otherwise a new bin gets opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: penalize opening a bin unless the item is large
    // (good long-term tenant) or existing bins would leave bad residuals.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // Large items justify a fresh bin; small items should squeeze into existing bins.
        score += 40.0 * (1.0 - fill_frac);
        // Late in the stream, closing out open bins matters more: discourage new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // Many open bins already: discourage spreading further.
        score += 2.0 * open_bins_count as f64;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Small leftover that next item cannot use: mild penalty scaled by waste.
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Prefer bins below the mean residual (consolidate waste in few bins).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev;

    // Early stream: encourage keeping residuals flexible (avoid over-tightening early).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && post_residual > 0 && post_residual < 20 {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: post_residual normalized and shaped by progress
    let r = post_residual as f64 / bin_capacity as f64;
    let poly = r * r * (1.0 - progress) + r * progress * progress;
    score += 20.0 * poly;

    // Penalize dead space more as stream progresses (less time to fill gaps)
    score += 8.0 * r * r * progress;

    // Reward tight fits (small post residual) especially late
    score -= 6.0 * (1.0 - r) * (1.0 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly in post residual, strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual {
        score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // New-bin candidate: mildly discouraged unless current residuals are large
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (mean_residual / bin_capacity as f64);
    }

    // Prefer bins with residual below mean (consolidate small gaps)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect fit classes (0, 10, 20, ...)
    let class = post_residual % 10;
    // Reward small dead space in fine granularity
    score -= 12.0 * ((10 - class) as f64 / 10.0) * (1.0 - (post_residual as f64 / bin_capacity as f64).powi(2));

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Integer-division thresholds on post_residual: dead-space zones
    if post_residual <= 10 && post_residual > 0 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual > 10 && post_residual <= 30 {
        score -= 8.0; // still usable for small items
    } else if post_residual > 30 && post_residual <= 60 {
        score -= 15.0; // comfortable usable zone
    }

    // Lookahead coupling: does next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + 0.5 * next_item_size as f64; // chain placement possible
            // harmonic match: next item exactly fills a class boundary
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 20.0;
            }
        } else {
            score += 10.0 + 0.3 * (next_item_size - post_residual) as f64; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: keep it neutral-ish, only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // open new bin when existing residuals are small relative to item
        score = 60.0 + 40.0 * fragmentation - 50.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 15.0; // large next item benefits from fresh bin
        }
    }

    // Mild penalty for spreading across too many bins when mean residual is large
    score += 0.05 * open_bins_count as f64 * (1.0 - mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit is excellent
    }

    // Non-linear waste: residual below half of smallest possible item is dead space.
    if post_residual < 10 && post_residual > 0 {
        score += (10.0 - post_residual as f64) * 6.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    let pressure = open_bins_count as f64 / 8.0;
    score += new_bin * pressure * 20.0;

    // Last-chance bonus: only one fitting bin, use it rather than waste.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits in the post residual, reward.
    if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
        score -= 8.0;
    }
    // Next item exactly fills post residual -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Early stream: keep bins tight; late stream: prefer closing out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.3 + 0.5 * progress);

    // Prefer bins tighter than the mean residual (good fill).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        // Perfect chain: next item fills this bin completely afterwards.
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual < next_item_size {
            // Dead space that even the next item cannot use: penalize.
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fill.
        score += 0.3 * post_residual as f64;
    }

    // Prefer bins already below mean residual (densely packed bins).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize creating tiny unusable slivers (worse than a moderately full bin).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Mild penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    // Early in stream: slightly favor compacting into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if next_item_size > 0 && dead < next_item_size as f64 {
            score += 0.5 * (next_item_size as f64 - dead);
        }
        // General penalty for awkward residuals (small but nonzero).
        if dead < 10.0 {
            score += 6.0;
        }
    }

    // Lookahead: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 4.0; // next item won't fit here; slight penalty
        }
    }

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global state: when many bins are open relative to progress, prefer consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_pressure = (open_bins_count as f64 / (1.0 + progress * 20.0)).min(3.0);
    score += 1.5 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (balance residual usage).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: allow opening a fresh bin only when existing fits are poor
    // or item is large relative to residuals; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let good_alternative = fitting_bins_count > 0
            && (bin_capacity as f64 - mean_residual) < 0.35 * bin_capacity as f64;
        if good_alternative && item_size < 60 {
            score += 45.0; // discourage opening new bin
        } else {
            score -= 10.0; // fresh bin is attractive for poor fits / large items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (low post residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits; later, demand tight fits more strongly.
    let tightness = (pr / cap).powi(3) * (1.0 + 3.0 * progress);
    score += tightness * cap;

    // Reward near-perfect fits with a smooth quadratic bonus
    let fit_quality = 1.0 - (pr / cap);
    score -= 12.0 * fit_quality * fit_quality * fit_quality;

    // Penalize leaving residual just below the smallest plausible next item,
    // using a smooth logistic-shaped dead-zone term
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = nxt - pr;
        let dead = 1.0 / (1.0 + (-0.35 * gap).exp());
        score += 15.0 * dead * (1.0 - progress * 0.4);
        // Reward bins whose post residual still fits the lookahead item
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap).powi(2);
        }
    }

    // Last-chance bin: smooth urgency reward when few fitting bins remain
    if fitting_bins_count <= 1 {
        score -= 8.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across too many open bins relative to mean residual
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * (pr - mean_residual).abs() / cap;

    // New-bin candidate: discourage opening a new bin unless open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = 1.0 - (mean_residual / cap).min(1.0);
        score += 20.0 * (1.0 - fragmentation) + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits heavily rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 10 {
        score += 12.0; // tiny dead space is nearly useless
    } else if pr <= 25 {
        score += 4.0;
    } else if pr <= 50 {
        score -= 2.0;
    } else {
        score -= 6.0; // large residual stays reusable
    }

    // Modulo-class bonus: residuals that are multiples of common item
    // granularity (10/20/25) are more likely reusable by future items.
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 5.0;
    }
    if pr > 0 && pr % 5 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward; if next item cannot fit, penalize mildly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) == pr {
            score -= 25.0;
        } else if (next_item_size as u32) <= pr && pr - next_item_size <= 10 {
            score -= 10.0;
        } else if next_item_size as u32 > pr {
            score += 8.0 * (nxt / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless post_residual would be tiny.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if pr > 0 && pr < 10 {
            score += 10.0;
        }
    }

    // New-bin candidate: opening a fresh bin is only attractive when the
    // current item is large and would leave a bad residual elsewhere.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 18.0;
        // large items leave large residuals anywhere; new bin is fine
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // early in the stream, avoid bin proliferation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // if open bins are mostly full (low mean residual), new bin is natural
        if mean_residual < 15.0 {
            score -= 8.0;
        }
    }

    // Prefer fuller bins overall: reward proximity of residual to item.
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * (1.0 - tightness).min(1.0).max(0.0) * 0.0; // neutralized
    score -= (1.0 - (post_residual as f64 / cap)) * 8.0;

    // Slight penalty for accumulating too many open bins.
    score += (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small post-residuals that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 6.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * (open_bins_count as f64) * (1.0 - progress);

    // Mean residual coupling: if this bin's residual is far below mean, it's already tight — prefer it.
    let residual_gap = mean_residual - bin_residual as f64;
    score -= 0.15 * residual_gap;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; mild penalty if post_residual becomes dead space.
        if post_residual < 10 {
            score += 5.0;
        }
    }

    // New-bin candidate: keep it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, modulated by how poor the existing fits are.
        score = bin_capacity as f64 - 10.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // forced new bin
        } else {
            // Only prefer new bin if best existing fit would leave tiny dead space.
            if post_residual_existing_proxy(post_residual, bin_residual, item_size) {
                score -= 12.0;
            }
        }
    }

    score
}

#[inline]
fn post_residual_existing_proxy(post_residual: u32, bin_residual: u32, item_size: u32) -> bool {
    // If this call is for an open bin (not the empty-bin candidate), judge dead space.
    bin_residual != 100 || (item_size == 0 && post_residual == 100)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual).
    score -= 60.0 * (-post_residual as f64 / 12.0).exp();

    // Exact or near-exact fit bonus.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual < 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post-residual
    // matches the next item size exactly.
    if next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item: chain two items perfectly.
        if gap == 0.0 {
            score -= 120.0;
        } else {
            score -= 40.0 * (-gap / 15.0).exp();
        }
        // Penalize leaving a residual that is unusable for the next item
        // but still large (dead space).
        if post_residual < next_item_size as u32 {
            score += 0.35 * post_residual as f64;
        }
    }

    // Compare against mean residual: prefer bins tighter than average,
    // penalize packing into already-loose bins.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 130.0;
        // Cheaper to open a new bin when the item is large and current
        // residuals are small (item wouldn't fit well anywhere anyway).
        let tightness = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 60.0;
        }
        if tightness < 0.15 && fitting_bins_count > 0 {
            // Existing bins barely fit the item -> poor fits; new bin OK.
            score -= 45.0;
        }
        // Late in the stream, opening bins is fine (few future regrets).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * progress;
    }

    // Mild penalty for spreading across many open bins (encourage consolidation).
    score += 0.6 * open_bins_count as f64;

    // Small tie-breaker: prefer bins with more residual used already.
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Perfect chaining: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is costly; only attractive when
    // the item is large relative to capacity or existing residuals are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Penalize new bins generally; relax penalty when item is big or few bins fit.
        let mut new_bin_cost = 25.0;
        new_bin_cost -= 15.0 * item_frac;
        if fitting_bins_count == 0 {
            new_bin_cost -= 30.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        new_bin_cost += 10.0 * progress;
        // If mean residual across open bins is small, new bin is more justified.
        new_bin_cost -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 5.0;
        score += new_bin_cost.max(-5.0);
    } else {
        // Mild preference for bins already below mean residual (balancing).
        score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: late in stream, dead space matters more
    let late = progress * progress;
    score += 40.0 * late * norm_pr * norm_pr;

    // Penalize large post-residual relative to mean residual (fragmentation)
    score += 6.0 * (pr - mean_residual).abs() / cap;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post residual fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as f64 >= nxt {
            score -= 8.0 * (1.0 - pr / (pr + nxt)) * (1.0 - late);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for spreading across too many open bins
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize slightly unless current fit is very tight
    if bin_residual == bin_capacity {
        let tight = (item_size as f64 / cap).powi(3);
        score = 10.0 + 30.0 * (1.0 - tight) - 20.0 * late * tight;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (modulo classes on capacity) ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (post_residual % 10) as f64; // decile class of leftover

    // Dead-space penalty: leftovers in "awkward" harmonic classes are hard to fill.
    // Classes near 1..9 (small slivers) are worst; class 0 (multiple of 10) is fine.
    let awkward = if post_residual == 0 {
        -8.0 // perfect fill: strongly reward
    } else if post_residual < 10 {
        6.0 + class // tiny sliver: unusable dead space
    } else {
        (class - 5.0).abs() * 0.15 // distance from class-5 centroid: mild shaping
    };
    score += awkward;

    // --- Capacity fraction thresholds (integer division) ---
    // How many copies of the item would still fit in the residual? (quotient)
    let q = if item_size > 0 { post_residual / item_size } else { 0 };
    let q_f = q as f64;
    score -= q_f * 3.0; // reward bins that could take repeats of this item (good "rhythm")

    // Harmonic fill ratio: post_residual as fraction of capacity, quantized to eighths
    let frac = pr / cap;
    let eighth = (frac * 8.0).floor() as f64;
    score -= eighth * 0.8; // prefer bins whose fill lands on coarse harmonic marks

    // --- Lookahead coupling: does next_item_size divide into post_residual? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here too: strong reward, scaled by leftover after both
            let both = post_residual - next_item_size;
            score -= 4.0 + (both % 10) as f64 * 0.1;
            if both % 10 == 0 {
                score -= 2.0; // harmonic alignment of the pair
            }
        } else {
            // next item cannot use this leftover: penalize proportionally to mismatch
            let gap = next_item_size - post_residual;
            score += (gap % 10) as f64 * 0.4 + 1.0;
        }
    } else {
        // last item: only exact closure matters
        score -= if post_residual == 0 { 10.0 } else { 0.0 };
    }

    // --- Last-chance logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0; // this is the only open bin that fits: avoid opening a new bin
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Brand-new bin: baseline cost of opening. Attractive only if no open bin
        // fits well (few fitting bins) or stream is early and bins are scarce.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_bonus = (open_bins_count as f64).sqrt() * 1.5;
        score += 12.0 + open_bonus - (1.0 - fitting_bins_count.min(3) as f64) * 2.0
                 - progress * 3.0;
        // If item is large, a fresh bin keeps room for future large items
        if item_size > bin_capacity / 2 {
            score -= 3.0;
        }
    }

    // --- Mean residual drift: prefer bins near the mean (keeps bin states uniform) ---
    let dev = (pr - mean_residual).abs();
    score += dev * 0.05;

    // --- Mild aging: later in stream, tighten packing (favor fuller bins) ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (pr / cap) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (items are >= 1, but gaps below ~10 waste capacity). Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Moderate gaps (10..20) are partially usable: mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // If the next item fits exactly into the post residual, reward this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    // If next item fits inside post residual, mild reward.
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }
    // If next item cannot fit in post residual, penalize creating stranded space.
    else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bins pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins tighter than the mean residual (good packing density).
    score += (mean_residual - bin_residual as f64) * 0.8;

    // New-bin candidate: only attractive when current bins are crowded or
    // the item simply does not leave a usable gap anywhere. Baseline penalty
    // keeps open bins preferred unless they fit poorly.
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * 2.0;
        // Early in the stream, opening bins is cheaper (more future to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (post_residual small relative to item size)
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let tightness = post_residual as f64 / (item_size as f64).max(1.0);
        score -= 40.0 / (1.0 + tightness * 3.0);
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 90.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 / (1.0 + slack / 10.0);
        } else {
            // next item cannot fit here after placement; penalize proportionally
            let miss = (next_item_size - post_residual) as f64;
            score += 15.0 * (miss / 50.0).min(1.5);
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than the mean
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when decent open bins exist (new-bin candidate)
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 {
            (next_item_size as f64 / bin_capacity as f64).min(1.0)
        } else {
            0.5
        };
        score += 25.0 + 20.0 * (1.0 - pressure);
        // New bin is more attractive early in the stream or when bins are nearly full
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
    }

    // Slight penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate: penalize so it is only chosen when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Larger items justify a fresh bin more (they would leave tiny residuals elsewhere).
        let size_relief = (item_size as f64 / bin_capacity as f64) * 60.0;
        // Later in the stream, be more conservative about opening bins.
        let time_penalty = 20.0 + 30.0 * progress;
        score += 80.0 - size_relief + time_penalty;
        return score;
    }

    // Reward tight fits: small post_residual is valuable dead-space avoidance.
    if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 25 {
        score -= 15.0;
    } else if post_residual > 60 {
        // Very loose fit: penalize wasting a big-capacity bin on a small item.
        score += 10.0;
    }

    // Lookahead (k=2): if the next item exactly fills the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it uses leftover space.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            // Next item would have fit before this placement but not after: mild penalty.
            score += 8.0;
        }
    }

    // Last chance: if this is the only bin that can fit the item, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count == 2 {
        score -= 10.0;
    }

    // Global state: if mean residual across open bins is high, prefer bins below the mean
    // (consolidate into emptier bins) to keep large residuals available for big items.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Many open bins: encourage consolidation to avoid bin sprawl.
    if open_bins_count > 5 {
        score -= 2.0 * (open_bins_count.min(20) as f64 - 5.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: prefer tight fits but tolerate leftovers (many items remain to fill them).
    // Late: strongly penalize dead space since fewer chances to reuse it.
    let tightness = 1.0 - (pr / cap); // 1 = perfect fit, 0 = empty bin
    let poly = tightness * tightness * (1.0 + progress) + tightness * progress * progress;
    score -= poly * cap * 0.6;

    // Reward bins whose residual matches the lookahead item (k=2 lookahead coupling).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= (1.0 - gap / cap).max(0.0) * cap * 0.25 * (1.0 - progress);
    }

    // Penalize opening a new bin when other bins fit (smooth, not piecewise).
    if bin_residual == bin_capacity {
        score += cap * (0.4 + 0.6 * progress) + open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= cap * 0.8;
    }

    // Mild preference for bins below mean residual (consolidate fullness).
    score += (mean_residual - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic dead-space classes: residuals that can no longer host typical
    // small items are wasted capacity. Classify post_residual by integer
    // division into decile classes; low classes (near-zero residual) are good,
    // but a tiny unusable sliver (1..=3) is worse than an exact fit.
    let decile = post_residual / 10;
    score += decile as f64 * 1.5; // larger leftover -> mildly worse bin choice
    if post_residual > 0 && post_residual <= 3 {
        score += 12.0; // sliver dead space penalty
    }

    // Lookahead coupling: if the next item still fits here, this bin stays
    // productive; reward proportionally to how well it nests.
    if next_item_size > 0 && next_item_size <= post_residual {
        let nest = next_item_size as f64 / post_residual as f64;
        score -= 6.0 + 10.0 * nest;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: leftover risks becoming dead space.
        score += 4.0;
    }

    // New-bin candidate detection (empty bin).
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity.
        score += 30.0;
        // If this bin is the ONLY option that fits, opening a new bin avoids
        // forcing a bad squeeze; soften the penalty.
        if fitting_bins_count <= 1 {
            score -= 22.0;
        }
        // If open bins on average have plenty of room, prefer reusing them.
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only open bin that can host the item,
    // using it avoids opening a new bin — reward unless it creates a sliver.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 3 && post_residual > 0 {
            score -= 4.0; // still prefer it over a new bin, but less eagerly
        } else {
            score -= 14.0;
        }
    }

    // Late-stream consolidation: as the stream matures, favor filling existing
    // bins tightly rather than spreading across many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Slight preference for bins already below average fullness when the item
    // is large (balance load, keep big holes available for big future items).
    if item_size >= 60 && (bin_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }

    // Reward tight fits (waste ratio low).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste_ratio) * 12.0;

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that blocks the known next item.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Slight preference for bins tighter than the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when existing bins would leave big waste.
    if bin_residual == bin_capacity {
        score += 20.0 - waste_ratio * 0.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact fit bonus: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Near-perfect fit, small dead space.
        score -= 15.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible future item.
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin remains useful for the next item: strong reward,
            // scaled by how snugly the next item fits the leftover.
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 10.0 + 8.0 * snug;
        } else {
            // Placing here strands the next item elsewhere: penalty grows
            // with how close the leftover came to fitting (frustration).
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 + 4.0 * (1.0 - gap / (bin_capacity as f64));
        }
    }

    // Compare post_residual against mean residual: prefer bins that reduce
    // fragmentation relative to the fleet average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance logic: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // open bins exist and the stream is progressing (waste of capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 30.0 + 20.0 * progress;
        // If the item is small relative to capacity, opening a fresh bin wastes space.
        let waste = 1.0 - (item_size as f64) / (bin_capacity as f64);
        score += base + 25.0 * waste;
        // But if no other bin fits (fitting_bins_count == 1 and it's the new bin),
        // the penalty should be softened since it's forced anyway.
        if fitting_bins_count == 1 {
            score -= 45.0;
        }
    }

    // Mild preference for filling bins with larger residuals when many bins are open
    // (consolidation pressure).
    score += 0.05 * (open_bins_count as f64) * (bin_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect or near-perfect fill gets a strong bonus
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Penalize tiny dead space that nothing can use (items >= 1, so any residual is usable,
    // but very small residuals waste the bin); encourage residual that pairs well with small items.
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item can't follow here; slight penalty if we leave a large awkward gap
            let gap = (next_item_size - post_residual) as f64;
            if gap < 20.0 {
                score += 2.0 + 0.2 * gap;
            }
        }
    } else {
        // Last item: strongly prefer filling existing bins as much as possible
        score -= 25.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item is large
    // or all existing fits are poor. For an empty bin (residual == capacity), add a penalty
    // that scales with how many open bins could have taken the item.
    if bin_residual == bin_capacity {
        score += 18.0 + 4.0 * fitting_bins_count as f64;
        // Late in the stream, opening a new bin is less costly (fewer future pairings needed)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
        // Large items keep new bins useful
        score -= 0.15 * item_size as f64;
    }

    // Prefer bins whose residual is already below the mean (consolidating waste),
    // and mildly prefer fewer open bins (keeps future choices concentrated).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * dev;
    score += 0.3 * open_bins_count as f64;

    // Prefer using fuller bins overall
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits, with smooth polynomial shaping of dead space
    let mut score = pr;

    // Non-linear coupling: post residual vs stream progress.
    // Early on, larger residuals are acceptable; later, punish leftover space more.
    let prog_shape = (0.5 + 2.0 * progress * progress) * (1.0 + 0.5 * progress);
    score += prog_shape * 40.0 * x * (1.0 - x * x);

    // Smooth penalty for very small residuals (dead space), strongest late in stream
    let tiny = (1.0 - x).powi(6); // near-full bins
    score += tiny * (10.0 + 30.0 * progress);

    // Reward bins whose residual is close to mean residual (harmonized pool)
    let mean_dev = (pr - mean_residual) / cap;
    score += 15.0 * mean_dev * mean_dev * (0.5 + progress);

    // Lookahead: if next item fits exactly in post residual, reward strongly (smooth bump)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs();
        let bump = (-fit_gap / 12.0).exp();
        score -= 35.0 * bump * (1.0 - 0.5 * progress);
        // penalize if post residual is just barely too small for next item (fragmentation risk)
        let near_miss = (-((pr - nxt).abs() - 8.0f64).abs() / 6.0).exp() * (pr < nxt) as i32 as f64;
        score += 20.0 * near_miss * (0.5 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, encourage using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 2.0 * (open_bins_count as f64).ln() * progress;

    // New-bin candidate: empty bin gets neutral-ish score; discourage early opening,
    // allow it when post residual of this fresh bin is a good canvas
    if bin_residual == bin_capacity {
        score = 60.0 - 40.0 * progress + 10.0 * x;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space quality.
    // Class 0: residual exactly 0 (perfect fit) -> huge reward.
    // Class 1: residual in 1..=9 -> unusable sliver, heavy penalty.
    // Class 2: residual in 10..=19 -> fits smallest item class.
    // Class 3: residual >= 20 -> still usable.
    let post_class: u32 = if post_residual == 0 { 0 } else if post_residual < 10 { 1 } else if post_residual < 20 { 2 } else { 3 };
    match post_class {
        0 => score -= 500.0,
        1 => score += 120.0,
        2 => score -= 20.0,
        _ => {}
    }

    // Integer-division harmonic: how many future min-items (size 10) fit in the gap.
    let slots = post_residual / 10;
    score -= slots as f64 * 8.0;

    // Lookahead harmony: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Prefer exact modulo alignment of next item into gap.
            let m = post_residual % next_item_size.max(1);
            score -= 60.0 - (m as f64) * 2.0;
        } else {
            score += 30.0;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we don't open bins frivolously; scales with open bins.
        score += 150.0 + 20.0 * open_bins_count as f64;
        // But if item leaves a bad residual class in any open bin context,
        // opening fresh is fine: new bin residual is maximal, reward capacity fraction.
        score -= (item_size as f64 / bin_capacity as f64) * 100.0;
        if fitting_bins_count == 0 {
            score -= 400.0; // no open bin can fit at all -> must open
        }
    }

    // Waste fraction coupling: penalize bins whose residual is far below mean (fragmented).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += (mean_residual - post_residual as f64).abs() * 0.3;

    // Progression-aware tightening: late in stream, prefer tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= frac * 50.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (min size 1, but
    // practically below next_item_size or tiny gaps) are wasted capacity.
    let min_useful = if next_item_size > 0 { next_item_size.min(80).max(10) } else { 10 };
    if post_residual < min_useful {
        score += (min_useful - post_residual) as f64 * 3.0;
    }

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual - next_item_size) as f64 * 0.2;
    } else if next_item_size > 0 {
        score += 8.0; // next item won't fit here; mild penalty
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it when few bins are open (early stream).
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure
        score += 30.0 + open_bins_count as f64 * 4.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // late in stream, be even more reluctant to open bins
        score += progress * 10.0;
    } else {
        // using an existing bin relieves pressure slightly
        score -= open_bins_count as f64 * 0.5;
    }

    // Prefer bins below mean residual (consolidate space into tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact matches with the next item (2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - fit_gap / bin_capacity as f64);
    }

    // Penalize post-residuals that are small dead space (unusable for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter fit).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if the item fits perfectly in a fresh bin and next item is large, allow it.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in stream, tighten packing (dead space becomes costlier).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on leftover space.
    score += 0.6 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Reward perfect fit strongly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual unusable by next item: penalize dead space.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are all bad.
    if bin_residual == bin_capacity {
        // Base penalty to prefer filling existing bins.
        score += 6.0;
        // But if existing bins have large residuals and few fit, opening is fine.
        score -= 0.04 * mean_residual * (open_bins_count as f64).sqrt();
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
        // Late in stream, avoid opening unnecessary bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * progress;
    }

    // Prefer bins whose residual is below the mean (tighter than average).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight preference for fewer open bins when many are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: post residual, weighted by progress (late stream => waste matters more)
    let mut score = pr * (0.5 + 1.5 * progress);

    // Non-linear coupling: penalize mid-range residuals (dead space), reward near-zero and tight fits
    let dead = norm_pr * (1.0 - norm_pr);
    score += 40.0 * dead * (0.3 + 0.7 * progress) * (1.0 - (item / cap).powi(2));

    // Smooth reward for exact/near-exact fit (post_residual small)
    score -= 25.0 * (1.0 - norm_pr).powi(3);

    // Lookahead: reward if next item fits the post residual, smoothly
    if nxt > 0.0 {
        let fits = (pr - nxt).max(0.0) / cap;
        score -= 15.0 * (1.0 - fits.min(1.0)) * (nxt / cap) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Many open bins: mild penalty to encourage consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - norm_pr);

    // New-bin candidate: penalize opening a new bin unless residual is large relative to mean
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress - (mean_residual / cap).min(1.0) * 15.0;
    }

    // Global smooth coupling term
    score += 10.0 * (norm_pr - 0.5).powi(2) * (progress * std::f64::consts::PI).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fills (post==0) are perfect.
    if post_residual == 0 {
        score -= 500.0;
        return score;
    }

    // Class of "dead space": residuals too small for typical items are costly.
    // Items are 1..=100; a residual < next_item_size is dead unless a future item fits.
    if next_item_size > 0 {
        if post_residual < next_item_size.min(10).max(1) {
            score += 60.0; // dead space relative to smallest plausible item
        } else if post_residual >= next_item_size {
            score -= 25.0; // bin can host the lookahead item: strong reward
        }
    }

    // Modular classes on post_residual (capacity 100): residuals near common
    // item-size residues (multiples of 10) are more reusable.
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 12.0;
    }
    if pr % 20 == 0 {
        score -= 8.0;
    }
    if pr % 25 == 0 {
        score -= 6.0;
    }
    if pr % 50 == 0 {
        score -= 10.0;
    }

    // Integer-division thresholds: quintiles of remaining capacity.
    let quint = pr * 5 / bin_capacity; // 0..4
    score += quint as f64 * 3.0; // larger post-residual classes slightly penalized (waste)

    // Very small leftovers are dead space.
    if pr <= 5 {
        score += 45.0;
    } else if pr <= 15 {
        score += 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        score += 4.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / cap;
    score -= 30.0 * fill_ratio;

    // New-bin candidate logic: an empty bin should only win when current bin
    // would leave a bad residue relative to the next item.
    if bin_residual == bin_capacity {
        // Slight penalty so open bins with good fits win.
        score += 15.0;
        if next_item_size > 0 && bin_capacity - next_item_size >= item_size {
            score -= 5.0; // new bin can also host lookahead after this item
        }
    }

    // Progress-aware mean residual coupling: when mean residual is high,
    // prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * (mean_residual - cap * 0.5) * (1.0 - progress);

    // Penalize opening many bins late in the stream.
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize dead space: gaps too small for the minimum item size (1..100 range,
    // but small gaps < 12 are rarely reusable).
    if post_residual > 0 && post_residual < 12 {
        score += 45.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // Penalize leaving a gap just barely below the next item (wasted potential).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= next_item_size - 6 {
        score += 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible, which the dead-space
    // penalties above already encode).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; opening a new
    // bin should be rare. Penalize the new-bin candidate via its large post_residual
    // naturally, and add mild pressure against new bins when open count is low.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of a fresh bin, softened late in the stream.
        score += 30.0 - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    } else {
        // Mild preference for fuller bins (smaller residual) to consolidate.
        score += (bin_residual as f64) * 0.05;
        // Prefer bins below mean residual (more room) when few bins are open.
        if open_bins_count > 3 {
            score += (mean_residual - bin_residual as f64) * 0.10;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect match is highly desirable: subtract a strong bonus.
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit in the residual created here: penalize proportionally.
        let overshoot = (next_item_size - post_residual) as f64;
        score += 8.0 * (overshoot / bin_capacity as f64);
    }

    // Penalize unusable dead space (residual smaller than the smallest plausible item).
    if post_residual < 10 {
        score += 15.0;
    }

    // Reward tightening relative to the mean residual across open bins.
    if (post_residual as f64) < mean_residual {
        score -= 4.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    } else {
        score += 2.0 * ((post_residual as f64) - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when the item is huge relative to capacity
    // or no good fit exists; otherwise make opening a new bin expensive.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If the item nearly fills a fresh bin, opening a new one is fine.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 35.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild bonus for high fill ratio of the current bin.
    score -= 5.0 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively as stream progresses.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64 / cap) * (20.0 + 40.0 * t);

    // Penalize bins whose residual after placement becomes dead space
    // (too small for the smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if next item cannot fit, penalize lightly.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 12.0 * (1.0 - (next_item_size as f64 / post_residual as f64).min(1.0));
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state: many open bins with high mean residual -> prefer reusing
    // bins with residual near mean (balance), and discourage new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or mean
        // residual is generous; allow new bins early or when fit is bad.
        let mean_r = if mean_residual.is_finite() { mean_residual } else { 0.0 };
        let mut nb = 40.0 + 3.0 * open_bins_count as f64;
        if mean_r > item_size as f64 {
            nb += 15.0;
        }
        // If item is large relative to typical residual, opening fresh is ok.
        nb -= (item_size as f64 / cap) * 35.0;
        // Late in stream, prefer closing out existing bins.
        nb += 20.0 * t;
        // If next item is huge and this item is small, reserving a fresh bin is bad.
        if next_item_size > 70 && item_size < 40 {
            nb += 25.0;
        }
        score += nb;
    } else {
        // Mild preference for bins with residual close to mean (avoid
        // fragmenting the bin landscape).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Slight preference for emptier bins when few bins are open (exploration).
    if open_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: dead space matters more as stream progresses.
    let waste = post / cap;
    score += (post * post) / cap * (0.5 + 1.5 * progress * progress);

    // Tight fits rewarded (smooth coupling of item size and post residual).
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 12.0 * tight * tight * (item_size as f64 / cap);

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    }

    // Lookahead: favor leaving space usable by the next item.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let nx = next_item_size as f64 / cap;
        score -= 8.0 * nx * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - post / cap);
    }

    // Crowding: spread across many open bins mildly penalized.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Prefer bins with residual near the mean (balanced usage), smooth term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: penalize opening fresh bins unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 18.0 + 30.0 * (1.0 - progress) - 15.0 * (post / cap);
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: modulo classes on capacity C=100.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residual too small to fit any plausible item (1..=100).
    if post_residual < 10 {
        score += 60.0; // nearly unusable sliver
    }

    // Class-based residual utility: residuals in [10, 80] are reusable.
    if post_residual >= 10 && post_residual <= 80 {
        score -= 25.0;
        // Extra reward for residuals that are exact multiples of 10 (harmonic classes).
        if post_residual % 10 == 0 {
            score -= 15.0;
        }
        // Reward residuals that can host the next item (lookahead chaining).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
            // Bonus when next item fits with small waste again.
            let chain_waste = post_residual - next_item_size;
            if chain_waste < 10 {
                score -= 15.0;
            }
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Penalize leaving a residual the next item cannot use.
            score += 10.0;
        }
    } else if post_residual > 80 {
        // Very large residual means we placed a tiny item into a big bin: fine, keep flexible.
        score -= 10.0;
    }

    // Integer-division threshold on item_size: large items (>50, i.e. > C/2)
    // should preferentially go into bins they nearly fill.
    if item_size > bin_capacity / 2 {
        let fill = item_size as f64 / c;
        score -= fill * 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish but should lose to good fits, win over bad fits.
    if bin_residual == bin_capacity {
        // Slight penalty so it's only chosen when open bins score poorly.
        score += 5.0;
        // Early in the stream, opening bins is cheap (plenty of future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        // If open bins are mostly full (low mean residual), a new bin is attractive.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Mild pressure toward consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for tiny unusable gaps (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Reward perfect / near-perfect fits
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 3 {
        score -= 40.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Dead-space-aware penalty scaled by how "wasted" the gap is
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Lookahead: if next item fits into the post residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // gap can't host the next item: mild penalty proportional to gap size
        score += post_residual as f64 * 0.3;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over new bins
    if bin_residual != bin_capacity {
        score -= open_bins_count as f64 * 1.0;
    } else {
        // New-bin candidate: penalize opening a bin when decent fits exist
        score += 20.0 + mean_residual * 0.2;
        // But allow a new bin late in the stream if residuals are fragmented
        if mean_residual < 15.0 {
            score -= 30.0;
        }
    }

    // Prefer bins whose residual deviates favorably from mean (tighter than average)
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item also fits here: good chain, penalize leftover gap size
            let chain_gap = post_residual - next_item_size;
            score -= 200.0;
            score += chain_gap as f64 * 0.5;
        } else {
            // next item won't fit after this placement: penalize dead space
            let dead = next_item_size - post_residual;
            score += dead as f64 * 0.8;
        }
    }

    // Relative-to-mean residual adjustment: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty, reduced only if item is large
        score += 150.0;
        score -= item_size as f64 * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            // next item is large: opening fresh space may be wise
            score -= 100.0;
        }
    }

    // Late in stream: be more conservative with new bins, tighter fits matter
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in stream, be picky (penalize wasted space more);
    // late in stream, just fill bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let urgency = 1.0 - progress;
    score *= 0.6 + 0.8 * urgency;

    // Lookahead coupling: if the next item fits into post_residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64).sqrt();
        } else {
            // dead space for the known next item: penalize proportionally
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            score += 0.35 * gap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the average residual (good fits).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Slight preference for existing bins over opening new ones, scaled by how full they are.
    if bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    } else {
        // New bin candidate: penalize mildly, but less when many bins are open / early stream.
        score += 8.0 + 4.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - urgency);
    }

    // Reward near-perfect fills.
    if post_residual > 0 && post_residual <= 5 {
        score -= 10.0;
    }
    if post_residual == 0 {
        score -= 20.0;
    }

    // Penalize very large dead space relative to smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let base = pr as f64;
    let mut score = base;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits smoothly (quadratic in item fill fraction)
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill * (1.0 - progress);

    // Penalize dead space that next item cannot use, scaled by progress
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += 5.0 * (gap / cap) * (gap / cap) * (0.5 + progress);
    }

    // Last-chance bonus: only one bin fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress + 0.5);
    }

    // Mean residual coupling: prefer bins near the mean early, deviating bins later
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (0.3 + progress);

    // Slight preference to fill already-open bins as stream progresses
    score -= 3.0 * progress * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "useful" classes
    // (multiples of common small sizes) so leftover space stays reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 {
                bonus += 4.0;
            }
        }
        // Perfect fit: zero waste is ideal
        if pr == 0 {
            score -= 100.0;
        } else {
            score -= bonus;
        }
        // Penalize dead space below the minimum plausible item size (1..100 unknown,
        // but tiny fragments are hard to fill): residuals in (0, 10)
        if pr < 10 {
            score += 15.0;
        }
        // Harmonic fraction of capacity: residual as fraction of cap
        let frac = pr as f64 / cap;
        if (frac * 4.0).round() / 4.0 == frac {
            score -= 3.0; // quarter-capacity aligned residuals are attractive
        }
    } else {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize large leftovers slightly
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // New-bin candidate: prefer keeping item in an open bin unless this bin is
    // fresh-ish and current bins are crowded. Empty-bin call has bin_residual == cap.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (mean_residual / cap + 1.0);
        // base cost of a new bin
        score += 20.0 + 10.0 * progress + 2.0 * crowding;
        // if mean residual is large, open bins have room: penalize new bin more
        score += (mean_residual - 20.0).max(0.0) * 0.5;
        // but if the item is huge and mean residual small, new bin is fine
        if item_size as f64 > mean_residual {
            score -= 18.0;
        }
    }

    // Mild penalty when bin residual deviates strongly from mean (balance loads)
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: less leftover relative to item size is good.
    let item_f = item_size as f64;
    let post_f = post_residual as f64;
    score -= (item_f * item_f) / (post_f + 1.0) * 0.5;

    // Strict dead-space avoidance: small unusable gaps are penalized hard.
    let min_useful = 10u32.min(bin_residual); // smallest item that could ever fit
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0 + (min_useful - post_residual) as f64 * 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, encourage filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).powf(1.3) * (0.6 + 0.4 * progress) * 0.8;

    // Prefer bins with residual below mean (fill the emptiest-tightest bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item would fit in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space relative to the actual next item.
        score += (post_residual as f64).powf(1.2) * 0.5;
    }

    // New-bin candidate: make it attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by potential of a fresh bin
        // when existing residuals are small relative to the item.
        score = bin_capacity as f64 * 0.9
            - (mean_residual - item_f).max(0.0) * 2.0
            - (open_bins_count as f64) * 1.5
            - if fitting_bins_count <= 1 { 30.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits: post_residual near 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual < 10 {
        score -= 100.0;
    }

    // Dead-space penalty: residuals below the minimum item size (1) are impossible,
    // but small residuals (say < 10) are hard to fill; penalize proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the post residual,
    // this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // Next item can also go here: good, but less ideal than exact match.
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item won't fit after this placement; penalize wasting the chain,
            // scaled by how much slack is left unused.
            let waste = (post_residual as f64 - next_item_size as f64).abs();
            score += waste * 0.3;
        }
    }

    // Compare post_residual against mean residual: leaving this bin far below the mean
    // creates fragmentation; leaving it above mean keeps flexibility.
    if post_residual as f64 > mean_residual {
        score -= (post_residual as f64 - mean_residual) * 0.2;
    } else {
        score += (mean_residual - post_residual as f64) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current item is
    // large and no good chain exists. Penalize empty-bin choice mildly by default.
    if bin_residual == bin_capacity {
        // A new bin gives full flexibility but wastes the chance to consolidate.
        // Penalize unless the item is huge relative to capacity (poor fit anywhere).
        let large_item = item_size as f64 / bin_capacity as f64;
        if large_item > 0.7 {
            score -= 150.0; // big items start fresh bins more readily
        } else {
            score += 120.0;
        }
        // Late in the stream, consolidation matters more; penalize new bins less
        // early when few bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
        if open_bins_count == 0 {
            score -= 500.0; // must open a bin
        }
    }

    // Mild bonus for filling bins tightly relative to capacity.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 35.0 * tightness * tightness;

    // Penalize dead space: small unusable post-residuals that no typical item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item can still fit here; mild reward proportional to fill of post space.
            score -= 12.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving large unusable residue.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap.min(50.0);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Time horizon: late in the stream, avoid opening new bins; early, be more exploratory.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 40.0 + 60.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    }

    // Prefer filling bins that are already relatively full (small residual vs mean).
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64) / mean_residual;
        if rel < 1.0 {
            score -= 10.0 * (1.0 - rel);
        } else {
            score += 5.0 * (rel - 1.0).min(2.0);
        }
    }

    // Encourage consolidation when many bins are open.
    if open_bins_count > 4 {
        score -= 3.0 * (open_bins_count.min(20) as f64) * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = post_norm * (1.0 + progress * post_norm * (2.0 - progress));

    let mut score = poly * cap;

    // Reward tight fits more strongly later in the stream
    score -= (1.0 - post_norm) * (1.0 + 2.0 * progress) * 12.0;

    // Penalize dead space that cannot fit the next item (smooth interaction)
    let next_fit = if next_item_size > 0 {
        let nxt = next_item_size as f64;
        ((post - nxt) / cap).abs()
    } else {
        0.0
    };
    score += next_fit * (8.0 + 10.0 * progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - post_norm);
    }

    // Mild penalty when bin residual deviates from mean residual (smooth dispersion term)
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 4.0 * (1.0 + progress);

    // Slight preference to consolidate into fewer bins early
    score += open_bins_count as f64 * 0.05 * post_norm;

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual as u32 == bin_capacity && item_size > 0 {
        score += 10.0 - 6.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are
    // multiples of common small item sizes (perfect packing partners).
    let cap = bin_capacity as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else {
        let pr = post_residual;
        let mut harmony = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 { harmony += 8.0; }
        }
        score -= harmony;

        // Dead-space penalty for tiny unusable slivers
        if pr < 10 {
            score += 25.0;
        }

        // Lookahead: if the next item fits exactly in post_residual, big reward
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 40.0;
            } else if next_item_size <= pr {
                score -= (pr - next_item_size) as f64 * 0.3;
            } else {
                // next item cannot use this residual; penalize large residuals proportionally less
                score += (next_item_size - pr) as f64 * 0.15;
            }
        }
    }

    // Last-chance bin: strong discount to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Fraction-of-capacity coupling: prefer bins whose fill ratio is high
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill_ratio * 15.0;

    // Late in stream, tighten packing (favor existing bins over new ones)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when many bins open
        score += 20.0 + 40.0 * progress + (open_bins_count as f64).sqrt() * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin keeps full flexibility; slight discount early
            score -= 10.0 * (1.0 - progress);
        }
    } else {
        // reward using existing bins more aggressively over time
        score -= 10.0 * progress;
    }

    // Mean residual coupling: if this bin is far from the mean, small correction
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0; // tiny unusable slivers
    } else if post_residual == 0 {
        score -= 60.0; // perfect fill: strongly reward exact fit
    } else if post_residual <= 20 {
        score += 8.0; // moderately wasteful gap
    }

    // Reward bins whose residual is close to item_size (tight fit, not just large leftover math).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 25.0;

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless it enables a much better future fit.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Soften new-bin penalty if no open bin leaves room for the lookahead item.
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score -= 45.0;
        }
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reserve room for the lookahead item: big bonus for keeping the chain alive.
        score -= 20.0;
    }

    // Open-bin pressure: prefer compacting into few bins when residuals are already fragmented.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.7 * progress) * (mean_residual / bin_capacity as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize useless tiny slivers
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // dead space too small for any item (min size 1..100 => keep threshold small)
    }

    // 2-step lookahead: perfect match of next item into post_residual is highly desirable
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (post_residual as f64 - n).abs() < 1e-9 {
            score -= 40.0; // exact chain fit
        } else if post_residual >= next_item_size {
            // next item fits here later; reward proportionally to how well it fills
            let fill_after_next = (post_residual as u32 - next_item_size) as f64;
            score -= 20.0 * (1.0 - fill_after_next / bin_capacity as f64);
            if fill_after_next < 10.0 {
                score += 8.0; // but avoid leaving another unusable sliver
            }
        } else {
            // next item won't fit in post_residual: penalize by the shortfall
            score += 0.5 * (n - post_residual as f64).min(60.0);
        }
    }

    // Relative-to-mean-residual coupling: favor bins tighter than average
    score += 0.6 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep empty bin attractive only when current fits are poor
    if bin_residual == bin_capacity {
        // neutral-ish baseline; subtract slightly early, add late when consolidation matters
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 55.0 - 15.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 30.0; // oversized next item: fresh bin useful
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no open bin fits: must open
        }
    }

    // Mild preference to consolidate into fewer bins as stream progresses
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let cap = bin_capacity as f64;
    let fit_ratio = post_residual as f64 / cap;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that becomes unusable for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 20.0 + 0.15 * next_item_size as f64;
        } else {
            score += 6.0; // bin likely closes after this item anyway
        }
        // Chain fit: next item exactly fills remaining space
        if post_residual as u32 == next_item_size {
            score -= 30.0;
        }
    } else {
        // Last item: just minimize waste
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier, penalize mediocre fits.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: early in stream, be more willing to keep bins flexible;
    // later, exploit tight fits harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0 * (1.0 - fit_ratio);

    // Global state: many open bins with high mean residual -> prefer filling
    // existing bins rather than spreading.
    score -= 0.05 * mean_residual * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate handling: empty bin gets a mild penalty so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But late in the stream or with huge item, opening fresh is fine.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Prefer bins whose residual is close to item size (perfect packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * p2 * cap * 0.1;
    score += coupling;

    // Reward tight fits, more strongly later in the stream
    let fit = item_size as f64 / bin_residual as f64;
    score -= fit * (0.5 + 1.5 * p3) * item_size as f64;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 && post_residual > 0 {
        score += (next_item_size as f64 - pr) * (0.3 + 0.7 * progress);
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * p2;
    }

    // Mild penalty when bin diverges from mean residual
    score += 0.2 * (pr - mean_residual).abs() * (1.0 - progress);

    // Discourage opening new bins early; encourage consolidation late
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - p2) - 2.0 * p3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let octave = (frac * 8.0).floor() as i32; // 0..7 harmonic classes of leftover space

    // Reward small leftovers (tight fits), strongest when leftover lands in a "usable" class.
    score -= 12.0 * (1.0 - frac) * (1.0 - frac);

    // Modulo arithmetic: leftovers that are multiples of small item sizes (e.g. 10, 20, 25)
    // are more likely reusable by future items -> reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 20 == 0 { score -= 3.0; }
        // Penalize awkward leftovers in the "dead zone" (1..9 and 11..14 style gaps)
        if pr < 10 && pr > 0 { score += 8.0; }
    }

    // Harmonic class bonus table: leftovers near half-capacity are highly reusable.
    match octave {
        0 => score += 15.0,          // nearly full bin, tiny leftover: dead space
        1 => score += 2.0,
        2 => score -= 2.0,           // ~25-37% leftover: good for small items
        3 => score -= 5.0,           // ~37-50%: prime reusable zone
        4 => score -= 6.0,           // ~50-62%: excellent
        5 => score -= 4.0,
        6 => score -= 1.0,
        _ => {}                      // large leftover: it's just an empty-ish bin
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            score -= 5.0 * (1.0 - (pr - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here regardless; slight penalty for blocking
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 14.0;
    }

    // New-bin candidate handling: empty bins should only win when open bins fit badly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open a new bin early in the stream or when few bins are open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        score -= 1.5 * open_bins_count as f64;
        // If mean residual across open bins is large, prefer existing bins.
        score += 0.35 * mean_residual;
        // If the current item is large relative to capacity, a fresh bin is attractive.
        score -= 0.25 * item_size as f64;
        // If the next item is large too, fresh bin keeps flexibility.
        if next_item_size >= bin_capacity / 2 { score -= 8.0; }
    }

    // Mild preference for bins with residual close to the item (perfect-fit seeking),
    // modulated by how many bins could fit the item (scarcity increases urgency).
    let gap = (bin_residual as i64 - item_size as i64).unsigned_abs() as f64;
    score += 0.05 * gap * (fitting_bins_count as f64).sqrt();

    // Encourage consolidation when many bins are open: favor emptier bins to reduce bin count.
    if open_bins_count > 4 {
        score -= 0.1 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the minimum plausible item size (1)
    // but more meaningfully, gaps that can't fit the next item are wasteful.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Gap after placement cannot host the lookahead item: dead space.
            let waste_ratio = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 25.0 + 60.0 * waste_ratio;
        } else {
            // Gap can host next item: reward tight fit that still leaves utility.
            score -= 12.0 * (post_residual as f64 / bin_capacity as f64).sqrt();
        }
    }

    // Steep dead-zone penalty: residuals in [1, 9] are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }
    // Residuals in [10, 20] are marginal; mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open bins pressure: penalize creating new bins when many are open,
    // reward using existing bins to consolidate.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 2.5 * open_bins_count as f64;
    } else {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // since failing to use it forces opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; placing here evens out load.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.15 * (mean_residual - residual_f);
    } else {
        score += 0.10 * (residual_f - mean_residual);
    }

    // Early in the stream, be more willing to open bins (spread risk);
    // later, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if is_new_bin {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        // Perfect two-item fill is ideal
        if gap == 0.0 {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Dead space the next item cannot use
        score += 25.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Penalize residual far from mean residual (encourage balanced fills)
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin bonus: strongly prefer using a nearly-full fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening new bins when open bins fit well
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Late in the stream, tighten packing (avoid waste)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead space minimization)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize tiny unusable leftovers (< 10) heavily
    if post_residual < 10 {
        score += 25.0;
    } else {
        score -= 5.0 * (post_residual as f64 / 10.0).ln().max(0.0);
    }

    // Lookahead: reward bins whose leftover can host the next item exactly-ish
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + gap);
    }
    // Penalize if next item nearly exhausts but doesn't fit this bin's leftover
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Global congestion: many open bins with high mean residual -> prefer filling existing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let congestion = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    if congestion > 20.0 {
        score -= 10.0 * (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
    }

    // New-bin candidate logic: only attractive when current bin leaves bad residue
    if bin_residual == bin_capacity {
        // fresh bin: base cost, discounted early in stream or for big items
        let base = 55.0 - 20.0 * progress;
        let waste = (bin_capacity - item_size) as f64;
        score = base + waste * 0.3 - (item_size as f64 / 80.0) * 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mild preference for bins tighter than average
    score -= 8.0 * ((mean_residual - bin_residual as f64) / bin_capacity as f64);

    // Time horizon: late in stream, be conservative, avoid new bins
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    score -= 8.0 * norm_pr * (1.0 + prog2) * (1.0 + norm_pr * norm_pr);

    // Penalize dead space that grows with stream maturity
    score += 6.0 * norm_pr * norm_pr * (0.5 + progress);

    // Lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 3.0 * progress;
    }

    // Last-chance bin: strong reward to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 4.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this residual deviates from mean
    let dev = (pr - mean_residual).abs() / cap;
    score += 2.0 * dev * (open_bins_count as f64).sqrt() * (0.3 + progress);

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 10.0;
    }

    // Slight bias toward new-bin option when item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 1.5 * (item_size as f64 / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality via integer division
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Classify post_residual into harmonic bands (quarter-capacity classes)
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..4
    match class {
        0 => score -= 18.0,          // tiny residual: near-perfect fill
        1 => score -= 6.0,           // small residual: still usable
        2 => { /* mid: neutral */ }
        3 => score += 8.0,           // large residual wasted on this item
        _ => {}                       // empty-bin candidate
    }

    // Modular resonance: post_residual divisible by common item sizes is reusable
    if post_residual > 0 {
        for m in [10u32, 20, 25, 50].iter() {
            if post_residual % m == 0 {
                score -= 5.0;
                break;
            }
        }
        // Next item fits harmonically into post_residual
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
            // perfect harmonic match
            if post_residual % next_item_size == 0 {
                score -= 8.0;
            }
        } else if next_item_size > post_residual && next_item_size > 0 {
            // lookahead item cannot use this dead space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only on truly poor fits,
    // but scale with stream progression and open-bin pressure.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap - (cap - pr) * (0.6 + 0.4 * progress);
        if open_bins_count > 0 {
            score += 6.0;
        }
    }

    // Mean-residual coupling: prefer bins far from the mean when mean is small
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Exact fill bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Zero post_residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Post-residual that can't fit a typical future item (dead space zone).
    if post_residual > 0 && post_residual < next_item_size as f64 && next_item_size > 0 {
        score += 25.0;
    }
    // Reward residual that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
    } else {
        score -= 5.0 * open_bins_count as f64;
    }

    // Slight preference for bins tighter than the mean residual.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Late in the stream, tighten packing (avoid leftover gaps).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small post-residuals are good, but residuals too small
    // to ever fit future items (min size 1, but typically >=10) are wasted.
    let dead_threshold: f64 = 9.0;
    if (post_residual as f64) < dead_threshold {
        score += 40.0; // unusable sliver -> strong penalty
    }

    // 2-step lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect follow-up match
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.5; // good follow-up, decaying with slack
        } else {
            // next item won't fit here; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    } else {
        // Last item: prefer tightest fit overall
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are tighter;
    // favoring them preserves large residuals for large future items.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity and few bins are open.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins generally, discount when item is big or stream is crowded
        score += 30.0 - fill * 25.0 - progress * 10.0 - (open_bins_count as f64 * 0.5);
        // Never open a new bin for the last item
        if next_item_size == 0 {
            score += 100.0;
        }
    }

    // Mild preference to fill bins more completely as the stream progresses.
    score += (bin_residual as f64 / bin_capacity as f64) * (1.0 + progress_factor(step_index, total_items)) * 2.0;

    score
}

#[inline]
fn progress_factor(step_index: usize, total_items: usize) -> f64 {
    if total_items == 0 { 0.0 } else { step_index as f64 / total_items as f64 }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, penalize large leftover.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 18.0;

    // Penalize dead space that is too small to fit typical future items.
    if post_residual > 0 && post_residual < item_size.min(30) {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += (next_item_size - post_residual.min(next_item_size)) as f64 * 0.3;
        }
    }

    // New-bin candidate handling: mildly discourage opening a new bin unless
    // existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual - item_size as f64).max(0.0);
        score += 20.0 - pressure.min(20.0);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Global state: when many bins are open, prefer consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.15;
    score += mean_residual * 0.05 * progress;

    // Prefer bins whose residual is close to mean (keep residuals uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 1.5 * progress) - 0.8 * x * x * (1.0 - progress);

    // Reward tight fits (small post_residual), smoothly
    score -= (1.0 - x).powi(2) * 0.5;

    // Penalize dead space relative to mean residual, scaled by progress
    score += 0.3 * (pr - mean_residual) / cap * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 2.0;
    } else if fitting_bins_count > 1 {
        score += 0.1 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits smoothly in the post residual, reward it
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_gap = (x - nx).abs();
        score -= 0.6 * (1.0 - fit_gap) * (1.0 - x);
        // Penalize leaving residual just below next item size (dead corner)
        if x < nx && x > 0.0 {
            score += 0.8 * nx;
        }
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.02 * open_bins_count as f64 * progress;

    // Slight bias against opening a new bin early when others fit
    if bin_residual == bin_capacity {
        score += 1.2 * (1.0 - progress) + 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small residues are "dead space" classes.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Penalize dead-space classes: residues in (0, 10) are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Harmonic bucket penalty via integer division of post_residual.
    let bucket = post_residual / 10; // 0..10 classes
    score += match bucket {
        0 => 15.0,          // 0..9 : dead space
        1 => 2.0,           // 10..19: fits only tiny items
        2 => 0.0,           // 20..29
        3 => -1.0,
        4 => -2.0,
        5 => -3.0,
        6 => -3.5,
        7 => -4.0,
        8 => -4.0,
        9 => -3.0,
        _ => -2.0,
    };

    // Reward tight fits (exact or near-exact fills).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let nf = next_item_size as f64 / post.max(1.0);
            score -= 8.0 * nf;
        } else {
            // Next item cannot fit here; slight penalty if this bin was its only chance later.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base score for a fresh bin: keep it competitive but not dominant.
        score = 55.0 + frac * 20.0;
        // Open a new bin early in the stream to build a pool of bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If many bins are open and mean residual is high, discourage new bins.
        score += 0.5 * open_bins_count as f64;
        if mean_residual > 40.0 {
            score += 15.0;
        }
        // If next item is large, having a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mild normalization: prefer bins whose residual was already small relative to mean.
    if mean_residual > 0.0 {
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Lookahead: if the leftover can host the next item, favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If leftover cannot host the next item, penalize slightly (dead space risk).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 30.0 + open_bins_count as f64 * 5.0;
        // But if mean residual is tiny (all bins nearly full), a new bin is fine.
        if mean_residual < 15.0 {
            score -= 50.0;
        }
    } else {
        // Using an existing bin reduces open-bin pressure slightly.
        score -= open_bins_count as f64 * 0.5;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !new_bin_candidate {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward when the next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            // partial lookahead fit: reward proportional to how well next item uses leftover
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * use_ratio;
        } else {
            // next item cannot fit here; penalize dead space relative to next item size
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize creating tiny unusable slivers (dead space) relative to capacity
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins tighter than the mean residual (good packing), penalize loose ones
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Mild penalty for leaving a large residual when mean residual is small (fragmentation risk)
    if post_residual as f64 > mean_residual {
        score += 0.1 * (post_residual as f64 - mean_residual);
    }

    // Late in the stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    // Discourage opening a new bin when good fitting options exist
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = (step_index as f64) / ((total_items.max(1)) as f64);
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Tight-fit reward: the smaller the post_residual relative to what was there, the better the fill.
    if bin_residual > 0 {
        score -= 12.0 * (1.0 - post / (bin_residual as f64));
    }

    // Lookahead (k=2): reward bins whose leftover can host the next item, especially early/mid stream.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 18.0 * (1.0 - 0.5 * t);
        } else {
            // leftover that can't host next item is a dead-space risk
            score += 6.0 * (1.0 - t);
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a bin is expensive; allow it only when
    // the resulting residual is a "useful" size (small, likely to be filled later),
    // and increasingly so as the stream progresses (less future to amortize waste).
    if is_new_bin {
        let usefulness = 1.0 - (post / cap); // tight new-bin fills are good
        score += 35.0
            + 0.6 * open_bins_count as f64
            - 30.0 * usefulness * (0.4 + 0.6 * t);
    }

    // Penalize creating tiny unusable dead space (< 10) that likely never fills.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Mild global-state coupling: prefer bins whose residual is below the mean
    // (closing the gap toward balanced, fuller bins).
    score += 0.08 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let p = progress;
    let poly = p * p - p + 0.5; // smooth bell-ish weight in [0.25, 0.5]
    score += 12.0 * poly * norm_post * norm_post;

    // Reward tight fits more strongly later in the stream
    score -= (1.0 - norm_post) * (1.0 + 2.0 * p) * 6.0;

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dead = norm_post - (mean_residual / bin_capacity as f64);
    score += 5.0 * dead * dead;

    // Last-chance bonus (smooth, not piecewise): exp decay of fitting bins
    let scarcity = 1.0 / (1.0 + (fitting_bins_count.saturating_sub(1)) as f64);
    score -= 8.0 * scarcity;

    // Lookahead coupling: reward leaving room for next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / bin_capacity as f64;
        let gap = norm_post - nxt;
        let s = gap / (1.0 + gap.abs());
        score -= 4.0 * s;
    } else {
        score -= 3.0 * norm_post; // last item: prefer fullest packing
    }

    // Mild penalty for proliferating open bins, scaled by progress
    score += 0.05 * open_bins_count as f64 * (0.5 + p);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
