    let residue_class = (post_residual % 10) as f64;
    // Classes with residue 0 are "perfect" harmonic fits; penalize non-zero residues
    score += residue_class * 1.5;

    // Integer-division thresholds: post_residual buckets of 20
    let bucket = post_residual / 20;
    score += bucket as f64 * 3.0;

    // Strong reward for near-perfect fits (post_residual very small)
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
