            } else {
                score += (1.0 - fill) * 8.0;
            }
        } else {
            // next item cannot use leftover: penalize dead space proportionally
            score += 10.0;
        }
    } else {
        // last item: minimize leftover
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral-ish baseline, opened only when open bins are bad
    if bin_residual == bin_capacity {
        score = 55.0 + (post_residual as f64) * 0.1;
        // early in stream, prefer opening bins more freely
        if step_index * 4 < total_items {
            score -= 10.0;
        }
        // if only one bin fits and it's bad, opening new bin is attractive
        if fitting_bins_count == 1 {
            score -= 8.0;
        }
    }

    // Discourage scattering across many bins when mean residual is high
    if (post_residual as f64) > mean_residual + 10.0 && open_bins_count > 2 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
