    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * -0.5;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small unusable residuals (dead space), scaled by capacity.
        if post_residual < 10 {
            score += 40.0 * (10 - post_residual) as f64;
        }
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // Next item can also fit here: bonus proportional to how well it fits.
            let next_leftover = post_residual - next_item_size;
            score -= 120.0 * (next_leftover as f64 / bin_capacity as f64);
            if next_leftover == 0 {
                score -= 200.0;
            }
        } else {
            // Next item cannot fit after this placement: penalize tight bins.
            score += 50.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing bins,
    // but allow opening a new bin when existing residuals are very tight.
    if bin_residual == bin_capacity {
        score += 60.0;
        // If open bins are nearly full on average, opening a new bin is fine.
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 80.0;
        }
        // Lookahead: a fresh bin is attractive if next item is large.
        if next_item_size >= 50 {
            score -= 40.0;
        }
    }

    // Slight preference for fuller bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * (1.0 + 10.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on post-residual (dead space).
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Lookahead: reward if the next item can fit into post_residual (chaining),
    // penalize if post_residual is a dead sliver the next item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if next_item_size <= post_residual {
            // Chain bonus proportional to how well next item fills leftover.
            let fill = nxt / post;
            score -= 30.0 * (1.0 - (fill - 1.0).abs());
        } else {
            // Dead space: leftover too small for the next item.
            let waste = post / nxt;
            score += 45.0 * (1.0 - waste.min(1.0));
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise this item forces a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // New-bin candidate handling: only open a new bin when open bins are
    // fragmented (high mean residual spread) or the fit is terrible.
    if bin_residual == bin_capacity && item_size > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // Prefer new bin if item is small (leaves room) and existing bins are messy.
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        let new_bin_bonus = 90.0 + 40.0 * progress - 60.0 * fit_quality + 50.0 * fragmentation;
        score += new_bin_bonus;
    }

    // Mild bias: prefer fuller bins (lower residual) globally.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late-stream consolidation: as stream ends, discourage leaving many slivers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 25.0 * progress;

    // Prefer bins that keep residual in "usable" ranges (>= next typical size ~ mid 40s).
    if post_residual > 0 && post_residual < 40 && next_item_size > post_residual {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: mildly reward tight fits (quadratic in normalized fill).
    // Late stream: strongly penalize wasted residual (cubic growth).
    let fill_norm = 1.0 - pr / cap;
    let coupling = fill_norm * fill_norm * (1.0 + 2.0 * progress) - fill_norm * fill_norm * fill_norm * (4.0 * progress);
    score -= 12.0 * coupling;

    // Smooth cubic penalty on dead space that grows with progress.
    let dead = pr / cap;
    score += 20.0 * dead * dead * dead * (0.5 + progress);

    // Penalize residual that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 15.0 * gap * gap * (1.0 + progress);
        // Reward residual that exactly or nearly accommodates the lookahead item.
        let slack = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 8.0 * (1.0 - slack) * (1.0 - slack) * (1.0 - progress) * (pr >= next_item_size as f64) as f64;
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - dead * dead);
    }

    // Mild pressure toward consolidating bins when many are open.
    score += 0.05 * open_bins_count as f64 * dead;

    // Deviation of this bin's residual from mean residual (smooth quadratic).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo 10 (capacity 100 -> 10 classes).
    let harm = post_residual % 10;
    // Penalize residuals that are "dead" (too small to ever hold a min item of 1..100 scale,
    // assume min item ~ 10 in classic streams, but adapt: dead if post_residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // dead space penalty
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // reward proportional to how well next item divides the residual
            let frac = post_residual as f64 / next_item_size as f64;
            if frac.fract() == 0.0 && frac >= 2.0 {
                score -= 25.0; // residual is an exact multiple of next item
            }
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item cannot use this bin's leftover; penalize large leftovers
            score += 0.15 * post_residual as f64;
        }
    }

    // Integer-division threshold on post_residual: classify into quarters of capacity.
    let q = post_residual / 25; // 0..4
    match q {
        0 => score += 8.0,          // tiny leftover: mostly dead
        1 => score += 2.0,          // quarter left
        2 => score -= 0.0,          // half: neutral
        3 => score -= 6.0,          // three quarters: very usable
        _ => score -= 10.0,         // nearly full bin remains
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: discourage unless current bin fit is poor.
    if bin_residual == bin_capacity {
        // open new bin only if it beats leaving lots of dead space elsewhere
        score += 30.0 + mean_residual * 0.2;
        if post_residual == bin_capacity as u32 && next_item_size > 0 && next_item_size >= item_size {
            score -= 55.0; // big item with a bigger next item: fresh bin is good
        }
    }

    // Modulo harmony between item and residual: reward when item divides capacity classes.
    if bin_residual % 10 == 0 && item_size % 10 == 0 {
        score -= 5.0;
    }

    // Late in stream: consolidate, prefer tightest fit.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Prefer bins below mean residual (keeps spread balanced) mildly.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest item (1..5) are wasted.
    if post_residual > 0 && post_residual < 5 {
        score += 50.0;
    } else if post_residual >= 5 && post_residual < 10 {
        score += 20.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits generally: prefer bins where item fills a large fraction of residual.
    if bin_residual > 0 {
        score -= 10.0 * (item_size as f64 / bin_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // (avoiding opening a new bin), scaled by open bin pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + (open_bins_count as f64) * 2.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another one.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate handling: only attractive when the item fits poorly anywhere
    // (i.e., would leave big dead space) or no bins fit. Penalize default new bin,
    // but relax penalty if item is large relative to capacity and mean residual is small.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 15.0 * large_item - 10.0 * (1.0 - pressure);
        // Lookahead: if next item is small, a fresh bin is more valuable.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Late in the stream, prioritize closing bins out (use existing space).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.05;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that likely cannot be reused.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { post_residual as f64 };
        score += 0.35 * dead * (1.0 - fit_ratio);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            score += 4.0;
        }
    }

    // Global pressure: many open bins with slack -> prefer consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = mean_residual / bin_capacity as f64;
    score += 6.0 * pressure * (1.0 - progress);

    // Penalize opening a new bin unless it is genuinely the best option:
    // new-bin candidate gets a base penalty, reduced when no open bin fits well.
    if bin_residual == bin_capacity {
        let mut penalty = 40.0;
        if fitting_bins_count == 0 {
            penalty = -10.0;
        } else if fitting_bins_count == 1 {
            penalty = 5.0;
        }
        // Late in the stream, new bins are cheaper to justify for big items.
        penalty -= 10.0 * progress * (item_size as f64 / 100.0);
        score += penalty;
    }

    // Mild preference for bins with residual close to item size (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: tight fits (small post_residual) get low scores.
    let mut score = pr;

    // Non-linear reward for tight fit: quadratic coupling of post_residual with item size.
    let tightness = 1.0 - (pr / cap); // 1.0 = perfect fit
    score -= 12.0 * tightness * tightness * (it / cap);

    // Smooth stream-progress coupling: early on, prefer filling existing bins aggressively;
    // later, dead space matters more, so penalize large residuals super-linearly.
    let prog_term = progress * progress;
    score += prog_term * (pr * pr) / cap;

    // Penalize wasted residual relative to mean residual across open bins (smooth coupling).
    score += 0.35 * (pr - mean_residual).abs() / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving residual that can still fit the next item (smooth gate).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = ((pr - nx).max(0.0) / cap).powf(2.0);
        score -= 8.0 * (1.0 - fits_next) * (nx / cap);
    } else {
        // Last item: strongly prefer zero residual.
        score += 0.5 * pr;
    }

    // New-bin candidate (residual == capacity): penalize unless the item is large,
    // i.e. only open a new bin when post_residual would be small (big item, tight start).
    if bin_residual == bin_capacity {
        let item_frac = it / cap;
        score += 30.0 * (1.0 - item_frac) * (1.0 - item_frac);
        score -= 15.0 * item_frac * item_frac;
    }

    // Mild crowding effect: many open bins -> favor consolidation into existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 0.8 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual buckets via integer division.
    // Classes: 0 (perfect fit), 1..=9 (small dead space), 10..=24 (medium),
    // 25..=49 (large), >=50 (half-empty bin).
    let class = post_residual / 10;
    let class_penalty = match class {
        0 => -40.0,                       // perfect fit: strong reward
        1..=2 => -10.0,                   // tight fit: mild reward
        3..=4 => 5.0,                     // moderate dead space
        5..=7 => 20.0,                    // poor fit
        _ => 35.0,                        // half-empty: very poor
    };
    score += class_penalty;

    // Fine-grained dead-space shaping: penalize residuals that are hard to fill
    // (small odd remainders below typical minimum item size 10 are useless).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space smaller than any item
    }

    // Lookahead coupling: reward if next item fits into post_residual,
    // penalize if next item would need a new bin anyway.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: reward proportionally to how snugly
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 25.0; // chain perfect fit
            } else {
                score -= 8.0;
            }
        } else {
            // next item won't fit after this placement
            score += 6.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // elsewhere is bad. Give the empty bin a moderate baseline penalty.
    if bin_residual == bin_capacity {
        score += 45.0;
        // but if stream is early, allow more bin openings (exploration)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is far below the mean (they are the "odd ones out"
    // and should be closed out / filled up).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Mild pressure to fill already-open bins when many are open.
    score += 0.5 * open_bins_count as f64;

    // Prefer placing larger items into tighter bins (best-fit flavor).
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium dead space (10..=20) is partially unusable; moderate penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }
    // Perfect or near-perfect fills are rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (next_item_size as f64) * 0.2;
    }
    // If next item does NOT fit post-residual, penalize slightly (dead space for future).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 12.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: discourage spreading across many open bins when residuals are large.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins are crowded or item is huge.
        let crowded = (mean_residual / bin_capacity as f64) < 0.35;
        let big_item = item_size > 70;
        if crowded || big_item {
            score -= 20.0;
        } else {
            score += 30.0;
        }
    } else {
        score += (open_bins_count as f64) * 1.5;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.1;

    // Progress-based nudge: later in the stream, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: big bonus; near match: scaled bonus.
        if diff == 0.0 {
            score -= 60.0;
        } else {
            score -= 25.0 * (-diff / 20.0).exp();
        }
        // Penalize leaving a residual that can't fit the next item (dead space).
        if (post_residual as i64) < next_item_size as i64 {
            score += 15.0;
        }
    } else {
        // Last item: simply prefer tightest fit.
        score -= 10.0;
    }

    // Penalize deviation from mean residual (avoid fragmenting many bins).
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless post_residual is huge (i.e., item tiny)
    // and no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 8.0;
        if next_item_size > 0 && post_residual as i64 >= next_item_size as i64 {
            score -= 5.0;
        }
    }

    // Mild preference for keeping bins count low: when many bins open, prefer filling existing.
    score += (open_bins_count as f64) * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }
    if post_residual == 0 {
        score -= 6.0; // perfect fill
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // When many bins fit, mild penalty to avoid spreading items too thin.
        score += 0.4 * (fitting_bins_count.saturating_sub(1)) as f64;
    }

    // Lookahead coupling: if next item fits exactly into post residual, big reward.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 20.0;
        } else if (post_residual as u32) >= next_item_size {
            score -= 3.0;
        } else {
            // next item won't fit here; penalize leaving awkward gap unless gap is large
            score += 2.0;
        }
    }

    // New-bin candidate handling: empty bin is a fallback; make it slightly costly
    // unless the item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 6.0 * (1.0 - progress);
        if item_size > bin_capacity / 2 {
            score -= 4.0;
        }
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Global state: many open bins with high mean residual -> encourage consolidation.
    let consolidation = mean_residual / bin_capacity as f64;
    score += 3.0 * consolidation * (open_bins_count as f64).sqrt();

    // Prefer bins whose residual is close to mean (balanced packing) late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 2.0 * dev / bin_capacity as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual

    // Base: prefer tight fits (low post_residual), with mild non-linear penalty
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in stream, tolerate larger residuals (explore); later, penalize heavily
    let progress_coupling = (1.0 - progress) * (x * x) * cap * 0.5
        + progress * (x * x * x) * cap * 1.5;
    score += progress_coupling;

    // Dead-space penalty: residuals too small to fit typical items are wasted
    let dead_threshold = 0.2 * cap;
    if post < dead_threshold {
        let d = (dead_threshold - post) / dead_threshold;
        score += 15.0 * d * d;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // slight penalty when many options exist, scaled by fit quality
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0) * (1.0 - x);
    }

    // Lookahead: reward if next item can use the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            let slack = (post - nx) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            score += 5.0 * (nx - post) / cap;
        }
    }

    // Mean residual alignment: prefer bins near the mean residual (keeps pool balanced)
    let dev = (post - mean_residual).abs() / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate handling: opening a new bin is attractive early or when
    // the current bin's post residual would be very small (dead space)
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let new_bin_score = cap * 0.85
            - 20.0 * (1.0 - progress)
            + 5.0 * open_pressure.min(10.0);
        return new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residual values that are
    // "friendly" multiples/divisors of common item sizes (modular structure).
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else {
        // Class A: post_residual divisible by small harmonics (10, 20, 25, 50)
        // => likely to be filled by future items exactly.
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 8.0; }

        // Class B: post_residual in a "dead zone" (small unusable slivers)
        // penalize heavily: 1..=9 cannot hold min-size items.
        if pr < 10 {
            score += 60.0;
        } else if pr <= 15 {
            score += 15.0;
        }

        // Integer division threshold: post_residual bucketed by capacity fraction.
        let frac = pr as f64 / cap; // fraction of bin still empty
        // Reward leaving exactly half or quarter bins (harmonic fractions).
        if (frac - 0.5).abs() < 0.001 { score -= 10.0; }
        if (frac - 0.25).abs() < 0.001 { score -= 5.0; }

        // Coupling with next item: if next item fits exactly into post_residual,
        // big reward (perfect lookahead fit).
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 200.0;
            } else if next_item_size <= pr {
                // Next item fits: reward proportional to how snug it is.
                let snug = 1.0 - ((pr - next_item_size) as f64) / cap;
                score -= 20.0 * snug;
                // Harmonic: next item leaves a friendly residual too.
                let pr2 = pr - next_item_size;
                if pr2 == 0 { score -= 100.0; }
                else if pr2 % 10 == 0 { score -= 8.0; }
                else if pr2 < 10 { score += 25.0; }
            } else {
                // Next item cannot fit here: mild penalty if this bin was the
                // only fitting one (we'd strand the next item's placement).
                if fitting_bins_count == 1 { score += 10.0; }
            }
        }

        // Last-chance bin: strongly prefer using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // If many bins fit the item, prefer the tightest (score already tracks
        // post_residual, but add mild diversity control via mean_residual).
        if (mean_residual - pr as f64).abs() < 1.0 {
            score -= 3.0;
        }
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so that
    // it only wins when open bins score poorly (dead-space penalties).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows slightly as stream progresses
        // and with number of open bins (encourage consolidation early).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 35.0 + 40.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // If lookahead item is huge and current item is small, opening fresh
        // may still be reasonable: slight discount.
        if next_item_size >= 60 && item_size <= 20 { score -= 10.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are useless.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize tight fits that leave less than next item needs (lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward leaving exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Last-chance bin: prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: baseline cost, cheaper only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
        // Opening fresh is attractive when item is large and residuals are fragmented.
        if item_size > 50 && mean_residual < item_size as f64 {
            score -= 30.0;
        }
    }

    // Prefer bins whose residual is close to item (efficient packing).
    score -= (bin_residual as f64 - item_size as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= (post_residual as f64);
        if next_fits {
            let fill_ratio = (next_item_size as f64) / (bin_capacity as f64);
            let exact = if post_residual == next_item_size { 1.0 } else { 0.0 };
            score -= 25.0 * exact + 12.0 * fill_ratio;
        } else {
            // Next item won't fit: penalize leaving post_residual just below next_item_size (dead space).
            let gap = (next_item_size as f64) - (post_residual as f64);
            if gap < 20.0 {
                score += 18.0 * (1.0 - gap / 20.0);
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.6 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening a new bin when many bins already fit the item.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (fitting_bins_count as f64);
        // But early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 12.0 * (1.0 - progress);
    }

    // Slight penalty for large item relative to residual (waste avoidance).
    score += 0.1 * (item_size as f64) / (bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual) with a non-linear term.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tight * tight;

    // Penalize dead space that cannot be filled by the lookahead item.
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += 12.0 * (1.0 - (post_residual as f64) / nxt.max(1.0));
        } else {
            // Reward bins whose leftover can host the next item.
            score -= 6.0 * ((post_residual as f64) - nxt) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin mildly,
    // but allow it when all open bins would leave large unusable gaps.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (mean_residual - item_size as f64).max(0.0) / cap;
        score += 20.0 - 18.0 * waste - 10.0 * progress;
    }

    // Slight preference for bins with residual below the mean (compact usage).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev;

    // Penalize very small unusable slivers more as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with non-linear shaping
    let mut score = 100.0 * x * x + 30.0 * x;

    // Polynomial coupling of post residual with stream progress:
    // early on, tolerate larger leftovers (keep bins flexible);
    // later, punish wasted space more aggressively.
    score += (1.0 - progress) * 60.0 * x * (1.0 - x);
    score -= progress * 40.0 * x * x;

    // Reward tight fits (small post residual) more as stream advances
    score -= progress * 25.0 * (1.0 - x) * (1.0 - x);

    // Penalize bins deviating from mean residual (fragmentation control)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits into the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 15.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // Slight preference for consolidating into fewer bins
    score += 0.5 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" class (large enough for typical small items) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class 1: post_residual == 0 -> perfect fit, strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Class 2: post_residual divisible into nice fractions of capacity
    // (0, 25, 50, 75) are classic "harmonic" leftovers; reward closeness.
    let quarter = bin_capacity / 4;
    let mod_q = post_residual % quarter.max(1);
    if mod_q == 0 && post_residual > 0 {
        score -= 12.0;
    } else {
        // penalize awkward remainders (dead space)
        score += (mod_q as f64) * 0.15;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or nearly: reward tight lookahead fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0) * 0.5;
        } else {
            // next item won't fit: leftover becomes dead space
            let waste = (next_item_size - post_residual) as f64;
            score += waste.min(40.0) * 0.6;
        }
    }

    // Last-chance bin: only fitting bin -> strong preference to use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer filling already-open bins vs opening new ones, more so late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 8.0 + 10.0 * progress;
    } else {
        // new-bin candidate: only attractive if current bins are congested
        score += (open_bins_count as f64).min(10.0) * 2.0;
        score -= mean_residual.min(cap) * 0.05;
    }

    // Penalize creating tiny unusable slivers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Mild preference for tighter bins (smaller residual before placement).
    score += (bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Reward tight fits (small waste relative to item size).
    if item_size > 0 {
        score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    score += (open_bins_count as f64) * 2.0;

    // New-bin candidate handling: default moderately high; becomes attractive
    // only if the item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        score += 80.0;
        if item_size >= 60 && fitting_bins_count == 0 {
            score -= 120.0;
        }
    }

    // Lookahead: if next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Late in the stream, tighten up: prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when next item matches post residual exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain: next item exactly fills the leftover space.
            if slack == 0.0 {
                score -= 40.0;
            } else {
                // Penalize proportionally to slack left after the chained placement.
                score += slack * 0.6;
            }
        } else {
            // Next item cannot fit here; penalize leftover that becomes dead space,
            // scaled by how close the miss is (near-misses are worse).
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.4 + 8.0;
        }

        // Double chain check: could next item leave room for a small follow-up?
        if post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next >= 10 && after_next <= 20 {
                score -= 6.0; // leaves a useful small slot
            } else if after_next < 10 {
                score += 4.0; // tiny dead space
            }
        }
    } else {
        // Last item: pure tightness.
        score += 10.0;
    }

    // Compare post residual relative to mean residual of open bins.
    // Placing into a bin with below-average residual (already tight) is cheaper.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes capacity unless the
    // current item is large or open bins are all poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // If item is large (fills new bin well), opening is attractive.
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // If many bins are open and mean residual is small, prefer existing bins.
        if open_bins_count > 2 && mean_residual < item_size as f64 * 1.5 {
            score += 10.0;
        }
        // Late in the stream, avoid opening new bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 12.0;
        }
    }

    // Slight preference for bins with less residual overall (fill fuller bins first).
    score += bin_residual as f64 * 0.05;

    // Mild open-bins pressure: with many open bins, consolidate.
    if open_bins_count > 5 {
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits relative to capacity.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 30.0;

    // Penalize dead space relative to the smallest plausible future item (1).
    // Small post-residual is good; scale penalty quadratically for large residuals.
    let pr = post_residual as f64;
    score += (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * 40.0;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 80.0;
        } else {
            // Next item won't fit here; penalize proportionally to wasted gap.
            score += (next_item_size as f64 - pr) * 0.5;
        }
    } else {
        // Last item: prefer the very tightest bin.
        score -= 200.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large and no open bin offers a good fit.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 60.0;
        // More open bins -> higher cost of adding another.
        score += open_bins_count as f64 * 2.0;
        // Early in the stream, a fresh bin is more acceptable (future flexibility).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 50.0;
        // If item nearly fills a fresh bin, new bin is fine.
        score -= tightness * 40.0;
    }

    // Compare against mean residual: bins far below mean residual (already tight)
    // are precious; penalize dumping into them wastefully.
    if mean_residual > 0.0 && !is_new_bin {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 1.0 {
            score += (1.0 - rel) * 25.0;
        } else {
            score -= (rel - 1.0).min(2.0) * 10.0;
        }
    }

    // Mild preference for keeping many open bins useful: spread across bins
    // when there are few fitting options left globally.
    if fitting_bins_count <= 2 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: reward tight packing (small post residual)
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress;
    let coupling = 1.0 + t * (1.0 - t) * 4.0; // peaks mid-stream, smooth
    score *= coupling;

    // Penalize dead space more as stream progresses (fewer chances to fill it)
    score += norm_pr * norm_pr * cap * t * 0.8;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 6.0 * t;
    }

    // Prefer bins with residual close to mean (balance) via smooth quadratic term
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 10.0;

    // Lookahead: reward if next item fits in post residual (smooth sigmoid-like)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let fit_quality = (ns / (pr + 1.0)) as f64;
            score -= 8.0 * fit_quality * (1.0 - fit_quality) * 4.0;
        } else {
            score += 2.0 * (ns - pr) / cap * 10.0;
        }
    }

    // Slight penalty for many open bins to encourage consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible into nice
    // fractions of capacity are more reusable, so reward them (subtract).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let half = cap / 2.0;
    let third = cap / 3.0;
    let quarter = cap / 4.0;

    let class_bonus = if post_residual == 0 {
        -30.0 // perfect fill
    } else if (post_residual as f64 - half).abs() < 0.5 {
        -12.0
    } else if (pr - third).abs() < 1.0 {
        -8.0
    } else if (pr - quarter).abs() < 1.0 {
        -5.0
    } else if post_residual % 10 == 0 {
        -3.0
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division threshold on post_residual: tiny dead space is bad.
    if post_residual > 0 && post_residual <= 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item exactly fits the post-residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 10.0 - (leftover as f64) * 0.1;
        } else {
            // next item won't fit here; mild penalty scaled by overshoot
            score += ((next_item_size - post_residual) as f64).min(30.0) * 0.2;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 20.0 + waste * 0.5;
        // Late in the stream, prefer reusing bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // If few bins fit the item, new bin becomes more acceptable.
        score -= (fitting_bins_count as f64) * 3.0;
    }

    // Prefer tighter bins: compare residual to mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Reward bins that are already quite full.
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= fill * 10.0;

    // Modulo-class penalty: odd awkward residuals (not multiples of 5) get
    // a small penalty scaled by how close to half-capacity they are.
    if post_residual % 5 != 0 && post_residual > 0 {
        score += 2.0 * (1.0 - (pr - half).abs() / half);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize moderately small gaps that are unlikely to fit typical items.
    if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit after this placement, mildly penalize.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bins pressure: penalize placements into bins when many bins are open,
    // encouraging consolidation unless the fit is excellent.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += pressure * (1.0 - 0.5 * progress);

    // New-bin candidate: reserve it for cases where no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If this is the only fitting option (i.e., no open bin fits), opening is fine.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
        // Late in the stream, avoid spreading into new bins.
        score += 20.0 * progress;
    }

    // Slight preference for bins below mean residual (tighter bins used first).
    if (bin_residual as f64) < mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), but weight by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let gap = post_residual as f64 - next_item_size as f64;
        // Perfect chain (post_residual == next_item_size) is highly desirable.
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize dead space proportional to post_residual.
        score += 0.15 * post_residual as f64;
    }

    // Relative-to-mean residual coupling: placing into a bin with residual below mean
    // consolidates space (good); above mean spreads space (bad).
    score += 0.3 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate: make it attractive only when current fit is very loose
    // (post_residual small-ish items leaving large unusable gaps) and stream is early.
    if bin_residual == bin_capacity {
        let loose = post_residual as f64; // item_size when new bin
        let tightness = 1.0 - (loose / bin_capacity as f64);
        // Penalize new bin by default; discount when item is large (tight new bin)
        // and few bins are open.
        score = 30.0 - 20.0 * tightness - 0.05 * open_bins_count as f64 - 5.0 * progress;
        // If next item is small enough to also chain into a fresh bin, soften penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 6.0;
        }
    }

    // Small penalty for opening bins when many are already open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) non-linearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 6.0 * tightness * tightness * (item_size as f64) / 100.0;

    // Penalize dead space: post_residual too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 5.0 + 0.05 * next_item_size as f64;
        } else {
            // penalize leaving residual that next item almost fits into
            let gap = next_item_size as f64 - post_residual as f64;
            if gap > 0.0 && gap < 10.0 {
                score += 6.0;
            }
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bin mildly; stronger when many bins already open.
        score += 12.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);
        // But if mean residual is low (open bins nearly full), new bin is fine.
        score -= (mean_residual / cap) * 10.0;
    }

    // Time-horizon modulation: early on, be greedy for tight fits; late, conserve bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0 * (bin_residual as f64 - post_residual as f64);

    // Slight preference for bins with above-mean residual when item is large.
    if item_size >= 50 {
        score += 0.02 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual (tight fit), smoothed non-linearly
    let mut score = 10.0 * (x * x + 0.5 * x * x * x);

    // Stream progress coupling: later in the stream, tolerate larger residuals less
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Dead-space penalty: residual too small to ever fit another typical item
    let min_item = 1.0;
    let deadness = ((min_item - pr).max(0.0)) / cap;
    score += 25.0 * deadness * deadness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Lookahead: if next item fits exactly in post residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            score -= 6.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        } else {
            score += 3.0 * (gap / cap);
        }
    }

    // Mild preference to keep mean residual balanced (spread load)
    score += 0.05 * (mean_residual - pr).abs();

    // Slight penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 1.0 + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which quarter of capacity the leftover lives in.
    let quarter = bin_capacity / 4;
    let post_class = post_residual / quarter; // 0..=4
    match post_class {
        0 => score -= 30.0, // near-perfect fit
        1 => score -= 10.0, // small leftover
        2 => score += 5.0,  // mid leftover, still usable
        3 => score += 15.0, // large dead space risk
        _ => {}             // essentially empty
    }

    // Lookahead: does the next item fit into the leftover?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // leftover remains useful -> reward proportionally to how well next item nests
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 + slack * 0.15;
            // exact harmonic nesting (next item fills leftover to a class boundary)
            if (post_residual - next_item_size) % quarter == 0 {
                score -= 8.0;
            }
        } else {
            // leftover becomes dead space for the next item -> penalize
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        // base penalty so we prefer reusing bins with decent fits
        score += 60.0;
        // but if existing bins would leave awful leftovers, new bin becomes attractive:
        // compare post_residual here (capacity - item) vs mean residual of open bins
        if open_bins_count > 0 {
            let mean_post = mean_residual - item_size as f64;
            if mean_post < 0.0 || mean_post > (bin_capacity as f64) * 0.6 {
                score -= 55.0;
            }
        }
        // early stream: opening bins is cheap, allow it more readily
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.25 {
            score -= 15.0;
        }
    }

    // Mild preference for fuller bins when many bins are open (consolidation pressure)
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Perfect lookahead fit: this bin absorbs the next item exactly too.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid
    // abandoning it unless the fit is genuinely tight.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bonus = 20.0 + 25.0 * (1.0 - progress) + 0.15 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if the current fit wastes space.
        score -= new_bin_bonus;
        if post_residual as f64 > mean_residual {
            score += (post_residual as f64 - mean_residual) * 0.5;
        }
    } else {
        // Placing into an existing bin is mildly favored as stream matures.
        score -= 3.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly or well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // gap between post_residual and next item size = future dead space
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - 0.5 * slack;
            if post_residual == next_item_size {
                score -= 500.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to how much space is wasted
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize small unusable residuals (dead space) non-linearly
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Prefer bins tighter than the mean residual (compact bins first)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when few bins fit or item is huge
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 400.0 - 500.0 * pressure - 200.0 * big_item;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 100.0; // fresh bin guarantees next-item fit
        }
    }

    // Early in stream: keep bins open and consolidated; late: be flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 50.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: small post_residual is already the base term.

    // Penalize dead space relative to bin capacity (non-linear).
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += dead_frac * dead_frac * 40.0;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + (next_item_size as f64 / 20.0);
        } else {
            // Waste that cannot host next item is worse, especially if small.
            score += (post_residual as f64).min(20.0) * 0.8;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // When many bins fit the item, discourage fragmenting a large-residual bin.
    if fitting_bins_count > 2 && bin_residual > item_size + 30 {
        score += 3.0;
    }

    // Global state: if mean residual is large, prefer reusing bins over opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless item is large and no good reuse exists.
        let pressure = mean_residual < item_size as f64 * 1.2 || fitting_bins_count == 0;
        if pressure {
            score -= 8.0;
        } else {
            score += 12.0 + mean_residual * 0.1;
        }
    } else {
        // Reuse bonus grows with open bins count (encourage consolidation).
        score -= (open_bins_count.min(20) as f64) * 0.3;
    }

    // Time horizon: early in stream, be conservative (penalize waste); later, allow slack.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual (tight packing)
    let mut score = post;

    // Non-linear penalty on dead space: squared normalized residual
    let norm_post = post / cap;
    score += 30.0 * norm_post * norm_post;

    // Tight-fit reward: strongly favor near-perfect fills
    let tightness = 1.0 - (post / cap);
    score -= 25.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress);
        score -= 20.0 * progress;
    }

    // New-bin candidate handling: penalize opening a new bin, especially
    // when the item would leave large residual or when many bins are open
    if bin_residual == bin_capacity {
        let waste = (cap - item) / cap;
        score += 35.0 * (1.0 - waste * waste);
        score += 10.0 * (open_bins_count as f64).sqrt();
        // Early stream: prefer consolidating into open bins
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead coupling: if next item could use this bin's post-residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = 1.0 - ((post - nxt) / cap);
            score -= 18.0 * fit_quality * fit_quality;
        } else {
            // post-residual too small for next item: penalize unusable sliver
            score += 8.0 * (1.0 - post / cap) * (1.0 - progress);
        }
    }

    // Interaction: mean residual vs post residual — avoid fragmenting spread
    let dev = (post - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Mild reward for placing into bins with less residual than average
    score -= 3.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
