    // Harmonic class of the post residual: residuals divisible by large powers
    // of small integers remain reusable by future items.
    let mut h = 0u32;
    let mut r = post_residual;
    while r > 0 && r % 2 == 0 { h += 1; r /= 2; }
    let mut h5 = 0u32;
    let mut r5 = post_residual;
    while r5 > 0 && r5 % 5 == 0 { h5 += 1; r5 /= 5; }
    let harmonic = h.max(h5) as f64;

    // Reward residuals in "friendly" classes: multiples of 10 and 20 are
    // highly reusable given typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 50 == 0 { score -= 5.0; }
    }
    score -= 2.0 * harmonic;

    // Penalize dead space: small nonzero residuals are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 6.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // this bin is very valuable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 { score -= 8.0; }
            if slack < 10 { score += 5.0; }
        } else {
            // next item won't fit here; slight penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.05 * gap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early with plenty of room expected.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        // Opening a new bin is penalized when many bins are open and mean residual is large.
        let penalty = 8.0 + 0.5 * open_pressure + 10.0 * (mean_residual / bin_capacity as f64);
        let bonus = 30.0 * (1.0 - progress);
        score = penalty - bonus + (bin_capacity - item_size) as f64;
    }

    // Mild pressure to prefer tighter bins when many bins are open.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item are "dead space" — penalize them hard.
    let dead_threshold = 10.0; // smallest item size in classic streams
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward near-perfect fits (post_residual very small but nonzero).
    if post_residual <= 3 {
        score -= 15.0;
    }

    // Penalize large leftover space only mildly (best-fit baseline already
    // prefers small residuals); add mild coupling with mean residual:
    // prefer bins whose residual deviates below the mean (tighter bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Open-bin pressure: when many bins are open, discourage opening new
    // ones (the new-bin candidate has bin_residual == bin_capacity, so it
    // gets a large post_residual and this term applies to it strongly).
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor
    // using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 18.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use the leftover: leftover is likely dead space
        score += 0.05 * post_residual as f64;
    }

    // Mild progression term: later in the stream, be slightly more
    // conservative about leaving gaps (consolidation phase).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.10 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary objective: minimize wasted post residual.
    // Aggressive 2-step lookahead: strongly reward bins where the NEXT item
    // fits exactly (post_residual == next_item_size), mildly when it fits.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step pairing: fill bin completely with next item.
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to tightness of pair.
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 12.0 - pair_waste * 0.25;
        } else {
            // Next item cannot follow: penalize, worse if residual is small/dead.
            score += 6.0 + (next_item_size as f64 - post_residual as f64) * 0.05;
        }
    }

    // Reward tight fits relative to mean residual across open bins.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.15;
    } else {
        score += (res - mean_residual) * 0.10;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins could still host reasonably.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus escalation with stream progress
        // (later in the stream, consolidating matters more) and number of bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 10.0 * progress + 0.05 * open_bins_count as f64;
        // A new bin is attractive only if no open bin fits well:
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild penalty for very small dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small relative to item size.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 18.0 * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Bonus for chained fit (next item leaves a still-usable remainder).
            let chain_left = post_residual - next_item_size;
            if chain_left >= 10 {
                score -= 4.0;
            }
        } else if next_item_size > bin_residual {
            // Next item won't fit here anyway; residual waste matters less.
            score -= 3.0;
        } else {
            // Next item would fit this bin but not after our placement: penalize.
            score += 10.0;
        }
    } else {
        // Last item: minimize leftover aggressively.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: discourage spreading, favor filling existing bins.
    let pressure = (open_bins_count as f64) / ((total_items.max(1) as f64).sqrt() + 1.0);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: bins far below mean residual are "wasteful" to fill lightly.
    if (bin_residual as f64) > mean_residual * 1.4 {
        score += 6.0;
    } else if (bin_residual as f64) < mean_residual * 0.7 {
        score -= 5.0;
    }

    // Time horizon: early in the stream, be conservative about tiny residuals;
    // late in the stream, squeeze bins hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.15;
    score -= progress * 8.0 * tightness;

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; offset when current bins are fragmented.
        let fragmentation = mean_residual / bin_capacity as f64;
        score = (bin_capacity as f64) * 0.9
            - 30.0 * fragmentation
            - (if fitting_bins_count <= 1 { 40.0 } else { 0.0 });
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Base: prefer small post_residual (tight fit), with non-linear sharpening.
    let mut score = pr + 25.0 * prn * prn * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly.
    let coupling = 1.0 + 1.5 * progress * progress + 2.0 * progress * prn;
    score *= coupling;

    // Penalize bins whose residual is far from the mean (imbalance), smoothly.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * cap;

    // Reward last-chance bins (fitting_bins_count == 1) smoothly.
    if fitting_bins_count <= 1 {
        score -= 6.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits into post_residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_ratio = nxt / pr.max(1.0);
            score -= 10.0 * fit_ratio * (1.0 - prn);
        } else {
            // Smooth penalty when next item cannot use the leftover space.
            let gap = (nxt - pr) / cap;
            score += 5.0 * gap * cap;
        }
    }

    // Mild preference for keeping fewer open bins, fading as stream progresses.
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress);

    // Brand-new bin candidate: only attractive when it enables a great fit for the
    // lookahead item (smooth reward), otherwise penalized.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            let pair = item_size as f64 + next_item_size as f64;
            if pair <= cap {
                score -= 4.0 * (1.0 - pair / cap) * (1.0 - progress);
            } else {
                score += 3.0;
            }
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity fraction buckets.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Exact-fit reward: dead space zero is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class logic: post_residual in {0, 10, 20, 25, 50} are
    // "usable" residual classes likely to host future items.
    let harmonic = post_residual % 10 == 0 || post_residual % 25 == 0;
    if harmonic {
        score -= 8.0;
    } else if post_residual > 0 {
        // Penalize awkward slivers (dead space) more than linear term.
        score += (10.0 - frac * 10.0).max(0.0);
    }

    // Lookahead coupling: reward if next item fits into post residual,
    // extra reward when it lands exactly on a harmonic class.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 12.0;
            if post_residual % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            score += 5.0;
        }
        // Integer division threshold: post_residual / next_item_size >= 2
        // means the bin could host the next item class twice.
        if next_item_size > 0 && (post_residual / next_item_size.max(1)) >= 2 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so it is only chosen when all
    // open bins would create bad fits; reward scales with stream progress
    // and how fragmented the open bins already are.
    if bin_residual == bin_capacity {
        score = cap - pr + 15.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / cap - 0.5).abs();
        score -= 20.0 * progress * fragmentation;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Tie-break: prefer fuller bins (low residual) among open bins.
    score += (bin_residual as f64 / cap) * 3.0;

    // Mild penalty when many bins fit item but this one is wasteful.
    if fitting_bins_count > 1 && post_residual > bin_capacity / 2 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10] are unusable for any
    // future item (min item size 1..100, but typical small fragments waste space).
    // Penalize gaps that are too small to be useful.
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 * (1.0 - post_residual as f64 / 20.0);
    }
    // Perfect fit heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate (empty bin): penalize so we only open new bins when
    // existing fits are genuinely poor (large dead space would result).
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if next item is large and no open bin will hold both, opening fresh
        // is fine: soften penalty.
        if next_item_size as f64 > mean_residual {
            score -= 20.0;
        }
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 35.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item can't use the leftover -> dead space likely; penalize.
        score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual is already below average (consolidating waste).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits exactly or well in the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // chain fit: excellent
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving medium dead space.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 && dead > 0.0 {
                score += 10.0 * (dead / next_item_size as f64);
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * progress;
        // But if open bins have large mean residual (fragmented), new bin is less bad.
        score -= 10.0 * (mean_residual / bin_capacity as f64);
        // Few open bins: opening is cheaper.
        if open_bins_count < 3 {
            score -= 15.0;
        }
        // If item is large relative to capacity, prefer fresh bin to avoid fragmentation.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Prefer filling bins that already have more content (larger item_size relative to residual).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fill_ratio;

    // Global balance: prefer bins whose residual is close to mean residual (even filling),
    // unless it's a tight fit case already rewarded.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post residual), with a smooth convex penalty.
    let mut score = norm_post * norm_post * 60.0 + norm_post * 40.0;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, waste matters more; early on, spreading is cheaper.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Interaction: post residual vs mean residual — penalize bins that leave
    // post-residual far from the fleet mean (fragmentation signal).
    let norm_mean = mean_residual / cap;
    let spread = norm_post - norm_mean;
    score += 25.0 * spread * spread;

    // Lookahead coupling: reward if next item fits the post residual (smooth term).
    if next_item_size > 0 {
        let fits_next = (post - next_item_size as f64).max(0.0) / cap;
        score += 30.0 * fits_next * fits_next;
        let exact = 1.0 - (post - next_item_size as f64).abs() / cap;
        score -= 15.0 * exact.max(0.0) * (1.0 - progress);
    }

    // Last-chance bonus: only one bin fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 80.0 * (1.0 - 0.5 * progress);
    } else {
        // Mild penalty when many bins fit, to keep some bins tight.
        score += 4.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: smooth penalty that grows with progress and shrinks
    // if the item is large relative to capacity (big items justify new bins).
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        score = cap * (1.2 + 1.5 * progress * progress) - 60.0 * size_frac * size_frac;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "friendly"
    // to the item-size universe (multiples of small divisors are re-usable).
    let pr = post_residual;
    if pr > 0 {
        let mut harmonic_bonus = 0.0;
        for d in [5u32, 10, 20, 25, 50] {
            if pr % d == 0 {
                harmonic_bonus += 6.0;
            }
        }
        score -= harmonic_bonus;
        // Dead-space penalty grows for small odd residuals (hard to fill).
        if pr % 2 == 1 && pr < 20 {
            score += 15.0;
        }
        // Very small residual = near-perfect fit, strong reward.
        if pr <= 5 {
            score -= 30.0;
        } else if pr <= 10 {
            score -= 12.0;
        }
    } else {
        // Perfect closure of the bin.
        score -= 60.0;
    }

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-friendly: next item can land here.
            score -= 10.0 + (next_item_size as f64) * 0.2;
            // Extra reward if post_residual matches next item exactly.
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Post-residual too small for lookahead: dead space risk.
            score += 8.0 + (next_item_size as f64) * 0.1;
        }
    }

    // Last-chance bin: strongly prefer using it before opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here would be terrible.
    if bin_residual == bin_capacity {
        let tightness = mean_residual / bin_capacity as f64;
        // Penalize new bins mildly; escalate penalty if many bins are open
        // and their mean residual is still large.
        score += 25.0 + open_bins_count as f64 * 2.0 + tightness * 30.0;
        // But if the item is huge relative to capacity, opening fresh is fine.
        if item_size > bin_capacity * 3 / 4 {
            score -= 20.0;
        }
        // Early in stream, new bins are cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    }

    // Tightness of this particular fit: fraction of bin consumed now.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Prefer bins whose residual is far from mean (deviant bins get used up
    // first to homogenize the pool).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Integer-division threshold: residuals in (0,10] are "junk class".
    if pr > 0 && pr / 10 == 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly useless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // dead space, unusable for any item
        } else if post_residual <= 20 {
            score += 25.0;
        }
    } else {
        score -= 40.0; // perfect fit
    }

    // Reward tight fits relative to item size.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Lookahead: leaving room for the next item is valuable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 10.0;
        }
    }

    // Pressure on number of open bins: prefer filling existing bins
    // when many bins are open.
    score += open_bins_count as f64 * 1.5;

    // Last chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with below-average residual (pack fuller bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect pair fill
        } else if post_residual > next_item_size {
            // next item fits with some slack left
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item would not fit here: penalize proportionally to mismatch
            let miss = (next_item_size - post_residual) as f64;
            score += 8.0 * (miss / bin_capacity as f64);
        }
    } else {
        // last item: prefer minimal post residual
        score += 0.0;
    }

    // Compare post_residual relative to mean residual: leaving far-below-average
    // residual wastes space; leaving above-average residual is fine.
    let cap = bin_capacity as f64;
    let dev = (post_residual as f64 - mean_residual) / cap;
    if dev < 0.0 {
        score += 6.0 * dev; // penalize below-mean residuals (dead space)
    } else {
        score -= 2.0 * dev; // mild reward for above-mean residual
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Discourage opening a new bin when a decent fit exists in an open bin
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus penalty scaled by how well the
        // item would fill the fresh bin
        score += 20.0;
        if next_item_size > 0 {
            let pair_fill = (item_size + next_item_size) as f64 / cap;
            score -= 15.0 * pair_fill.min(1.0);
        }
        // early in stream, opening bins is cheaper (build diversity)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Tight fits are valuable regardless of lookahead
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 5.0 * tightness * tightness;

    // Slight preference for bins with larger residual (less packed) when
    // many bins are open, to preserve tight bins for tight items
    if open_bins_count > 4 {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}
